INSERT INTO plugins (name, version, title, status, manifest_json, binding_json, report_json, installed_at, updated_at)
VALUES ('daily-planner', '1.0.1', 'Daily Planner', 'active', '{"nyyon_plugin":2,"name":"daily-planner","title":"Daily Planner","version":"1.0.1","description":"Planning workspace: a guided chat produces a persisted, editable day plan (Focus Sessions + to-dos), with weekly objectives, history search and day time-travel. Full module-as-plugin: seven tools, the persona knowledge doc, and the real two-pane page.","origin":{"system":"nyyon-app"},"requires":{"gateways":[],"knowledge":[{"slug":"kpi-outreach","purpose":"the operator timezone + workweek days that anchor ''today'' and the week''s Sunday"}],"tables":[{"name":"plugin_daily_planner_plans","ddl":"CREATE TABLE IF NOT EXISTS plugin_daily_planner_plans (date TEXT PRIMARY KEY, plan TEXT NOT NULL, mode TEXT NOT NULL DEFAULT ''wing_it'', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL)"},{"name":"plugin_daily_planner_objectives","ddl":"CREATE TABLE IF NOT EXISTS plugin_daily_planner_objectives (week_start TEXT PRIMARY KEY, objectives TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL)"}]},"provides":{"tools":[{"name":"read_daily_plan","def":{"name":"read_daily_plan","description":"Read one day''s plan (schedule blocks + to-dos). date is YYYY-MM-DD, default today. Call this before editing a day or to see what is already planned.","input_schema":{"type":"object","properties":{"date":{"type":"string","description":"YYYY-MM-DD; default today"}},"required":[]}},"code":"// Daily Planner plugin — read_daily_plan. Ported verbatim from the host module;\n// every host import replaced by the capability object (api.db is scoped to the\n// plugin_daily_planner_* tables, api.knowledge to the declared read set).\n\nexport const def = {\n  name: ''read_daily_plan'',\n  description: \"Read one day''s plan (schedule blocks + to-dos). date is YYYY-MM-DD, default today. Call this before editing a day or to see what is already planned.\",\n  input_schema: { type: ''object'', properties: { date: { type: ''string'', description: ''YYYY-MM-DD; default today'' } }, required: [] },\n};\n\n// kpi-outreach is the host note holding the operator timezone + workweek —\n// declared in requires.knowledge so the read is visible at import time.\nconst KPI_DEFAULTS = { tz: ''UTC'', work_days: [0, 1, 2, 3, 4] };\n// Smaller models (and any model under pressure) routinely pass an array\n// parameter as a JSON STRING. Treating that as \"not an array\" saved an EMPTY\n// plan and reported success, which is worse than an error: the operator sees\n// a blank day and no reason. Parse the string, then carry on.\nfunction asArray(v) {\n  if (Array.isArray(v)) return v;\n  if (typeof v === ''string'') {\n    const t = v.trim();\n    if (!t) return [];\n    try { const p = JSON.parse(t); return Array.isArray(p) ? p : [p]; } catch { return []; }\n  }\n  if (v && typeof v === ''object'') return [v];\n  return [];\n}\nasync function kpiCfg(api) {\n  try {\n    const doc = await api.knowledge(''kpi-outreach'');\n    const m = String(doc?.body || '''').match(/```json\\s*([\\s\\S]*?)```/);\n    const cfg = m ? JSON.parse(m[1]) : null;\n    return cfg && typeof cfg === ''object'' ? { ...KPI_DEFAULTS, ...cfg } : KPI_DEFAULTS;\n  } catch { return KPI_DEFAULTS; }\n}\nasync function todayLocal(api) {\n  const cfg = await kpiCfg(api);\n  try { return new Date().toLocaleDateString(''en-CA'', { timeZone: cfg.tz || ''UTC'' }); }\n  catch { return new Date().toISOString().slice(0, 10); }\n}\nfunction normalizePlanBody(plan = {}) {\n  const schedule = asArray(plan.schedule).map((b, i) => ({\n    id: b.id || `b${i + 1}`,\n    start: b.start ? String(b.start).slice(0, 10) : null,\n    end: b.end ? String(b.end).slice(0, 10) : null,\n    title: String(b.title || '''').slice(0, 400),\n    deliverable: b.deliverable ? String(b.deliverable).slice(0, 400) : null,\n    done: !!b.done,\n    focus: !!b.focus,\n  }));\n  const todos = asArray(plan.todos).map((tk, i) => ({\n    id: tk.id || `t${i + 1}`,\n    text: String(tk.text || '''').slice(0, 400),\n    done: !!tk.done,\n    star: !!tk.star,\n    priority: Number.isFinite(tk.priority) ? tk.priority : i + 1,\n  }));\n  return {\n    summary: String(plan.summary || '''').slice(0, 1000),\n    weekly_ref: plan.weekly_ref ? String(plan.weekly_ref).slice(0, 10) : null,\n    schedule,\n    todos,\n  };\n}\nfunction rowToPlan(row) {\n  if (!row) return null;\n  let body = {};\n  try { body = JSON.parse(row.plan || ''{}''); } catch { body = {}; }\n  const norm = normalizePlanBody(body);\n  return {\n    date: row.date, mode: row.mode || body.mode || ''wing_it'',\n    summary: norm.summary, weekly_ref: norm.weekly_ref,\n    schedule: norm.schedule, todos: norm.todos,\n    created_at: row.created_at, updated_at: row.updated_at,\n  };\n}\nasync function readPlan(api, date) {\n  const row = await api.db\n    .prepare(''SELECT date, plan, mode, created_at, updated_at FROM plugin_daily_planner_plans WHERE date = ?'')\n    .bind(date).first();\n  return rowToPlan(row);\n}\n\nexport async function run(api, input) {\n  const date = input?.date || (await todayLocal(api));\n  const plan = await readPlan(api, date);\n  return plan ? { date, plan } : { date, plan: null, note: ''no plan yet for this day'' };\n}\n"},{"name":"save_daily_plan","def":{"name":"save_daily_plan","description":"Write (or replace) a day''s plan — this is what fills the plan panel. schedule = time blocks [{start:''HH:MM'', end:''HH:MM'', title, deliverable, focus}]. Mark each ~2-hour FOCUS SESSION block focus:true (the operator says how many fit in a day) — those are the day''s backbone; supporting blocks are focus:false. todos = [{text, priority, star}], star:true for the extra-important few. mode ''strategic'' (aligned to the week''s objectives, set weekly_ref = that week''s Sunday) or ''wing_it''. date defaults to today. Replaces the whole plan; use update_daily_plan to change part of one.","input_schema":{"type":"object","properties":{"date":{"type":"string","description":"YYYY-MM-DD; default today"},"mode":{"type":"string","enum":["strategic","wing_it"]},"summary":{"type":"string","description":"one line on what this day is about"},"weekly_ref":{"type":"string","description":"the aligned week''s Sunday (YYYY-MM-DD), strategic mode"},"schedule":{"type":"array","items":{"type":"object"},"description":"time blocks, each with a concrete deliverable"},"todos":{"type":"array","items":{"type":"object"},"description":"checklist items"}},"required":["schedule"]}},"code":"// Daily Planner plugin — save_daily_plan. Ported verbatim from the host module;\n// every host import replaced by the capability object (api.db is scoped to the\n// plugin_daily_planner_* tables, api.knowledge to the declared read set).\n\nexport const def = {\n  name: ''save_daily_plan'',\n  description: \"Write (or replace) a day''s plan — this is what fills the plan panel. schedule = time blocks [{start:''HH:MM'', end:''HH:MM'', title, deliverable, focus}]. Mark each ~2-hour FOCUS SESSION block focus:true (the operator says how many fit in a day) — those are the day''s backbone; supporting blocks are focus:false. todos = [{text, priority, star}], star:true for the extra-important few. mode ''strategic'' (aligned to the week''s objectives, set weekly_ref = that week''s Sunday) or ''wing_it''. date defaults to today. Replaces the whole plan; use update_daily_plan to change part of one.\",\n  input_schema: {\n    type: ''object'',\n    properties: {\n      date: { type: ''string'', description: ''YYYY-MM-DD; default today'' },\n      mode: { type: ''string'', enum: [''strategic'', ''wing_it''] },\n      summary: { type: ''string'', description: ''one line on what this day is about'' },\n      weekly_ref: { type: ''string'', description: \"the aligned week''s Sunday (YYYY-MM-DD), strategic mode\" },\n      schedule: { type: ''array'', items: { type: ''object'' }, description: ''time blocks, each with a concrete deliverable'' },\n      todos: { type: ''array'', items: { type: ''object'' }, description: ''checklist items'' },\n    },\n    required: [''schedule''],\n  },\n};\n\n// kpi-outreach is the host note holding the operator timezone + workweek —\n// declared in requires.knowledge so the read is visible at import time.\nconst KPI_DEFAULTS = { tz: ''UTC'', work_days: [0, 1, 2, 3, 4] };\n// Smaller models (and any model under pressure) routinely pass an array\n// parameter as a JSON STRING. Treating that as \"not an array\" saved an EMPTY\n// plan and reported success, which is worse than an error: the operator sees\n// a blank day and no reason. Parse the string, then carry on.\nfunction asArray(v) {\n  if (Array.isArray(v)) return v;\n  if (typeof v === ''string'') {\n    const t = v.trim();\n    if (!t) return [];\n    try { const p = JSON.parse(t); return Array.isArray(p) ? p : [p]; } catch { return []; }\n  }\n  if (v && typeof v === ''object'') return [v];\n  return [];\n}\nasync function kpiCfg(api) {\n  try {\n    const doc = await api.knowledge(''kpi-outreach'');\n    const m = String(doc?.body || '''').match(/```json\\s*([\\s\\S]*?)```/);\n    const cfg = m ? JSON.parse(m[1]) : null;\n    return cfg && typeof cfg === ''object'' ? { ...KPI_DEFAULTS, ...cfg } : KPI_DEFAULTS;\n  } catch { return KPI_DEFAULTS; }\n}\nasync function todayLocal(api) {\n  const cfg = await kpiCfg(api);\n  try { return new Date().toLocaleDateString(''en-CA'', { timeZone: cfg.tz || ''UTC'' }); }\n  catch { return new Date().toISOString().slice(0, 10); }\n}\nfunction normalizePlanBody(plan = {}) {\n  const schedule = asArray(plan.schedule).map((b, i) => ({\n    id: b.id || `b${i + 1}`,\n    start: b.start ? String(b.start).slice(0, 10) : null,\n    end: b.end ? String(b.end).slice(0, 10) : null,\n    title: String(b.title || '''').slice(0, 400),\n    deliverable: b.deliverable ? String(b.deliverable).slice(0, 400) : null,\n    done: !!b.done,\n    focus: !!b.focus,\n  }));\n  const todos = asArray(plan.todos).map((tk, i) => ({\n    id: tk.id || `t${i + 1}`,\n    text: String(tk.text || '''').slice(0, 400),\n    done: !!tk.done,\n    star: !!tk.star,\n    priority: Number.isFinite(tk.priority) ? tk.priority : i + 1,\n  }));\n  return {\n    summary: String(plan.summary || '''').slice(0, 1000),\n    weekly_ref: plan.weekly_ref ? String(plan.weekly_ref).slice(0, 10) : null,\n    schedule,\n    todos,\n  };\n}\nfunction rowToPlan(row) {\n  if (!row) return null;\n  let body = {};\n  try { body = JSON.parse(row.plan || ''{}''); } catch { body = {}; }\n  const norm = normalizePlanBody(body);\n  return {\n    date: row.date, mode: row.mode || body.mode || ''wing_it'',\n    summary: norm.summary, weekly_ref: norm.weekly_ref,\n    schedule: norm.schedule, todos: norm.todos,\n    created_at: row.created_at, updated_at: row.updated_at,\n  };\n}\nasync function readPlan(api, date) {\n  const row = await api.db\n    .prepare(''SELECT date, plan, mode, created_at, updated_at FROM plugin_daily_planner_plans WHERE date = ?'')\n    .bind(date).first();\n  return rowToPlan(row);\n}\nasync function savePlan(api, { date, plan = {}, mode }) {\n  const t = Date.now();\n  const m = mode || plan.mode || ''wing_it'';\n  const body = normalizePlanBody(plan);\n  await api.db.prepare(\n    `INSERT INTO plugin_daily_planner_plans (date, plan, mode, created_at, updated_at) VALUES (?,?,?,?,?)\n     ON CONFLICT(date) DO UPDATE SET plan = excluded.plan, mode = excluded.mode, updated_at = excluded.updated_at`,\n  ).bind(date, JSON.stringify({ mode: m, ...body }), m, t, t).run();\n  await api.log(''plan_saved'', { date, mode: m, blocks: body.schedule.length, todos: body.todos.length });\n  return readPlan(api, date);\n}\n\nexport async function run(api, input) {\n  const date = input?.date || (await todayLocal(api));\n  const plan = await savePlan(api, { date, plan: input, mode: input?.mode });\n  return { date, plan };\n}\n"},{"name":"update_daily_plan","def":{"name":"update_daily_plan","description":"Edit part of a day''s plan during the day (tick a block or to-do done, add a to-do, shift the schedule). Pass ONLY the keys you are changing; everything else is kept as-is. date defaults to today.","input_schema":{"type":"object","properties":{"date":{"type":"string","description":"YYYY-MM-DD; default today"},"mode":{"type":"string","enum":["strategic","wing_it"]},"summary":{"type":"string"},"weekly_ref":{"type":"string"},"schedule":{"type":"array","items":{"type":"object"}},"todos":{"type":"array","items":{"type":"object"}}},"required":[]}},"code":"// Daily Planner plugin — update_daily_plan. Ported verbatim from the host module;\n// every host import replaced by the capability object (api.db is scoped to the\n// plugin_daily_planner_* tables, api.knowledge to the declared read set).\n\nexport const def = {\n  name: ''update_daily_plan'',\n  description: \"Edit part of a day''s plan during the day (tick a block or to-do done, add a to-do, shift the schedule). Pass ONLY the keys you are changing; everything else is kept as-is. date defaults to today.\",\n  input_schema: {\n    type: ''object'',\n    properties: {\n      date: { type: ''string'', description: ''YYYY-MM-DD; default today'' },\n      mode: { type: ''string'', enum: [''strategic'', ''wing_it''] },\n      summary: { type: ''string'' },\n      weekly_ref: { type: ''string'' },\n      schedule: { type: ''array'', items: { type: ''object'' } },\n      todos: { type: ''array'', items: { type: ''object'' } },\n    },\n    required: [],\n  },\n};\n\n// kpi-outreach is the host note holding the operator timezone + workweek —\n// declared in requires.knowledge so the read is visible at import time.\nconst KPI_DEFAULTS = { tz: ''UTC'', work_days: [0, 1, 2, 3, 4] };\n// Smaller models (and any model under pressure) routinely pass an array\n// parameter as a JSON STRING. Treating that as \"not an array\" saved an EMPTY\n// plan and reported success, which is worse than an error: the operator sees\n// a blank day and no reason. Parse the string, then carry on.\nfunction asArray(v) {\n  if (Array.isArray(v)) return v;\n  if (typeof v === ''string'') {\n    const t = v.trim();\n    if (!t) return [];\n    try { const p = JSON.parse(t); return Array.isArray(p) ? p : [p]; } catch { return []; }\n  }\n  if (v && typeof v === ''object'') return [v];\n  return [];\n}\nasync function kpiCfg(api) {\n  try {\n    const doc = await api.knowledge(''kpi-outreach'');\n    const m = String(doc?.body || '''').match(/```json\\s*([\\s\\S]*?)```/);\n    const cfg = m ? JSON.parse(m[1]) : null;\n    return cfg && typeof cfg === ''object'' ? { ...KPI_DEFAULTS, ...cfg } : KPI_DEFAULTS;\n  } catch { return KPI_DEFAULTS; }\n}\nasync function todayLocal(api) {\n  const cfg = await kpiCfg(api);\n  try { return new Date().toLocaleDateString(''en-CA'', { timeZone: cfg.tz || ''UTC'' }); }\n  catch { return new Date().toISOString().slice(0, 10); }\n}\nfunction normalizePlanBody(plan = {}) {\n  const schedule = asArray(plan.schedule).map((b, i) => ({\n    id: b.id || `b${i + 1}`,\n    start: b.start ? String(b.start).slice(0, 10) : null,\n    end: b.end ? String(b.end).slice(0, 10) : null,\n    title: String(b.title || '''').slice(0, 400),\n    deliverable: b.deliverable ? String(b.deliverable).slice(0, 400) : null,\n    done: !!b.done,\n    focus: !!b.focus,\n  }));\n  const todos = asArray(plan.todos).map((tk, i) => ({\n    id: tk.id || `t${i + 1}`,\n    text: String(tk.text || '''').slice(0, 400),\n    done: !!tk.done,\n    star: !!tk.star,\n    priority: Number.isFinite(tk.priority) ? tk.priority : i + 1,\n  }));\n  return {\n    summary: String(plan.summary || '''').slice(0, 1000),\n    weekly_ref: plan.weekly_ref ? String(plan.weekly_ref).slice(0, 10) : null,\n    schedule,\n    todos,\n  };\n}\nfunction rowToPlan(row) {\n  if (!row) return null;\n  let body = {};\n  try { body = JSON.parse(row.plan || ''{}''); } catch { body = {}; }\n  const norm = normalizePlanBody(body);\n  return {\n    date: row.date, mode: row.mode || body.mode || ''wing_it'',\n    summary: norm.summary, weekly_ref: norm.weekly_ref,\n    schedule: norm.schedule, todos: norm.todos,\n    created_at: row.created_at, updated_at: row.updated_at,\n  };\n}\nasync function readPlan(api, date) {\n  const row = await api.db\n    .prepare(''SELECT date, plan, mode, created_at, updated_at FROM plugin_daily_planner_plans WHERE date = ?'')\n    .bind(date).first();\n  return rowToPlan(row);\n}\nasync function savePlan(api, { date, plan = {}, mode }) {\n  const t = Date.now();\n  const m = mode || plan.mode || ''wing_it'';\n  const body = normalizePlanBody(plan);\n  await api.db.prepare(\n    `INSERT INTO plugin_daily_planner_plans (date, plan, mode, created_at, updated_at) VALUES (?,?,?,?,?)\n     ON CONFLICT(date) DO UPDATE SET plan = excluded.plan, mode = excluded.mode, updated_at = excluded.updated_at`,\n  ).bind(date, JSON.stringify({ mode: m, ...body }), m, t, t).run();\n  await api.log(''plan_saved'', { date, mode: m, blocks: body.schedule.length, todos: body.todos.length });\n  return readPlan(api, date);\n}\n\nexport async function run(api, input) {\n  const { date: rawDate, ...patch } = input || {};\n  const date = rawDate || (await todayLocal(api));\n  const cur = await readPlan(api, date);\n  if (!cur) return { date, plan: await savePlan(api, { date, plan: patch, mode: patch.mode }) };\n  const merged = {\n    summary: patch.summary !== undefined ? patch.summary : cur.summary,\n    weekly_ref: patch.weekly_ref !== undefined ? patch.weekly_ref : cur.weekly_ref,\n    schedule: patch.schedule !== undefined ? patch.schedule : cur.schedule,\n    todos: patch.todos !== undefined ? patch.todos : cur.todos,\n  };\n  const plan = await savePlan(api, { date, plan: merged, mode: patch.mode || cur.mode });\n  return { date, plan };\n}\n"},{"name":"search_daily_plans","def":{"name":"search_daily_plans","description":"Search past daily plans by text (matches the summary, the to-dos and the blocks). Use it to recall or reuse an earlier day. An empty query returns the most recent plans.","input_schema":{"type":"object","properties":{"query":{"type":"string"},"limit":{"type":"number","description":"default 20, max 100"}},"required":[]}},"code":"// Daily Planner plugin — search_daily_plans. Ported verbatim from the host module;\n// every host import replaced by the capability object (api.db is scoped to the\n// plugin_daily_planner_* tables, api.knowledge to the declared read set).\n\nexport const def = {\n  name: ''search_daily_plans'',\n  description: ''Search past daily plans by text (matches the summary, the to-dos and the blocks). Use it to recall or reuse an earlier day. An empty query returns the most recent plans.'',\n  input_schema: { type: ''object'', properties: { query: { type: ''string'' }, limit: { type: ''number'', description: ''default 20, max 100'' } }, required: [] },\n};\n\n// Smaller models (and any model under pressure) routinely pass an array\n// parameter as a JSON STRING. Treating that as \"not an array\" saved an EMPTY\n// plan and reported success, which is worse than an error: the operator sees\n// a blank day and no reason. Parse the string, then carry on.\nfunction asArray(v) {\n  if (Array.isArray(v)) return v;\n  if (typeof v === ''string'') {\n    const t = v.trim();\n    if (!t) return [];\n    try { const p = JSON.parse(t); return Array.isArray(p) ? p : [p]; } catch { return []; }\n  }\n  if (v && typeof v === ''object'') return [v];\n  return [];\n}\nfunction normalizePlanBody(plan = {}) {\n  const schedule = asArray(plan.schedule).map((b, i) => ({\n    id: b.id || `b${i + 1}`,\n    start: b.start ? String(b.start).slice(0, 10) : null,\n    end: b.end ? String(b.end).slice(0, 10) : null,\n    title: String(b.title || '''').slice(0, 400),\n    deliverable: b.deliverable ? String(b.deliverable).slice(0, 400) : null,\n    done: !!b.done,\n    focus: !!b.focus,\n  }));\n  const todos = asArray(plan.todos).map((tk, i) => ({\n    id: tk.id || `t${i + 1}`,\n    text: String(tk.text || '''').slice(0, 400),\n    done: !!tk.done,\n    star: !!tk.star,\n    priority: Number.isFinite(tk.priority) ? tk.priority : i + 1,\n  }));\n  return {\n    summary: String(plan.summary || '''').slice(0, 1000),\n    weekly_ref: plan.weekly_ref ? String(plan.weekly_ref).slice(0, 10) : null,\n    schedule,\n    todos,\n  };\n}\nfunction rowToPlan(row) {\n  if (!row) return null;\n  let body = {};\n  try { body = JSON.parse(row.plan || ''{}''); } catch { body = {}; }\n  const norm = normalizePlanBody(body);\n  return {\n    date: row.date, mode: row.mode || body.mode || ''wing_it'',\n    summary: norm.summary, weekly_ref: norm.weekly_ref,\n    schedule: norm.schedule, todos: norm.todos,\n    created_at: row.created_at, updated_at: row.updated_at,\n  };\n}\nasync function readPlan(api, date) {\n  const row = await api.db\n    .prepare(''SELECT date, plan, mode, created_at, updated_at FROM plugin_daily_planner_plans WHERE date = ?'')\n    .bind(date).first();\n  return rowToPlan(row);\n}\n\nexport async function run(api, input) {\n  const q = String(input?.query || '''');\n  const like = `%${q.toLowerCase()}%`;\n  const lim = Math.min(Math.max(1, Number(input?.limit) || 20), 100);\n  const r = await api.db.prepare(\n    `SELECT date, plan, mode, created_at, updated_at FROM plugin_daily_planner_plans\n     WHERE ? = '''' OR LOWER(plan) LIKE ? ORDER BY date DESC LIMIT ?`,\n  ).bind(q, like, lim).all();\n  return { query: q, plans: (r.results || []).map(rowToPlan) };\n}\n"},{"name":"list_recent_plans","def":{"name":"list_recent_plans","description":"The most recent PAST daily plans, strictly before today (default the last 3). Call it at the start of planning to surface unfinished priorities and ask the operator what happened to each (done / carry over / drop).","input_schema":{"type":"object","properties":{"days":{"type":"number","description":"how many past plans, default 3"}},"required":[]}},"code":"// Daily Planner plugin — list_recent_plans. Ported verbatim from the host module;\n// every host import replaced by the capability object (api.db is scoped to the\n// plugin_daily_planner_* tables, api.knowledge to the declared read set).\n\nexport const def = {\n  name: ''list_recent_plans'',\n  description: ''The most recent PAST daily plans, strictly before today (default the last 3). Call it at the start of planning to surface unfinished priorities and ask the operator what happened to each (done / carry over / drop).'',\n  input_schema: { type: ''object'', properties: { days: { type: ''number'', description: ''how many past plans, default 3'' } }, required: [] },\n};\n\n// kpi-outreach is the host note holding the operator timezone + workweek —\n// declared in requires.knowledge so the read is visible at import time.\nconst KPI_DEFAULTS = { tz: ''UTC'', work_days: [0, 1, 2, 3, 4] };\n// Smaller models (and any model under pressure) routinely pass an array\n// parameter as a JSON STRING. Treating that as \"not an array\" saved an EMPTY\n// plan and reported success, which is worse than an error: the operator sees\n// a blank day and no reason. Parse the string, then carry on.\nfunction asArray(v) {\n  if (Array.isArray(v)) return v;\n  if (typeof v === ''string'') {\n    const t = v.trim();\n    if (!t) return [];\n    try { const p = JSON.parse(t); return Array.isArray(p) ? p : [p]; } catch { return []; }\n  }\n  if (v && typeof v === ''object'') return [v];\n  return [];\n}\nasync function kpiCfg(api) {\n  try {\n    const doc = await api.knowledge(''kpi-outreach'');\n    const m = String(doc?.body || '''').match(/```json\\s*([\\s\\S]*?)```/);\n    const cfg = m ? JSON.parse(m[1]) : null;\n    return cfg && typeof cfg === ''object'' ? { ...KPI_DEFAULTS, ...cfg } : KPI_DEFAULTS;\n  } catch { return KPI_DEFAULTS; }\n}\nasync function todayLocal(api) {\n  const cfg = await kpiCfg(api);\n  try { return new Date().toLocaleDateString(''en-CA'', { timeZone: cfg.tz || ''UTC'' }); }\n  catch { return new Date().toISOString().slice(0, 10); }\n}\nfunction normalizePlanBody(plan = {}) {\n  const schedule = asArray(plan.schedule).map((b, i) => ({\n    id: b.id || `b${i + 1}`,\n    start: b.start ? String(b.start).slice(0, 10) : null,\n    end: b.end ? String(b.end).slice(0, 10) : null,\n    title: String(b.title || '''').slice(0, 400),\n    deliverable: b.deliverable ? String(b.deliverable).slice(0, 400) : null,\n    done: !!b.done,\n    focus: !!b.focus,\n  }));\n  const todos = asArray(plan.todos).map((tk, i) => ({\n    id: tk.id || `t${i + 1}`,\n    text: String(tk.text || '''').slice(0, 400),\n    done: !!tk.done,\n    star: !!tk.star,\n    priority: Number.isFinite(tk.priority) ? tk.priority : i + 1,\n  }));\n  return {\n    summary: String(plan.summary || '''').slice(0, 1000),\n    weekly_ref: plan.weekly_ref ? String(plan.weekly_ref).slice(0, 10) : null,\n    schedule,\n    todos,\n  };\n}\nfunction rowToPlan(row) {\n  if (!row) return null;\n  let body = {};\n  try { body = JSON.parse(row.plan || ''{}''); } catch { body = {}; }\n  const norm = normalizePlanBody(body);\n  return {\n    date: row.date, mode: row.mode || body.mode || ''wing_it'',\n    summary: norm.summary, weekly_ref: norm.weekly_ref,\n    schedule: norm.schedule, todos: norm.todos,\n    created_at: row.created_at, updated_at: row.updated_at,\n  };\n}\nasync function readPlan(api, date) {\n  const row = await api.db\n    .prepare(''SELECT date, plan, mode, created_at, updated_at FROM plugin_daily_planner_plans WHERE date = ?'')\n    .bind(date).first();\n  return rowToPlan(row);\n}\n\nexport async function run(api, input) {\n  const cutoff = await todayLocal(api);\n  const lim = Math.min(Math.max(1, Number(input?.days) || 3), 30);\n  const r = await api.db.prepare(\n    `SELECT date, plan, mode, created_at, updated_at FROM plugin_daily_planner_plans\n     WHERE date < ? ORDER BY date DESC LIMIT ?`,\n  ).bind(cutoff, lim).all();\n  return { days: lim, before: cutoff, plans: (r.results || []).map(rowToPlan) };\n}\n"},{"name":"read_weekly_objectives","def":{"name":"read_weekly_objectives","description":"Read a week''s strategic objectives. week_start is that week''s Sunday (YYYY-MM-DD), or pass any `date` to have its workweek anchored for you; default is the current week. Read this in strategic mode before planning a day so the day points at the week.","input_schema":{"type":"object","properties":{"week_start":{"type":"string","description":"the week''s Sunday, YYYY-MM-DD; default this week"},"date":{"type":"string","description":"any day (YYYY-MM-DD) — its workweek is anchored server-side"}},"required":[]}},"code":"// Daily Planner plugin — read_weekly_objectives. Ported verbatim from the host module;\n// every host import replaced by the capability object (api.db is scoped to the\n// plugin_daily_planner_* tables, api.knowledge to the declared read set).\n\nexport const def = {\n  name: ''read_weekly_objectives'',\n  description: \"Read a week''s strategic objectives. week_start is that week''s Sunday (YYYY-MM-DD), or pass any `date` to have its workweek anchored for you; default is the current week. Read this in strategic mode before planning a day so the day points at the week.\",\n  input_schema: {\n    type: ''object'',\n    properties: {\n      week_start: { type: ''string'', description: \"the week''s Sunday, YYYY-MM-DD; default this week\" },\n      date: { type: ''string'', description: ''any day (YYYY-MM-DD) — its workweek is anchored server-side'' },\n    },\n    required: [],\n  },\n};\n\n// kpi-outreach is the host note holding the operator timezone + workweek —\n// declared in requires.knowledge so the read is visible at import time.\nconst KPI_DEFAULTS = { tz: ''UTC'', work_days: [0, 1, 2, 3, 4] };\nasync function kpiCfg(api) {\n  try {\n    const doc = await api.knowledge(''kpi-outreach'');\n    const m = String(doc?.body || '''').match(/```json\\s*([\\s\\S]*?)```/);\n    const cfg = m ? JSON.parse(m[1]) : null;\n    return cfg && typeof cfg === ''object'' ? { ...KPI_DEFAULTS, ...cfg } : KPI_DEFAULTS;\n  } catch { return KPI_DEFAULTS; }\n}\nasync function todayLocal(api) {\n  const cfg = await kpiCfg(api);\n  try { return new Date().toLocaleDateString(''en-CA'', { timeZone: cfg.tz || ''UTC'' }); }\n  catch { return new Date().toISOString().slice(0, 10); }\n}\nasync function weekAnchor(api, dateStr) {\n  const d = new Date(`${dateStr}T00:00:00Z`);\n  if (Number.isNaN(d.getTime())) return dateStr;\n  let lastWork = 4;\n  const cfg = await kpiCfg(api);\n  if (Array.isArray(cfg.work_days) && cfg.work_days.length) lastWork = Math.max(...cfg.work_days);\n  const wd = d.getUTCDay();\n  if (wd > lastWork) d.setUTCDate(d.getUTCDate() + (7 - wd));\n  else d.setUTCDate(d.getUTCDate() - wd);\n  return d.toISOString().slice(0, 10);\n}\nfunction rowToObjectives(row) {\n  if (!row) return null;\n  let objectives = [];\n  try { objectives = JSON.parse(row.objectives || ''[]''); } catch { objectives = []; }\n  if (!Array.isArray(objectives)) objectives = [];\n  return { week_start: row.week_start, objectives, created_at: row.created_at, updated_at: row.updated_at };\n}\nasync function readObjectives(api, weekStart) {\n  const row = await api.db\n    .prepare(''SELECT week_start, objectives, created_at, updated_at FROM plugin_daily_planner_objectives WHERE week_start = ?'')\n    .bind(weekStart).first();\n  return rowToObjectives(row);\n}\n\nexport async function run(api, input) {\n  const week_start = input?.week_start\n    || (await weekAnchor(api, input?.date || (await todayLocal(api))));\n  const row = await readObjectives(api, week_start);\n  return row\n    ? { week_start, objectives: row.objectives, created_at: row.created_at, updated_at: row.updated_at }\n    : { week_start, objectives: [], note: ''no objectives set for this week yet'' };\n}\n"},{"name":"set_weekly_objectives","def":{"name":"set_weekly_objectives","description":"Set a week''s strategic objectives — the 2-4 outcomes that move the business in the intended direction. objectives is a list of short outcome strings (or {text, done} objects) and REPLACES the week''s list. week_start defaults to the current week''s Sunday.","input_schema":{"type":"object","properties":{"objectives":{"type":"array","items":{"type":["string","object"]},"description":"short outcome strings, or {text, done}"},"week_start":{"type":"string","description":"the week''s Sunday, YYYY-MM-DD; default this week"}},"required":["objectives"]}},"code":"// Daily Planner plugin — set_weekly_objectives. Ported verbatim from the host module;\n// every host import replaced by the capability object (api.db is scoped to the\n// plugin_daily_planner_* tables, api.knowledge to the declared read set).\n\nexport const def = {\n  name: ''set_weekly_objectives'',\n  description: \"Set a week''s strategic objectives — the 2-4 outcomes that move the business in the intended direction. objectives is a list of short outcome strings (or {text, done} objects) and REPLACES the week''s list. week_start defaults to the current week''s Sunday.\",\n  input_schema: {\n    type: ''object'',\n    properties: {\n      objectives: { type: ''array'', items: { type: [''string'', ''object''] }, description: ''short outcome strings, or {text, done}'' },\n      week_start: { type: ''string'', description: \"the week''s Sunday, YYYY-MM-DD; default this week\" },\n    },\n    required: [''objectives''],\n  },\n};\n\n// kpi-outreach is the host note holding the operator timezone + workweek —\n// declared in requires.knowledge so the read is visible at import time.\nconst KPI_DEFAULTS = { tz: ''UTC'', work_days: [0, 1, 2, 3, 4] };\n// A model may pass this array as a JSON string; parse rather than silently\n// storing an empty week.\nfunction asArray(v) {\n  if (Array.isArray(v)) return v;\n  if (typeof v === ''string'') {\n    const t = v.trim();\n    if (!t) return [];\n    try { const p = JSON.parse(t); return Array.isArray(p) ? p : [p]; } catch { return [t]; }\n  }\n  if (v && typeof v === ''object'') return [v];\n  return [];\n}\nasync function kpiCfg(api) {\n  try {\n    const doc = await api.knowledge(''kpi-outreach'');\n    const m = String(doc?.body || '''').match(/```json\\s*([\\s\\S]*?)```/);\n    const cfg = m ? JSON.parse(m[1]) : null;\n    return cfg && typeof cfg === ''object'' ? { ...KPI_DEFAULTS, ...cfg } : KPI_DEFAULTS;\n  } catch { return KPI_DEFAULTS; }\n}\nasync function todayLocal(api) {\n  const cfg = await kpiCfg(api);\n  try { return new Date().toLocaleDateString(''en-CA'', { timeZone: cfg.tz || ''UTC'' }); }\n  catch { return new Date().toISOString().slice(0, 10); }\n}\nasync function weekAnchor(api, dateStr) {\n  const d = new Date(`${dateStr}T00:00:00Z`);\n  if (Number.isNaN(d.getTime())) return dateStr;\n  let lastWork = 4;\n  const cfg = await kpiCfg(api);\n  if (Array.isArray(cfg.work_days) && cfg.work_days.length) lastWork = Math.max(...cfg.work_days);\n  const wd = d.getUTCDay();\n  if (wd > lastWork) d.setUTCDate(d.getUTCDate() + (7 - wd));\n  else d.setUTCDate(d.getUTCDate() - wd);\n  return d.toISOString().slice(0, 10);\n}\nfunction rowToObjectives(row) {\n  if (!row) return null;\n  let objectives = [];\n  try { objectives = JSON.parse(row.objectives || ''[]''); } catch { objectives = []; }\n  if (!Array.isArray(objectives)) objectives = [];\n  return { week_start: row.week_start, objectives, created_at: row.created_at, updated_at: row.updated_at };\n}\nasync function readObjectives(api, weekStart) {\n  const row = await api.db\n    .prepare(''SELECT week_start, objectives, created_at, updated_at FROM plugin_daily_planner_objectives WHERE week_start = ?'')\n    .bind(weekStart).first();\n  return rowToObjectives(row);\n}\n\nexport async function run(api, input) {\n  const week_start = input?.week_start || (await weekAnchor(api, await todayLocal(api)));\n  const t = Date.now();\n  const norm = asArray(input?.objectives)\n    .map((o, i) => ({\n      id: (o && o.id) || `o${i + 1}`,\n      text: String((o && o.text) || o || '''').slice(0, 400),\n      done: !!(o && o.done),\n    }))\n    .filter((o) => o.text);\n  await api.db.prepare(\n    `INSERT INTO plugin_daily_planner_objectives (week_start, objectives, created_at, updated_at) VALUES (?,?,?,?)\n     ON CONFLICT(week_start) DO UPDATE SET objectives = excluded.objectives, updated_at = excluded.updated_at`,\n  ).bind(week_start, JSON.stringify(norm), t, t).run();\n  await api.log(''objectives_saved'', { week_start, count: norm.length });\n  const row = await readObjectives(api, week_start);\n  return { week_start, objectives: row?.objectives || [] };\n}\n"}],"workflows":[],"knowledge":[{"slug":"plugin-daily-planner-persona","title":"Daily Planner — planner persona (system prompt)","body":"You are the Daily Planner inside the Nyyon Command Center — a fast planning partner that turns a short conversation into a SAVED day plan in the panel beside this chat. You share Nyo''s tools. Be terse, ask ONE thing at a time, and draft as soon as you have enough.\n\nEach new day the chat + panel start empty. Ground yourself quietly first — call read_daily_plan (today) and read_weekly_objectives (this week) before your first reply. If today already has a plan, recap it in a line and ask what to change instead of re-asking.\n\nOtherwise, ask these FOUR things — in order, crisp, one at a time (pair two only if it''s natural), and STOP asking the moment you can draft:\n1. What do you want done today?\n2. Any constraints we should account for? (meetings, deadlines, energy, hours available)\n3. How many Focus Sessions can you fit today? Each is a ~2-hour deep-work block.\n4. Are we aligned with this week''s objectives? (You already read them; if none are set, offer to set 2-4 with set_weekly_objectives.)\n\nThen call save_daily_plan — this fills the panel:\n- Create exactly the number of FOCUS SESSION blocks the operator gave — ~2 hours each, focus:true, each with ONE concrete deliverable (what will exist when it''s done). These are the backbone of the day.\n- Place them around the stated constraints; add any other needed items as regular blocks (focus:false) to form the schedule.\n- List today''s to-dos as todos:[{text, star}] — star:true for the extra-important few.\n- mode ''strategic'' with weekly_ref (the week''s Sunday) if the day is aligned to the week''s objectives, else ''wing_it''.\n\nSay it''s a first cut, then refine with update_daily_plan (only the changed keys) — the panel updates live. Never claim you saved or changed the plan unless the tool returned success.\n\nThe plan is self-contained — it is NOT synced to the calendar or the task list right now, and you have no tools for those, so plan the day inside the schedule + to-dos only. Ask the operator about fixed commitments; don''t try to read or write a calendar or task list.\n\nSTYLE: terse, direct, plain — no marketing voice, no filler. This is the planning desk; keep general command-center work (deploys, writing, deep CRM) in Nyo."}],"surfaces":[{"slug":"planner","title":"Daily Planner","files":[{"path":"PlanPanel.tsx","code":"import { useCallback, useEffect, useRef, useState } from ''react'';\nimport { planner, type DailyPlan, type PlanBlock, type PlanTodo, type WeeklyObjective, type WeeklyObjectives } from ''./data'';\nimport { Search, X, MessageSquare, Menu } from ''../../components/Icons'';\n\n// The plan surface of the Daily Planner workspace — the main course, and on a\n// phone the ENTIRE page (the chat is a drawer over it; see pages/DailyPlanner).\n// The plan''s CONTENT is built and edited by the planner CHAT; here you watch it,\n// mark items done, and step back. 🎯 Weekly Objectives pinned on top (collapsible\n// on mobile, where vertical space is the scarce resource); 🔥 Focus Sessions (bold,\n// black-framed 2h blocks vs plain regular blocks; done items stay struck-through,\n// NOT collapsed); ✅ today-only to-dos. ↩ Undo reverts the last change; a spinner\n// shows while a chat turn or a save is in flight; it refreshes after every chat turn.\n//\n// Touch sizing: checking items off is the primary phone job, so controls are\n// finger-sized by default and shrink to the compact desktop scale at lg.\n\ntype Props = {\n  // Present only below lg, where the chat is a drawer that needs opening.\n  // Undefined on desktop, where the chat is always on screen.\n  onOpenChat?: () => void;\n};\n\nconst HISTORY_MAX = 15;\nconst OBJ_OPEN_KEY = ''nyyon.planner.objectives.open.v1'';\nconst fmtDate = (d: string) => {\n  try { return new Date(d + ''T00:00:00'').toLocaleDateString(undefined, { weekday: ''short'', month: ''short'', day: ''numeric'' }); }\n  catch { return d; }\n};\nconst todayLocal = () => {\n  const d = new Date();\n  const p = (n: number) => String(n).padStart(2, ''0'');\n  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;\n};\nconst byTime = (a: PlanBlock, b: PlanBlock) => (a.start || ''99:99'').localeCompare(b.start || ''99:99'');\nconst todoOrder = (a: PlanTodo, b: PlanTodo) => (a.done ? 1 : 0) - (b.done ? 1 : 0) || (b.star ? 1 : 0) - (a.star ? 1 : 0);\nconst EMPTY: DailyPlan = { date: '''', mode: ''wing_it'', summary: '''', weekly_ref: null, schedule: [], todos: [], created_at: 0, updated_at: 0 };\nconst planSig = (p: DailyPlan | null) => p ? JSON.stringify([p.mode, p.summary, p.weekly_ref, p.schedule, p.todos]) : '''';\n\nfunction Spinner() {\n  return <span className=\"inline-block h-3.5 w-3.5 rounded-full border-2 border-ink/25 border-t-ink animate-spin align-middle\" aria-label=\"updating\" />;\n}\n\nexport function PlanPanel({ onOpenChat }: Props) {\n  const [plan, setPlan] = useState<DailyPlan | null>(null);\n  const [objectives, setObjectives] = useState<WeeklyObjectives | null>(null);\n  const [loading, setLoading] = useState(true);\n  const [saving, setSaving] = useState(false);\n  const [updating, setUpdating] = useState(false); // a chat turn is in flight\n  const [history, setHistory] = useState<DailyPlan[]>([]); // undo stack (past plans)\n  const [future,  setFuture]  = useState<DailyPlan[]>([]); // redo stack (undone plans)\n  // Objectives are pinned above the scroll area, so on a short screen they eat\n  // ~156px of the plan. Default COLLAPSED and let the count carry the signal —\n  // they''re weekly context, not the thing you act on hourly. Only affects mobile:\n  // the body below renders `hidden lg:block`, so desktop always shows the list.\n  // The choice sticks (house pattern: localStorage).\n  const [objOpen, setObjOpen] = useState(() => localStorage.getItem(OBJ_OPEN_KEY) === ''1'');\n  useEffect(() => { localStorage.setItem(OBJ_OPEN_KEY, objOpen ? ''1'' : ''0''); }, [objOpen]);\n\n  // history search\n  const [searchOpen, setSearchOpen] = useState(false);\n  const [q, setQ] = useState('''');\n  const [results, setResults] = useState<DailyPlan[] | null>(null);\n  const [viewing, setViewing] = useState<DailyPlan | null>(null); // a past day being reviewed\n  const [viewDate, setViewDate] = useState<string>(todayLocal);   // the day the header shows — ‹ › time travel\n\n  const planRef = useRef<DailyPlan | null>(null);\n  useEffect(() => { planRef.current = plan; }, [plan]);\n\n  const loadToday = useCallback(async () => {\n    try {\n      const [pr, wo] = await Promise.all([planner.dailyPlan(), planner.weeklyObjectives({}).catch(() => null)]);\n      const cur = planRef.current;\n      // A chat turn changed the plan → snapshot the pre-change version for Undo.\n      if (cur && pr.plan && planSig(cur) !== planSig(pr.plan)) {\n        setHistory((h) => (h.length && planSig(h[h.length - 1]) === planSig(cur)) ? h : [...h.slice(-(HISTORY_MAX - 1)), cur]);\n        setFuture([]); // a chat turn is a forward change → the redo stack no longer applies\n      }\n      setPlan(pr.plan);\n      setObjectives(wo?.objectives || null);\n    } catch { /* keep prior */ } finally { setLoading(false); }\n  }, []);\n\n  useEffect(() => { loadToday(); }, [loadToday]);\n\n  // Time travel — ‹ › browse previous days (read-only, exactly like a searched\n  // day), forward capped at today. The weekly objectives follow the VIEWED\n  // day''s workweek: the server anchors the date, the client never re-derives\n  // the week convention.\n  const gotoDate = useCallback(async (date: string) => {\n    const today = todayLocal();\n    const target = date > today ? today : date;\n    setViewDate(target);\n    if (target === today) {\n      setViewing(null);\n      loadToday();\n      return;\n    }\n    try {\n      const [pr, wo] = await Promise.all([\n        planner.dailyPlan(target),\n        planner.weeklyObjectives({ date: target }).catch(() => null),\n      ]);\n      setViewing(pr.plan || { ...EMPTY, date: target });\n      if (wo) setObjectives(wo.objectives || null);\n    } catch {\n      setViewing({ ...EMPTY, date: target });\n    }\n  }, [loadToday]);\n  const shiftDay = (delta: number) => {\n    const d = new Date(`${viewDate}T00:00:00`);\n    d.setDate(d.getDate() + delta);\n    const p = (n: number) => String(n).padStart(2, ''0'');\n    void gotoDate(`${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`);\n  };\n  const isToday = viewDate === todayLocal();\n  // Live refresh when a plan tool returns.\n  useEffect(() => {\n    const h = () => loadToday();\n    window.addEventListener(''nyyon:plan-updated'', h);\n    return () => window.removeEventListener(''nyyon:plan-updated'', h);\n  }, [loadToday]);\n  // Spinner + refresh keyed to the chat turn (fires on every input).\n  useEffect(() => {\n    const h = (e: Event) => {\n      const busy = !!(e as CustomEvent).detail;\n      setUpdating(busy);\n      if (!busy) loadToday();\n    };\n    window.addEventListener(''nyyon:chat-busy'', h);\n    return () => window.removeEventListener(''nyyon:chat-busy'', h);\n  }, [loadToday]);\n\n  const base = plan || EMPTY;\n\n  // Persist a plan change (marking an item done). `track` pushes the pre-change\n  // plan onto the Undo stack. The chat owns the content; the panel only marks done.\n  async function persist(next: DailyPlan, track = true) {\n    if (track && plan) {\n      setHistory((h) => (h.length && planSig(h[h.length - 1]) === planSig(plan)) ? h : [...h.slice(-(HISTORY_MAX - 1)), plan]);\n      setFuture([]); // a new forward change invalidates the redo stack (no redo across a branch)\n    }\n    setPlan(next);            // optimistic\n    setSaving(true);\n    try { setPlan(await planner.saveDailyPlan(next)); }\n    catch { /* keep optimistic copy */ } finally { setSaving(false); }\n  }\n  // Undo/redo shuttle the plan between two stacks. undo pops the last past plan\n  // and pushes the current one onto the redo stack; redo does the reverse. Both\n  // save with track=false so persist() touches neither stack — the moves are\n  // managed here. Any NEW forward change (an edit, a reuse, a chat turn) clears\n  // the redo stack via persist()/loadToday, so you can''t redo across a branch.\n  function undo() {\n    if (!history.length || !plan) return;\n    const prev = history[history.length - 1];\n    setHistory((h) => h.slice(0, -1));\n    setFuture((f) => [...f.slice(-(HISTORY_MAX - 1)), plan]);\n    persist(prev, false);\n  }\n  function redo() {\n    if (!future.length || !plan) return;\n    const next = future[future.length - 1];\n    setFuture((f) => f.slice(0, -1));\n    setHistory((h) => [...h.slice(-(HISTORY_MAX - 1)), plan]);\n    persist(next, false);\n  }\n\n  // mark done — the only in-panel plan edits\n  const toggleBlock = (id: string) => persist({ ...base, schedule: base.schedule.map((b) => b.id === id ? { ...b, done: !b.done } : b) });\n  const toggleTodo  = (id: string) => persist({ ...base, todos: base.todos.map((t) => t.id === id ? { ...t, done: !t.done } : t) });\n\n  // objectives (separate weekly store) — mark done only; the chat sets them\n  const objList = objectives?.objectives || [];\n  async function saveObjectives(list: WeeklyObjective[]) {\n    setObjectives((o) => (o ? { ...o, objectives: list } : { week_start: '''', objectives: list, created_at: 0, updated_at: 0 }));\n    setSaving(true);\n    try { setObjectives(await planner.saveWeeklyObjectives(list)); } catch { /* keep */ } finally { setSaving(false); }\n  }\n  const toggleObjective = (id: string) => saveObjectives(objList.map((o) => o.id === id ? { ...o, done: !o.done } : o));\n\n  async function runSearch() { try { setResults(await planner.searchDailyPlans(q.trim(), 30)); } catch { setResults([]); } }\n  // Reuse a past day as today''s draft. This REPLACES today''s plan wholesale, so\n  // it is the most destructive action in the panel and must go through persist()\n  // — that is what pushes the outgoing plan onto the Undo stack. It used to call\n  // the save endpoint directly, which overwrote today with no way back: ↩ had\n  // nothing to restore.\n  //\n  // Spread `base` (today), never `src` (the past day). The PUT route resolves the\n  // target day from the payload — `input.date || today` in the save_daily_plan tool —\n  // so carrying the source day''s date across would rewrite THAT day instead of\n  // today, quietly destroying a second plan.\n  async function reuseAsToday(src: DailyPlan) {\n    const next: DailyPlan = {\n      ...base,\n      mode: src.mode,\n      summary: src.summary,\n      weekly_ref: null,\n      schedule: src.schedule.map((b) => ({ ...b, done: false })),\n      todos: src.todos.map((t) => ({ ...t, done: false })),\n    };\n    // Drop out of the past-day view first so the reused plan is what you land on\n    // (and snap the header + objectives back to today''s week).\n    setViewing(null); setViewDate(todayLocal()); setSearchOpen(false); setResults(null); setQ('''');\n    void planner.weeklyObjectives({}).then((wo) => setObjectives(wo.objectives || null)).catch(() => {});\n    await persist(next);\n  }\n\n  const shown = viewing || plan;\n  const blocks = (shown?.schedule || []).slice().sort(byTime);   // done stays in place (no collapse)\n  const todos  = (shown?.todos || []).slice().sort(todoOrder);\n  const ro = !!viewing; // reviewing a past day → read-only\n\n  const renderBlock = (b: PlanBlock) => (\n    <li key={b.id} className={''flex items-start gap-3 lg:gap-2.5 px-3 py-3 lg:py-2.5 '' + (b.focus ? ''rounded-lg border-2 border-ink bg-card/40'' : ''rounded-md hairline bg-card/30'')}>\n      <input type=\"checkbox\" checked={b.done} disabled={ro} onChange={() => toggleBlock(b.id)} className=\"mt-0.5 lg:mt-1 shrink-0 accent-ink h-5 w-5 lg:h-4 lg:w-4\" />\n      <div className=\"flex-1 min-w-0\">\n        <div className={''leading-snug flex items-center gap-1.5 flex-wrap '' + (b.focus ? ''font-bold text-[15px] '' : ''text-sm '') + (b.done ? ''line-through text-mute'' : ''text-ink'')}>\n          {b.focus && <span>🎯</span>}\n          {(b.start || b.end) && <span className=\"mono text-xs text-mute font-normal\">{b.start || ''--:--''}–{b.end || ''--:--''}</span>}\n          <span className=\"flex-1 min-w-[6rem]\">{b.title || <span className=\"text-mute italic\">(untitled)</span>}</span>\n        </div>\n        {b.deliverable && (\n          <div className=\"text-[13px] text-mute mt-0.5 flex items-baseline gap-1\">\n            <span>→</span><span className=\"flex-1\">{b.deliverable}</span>\n          </div>\n        )}\n      </div>\n    </li>\n  );\n\n  const renderTodo = (t: PlanTodo) => (\n    <li key={t.id} className=\"flex items-center gap-2.5 lg:gap-2 px-1 py-2.5 lg:py-1.5\">\n      <input type=\"checkbox\" checked={t.done} disabled={ro} onChange={() => toggleTodo(t.id)} className=\"shrink-0 accent-ink h-5 w-5 lg:h-4 lg:w-4\" />\n      {t.star && <span className=\"shrink-0 text-[15px] leading-none\" title=\"Extra important\">⭐</span>}\n      <span className={''flex-1 text-[15px] '' + (t.done ? ''line-through text-mute'' : t.star ? ''text-ink font-semibold'' : ''text-ink'')}>\n        {t.text || <span className=\"text-mute italic\">(empty)</span>}\n      </span>\n    </li>\n  );\n\n  return (\n    <div className=\"flex flex-col h-full w-full bg-paper/60 min-h-0\">\n      {/* header */}\n      <div className=\"pl-1 pr-2 lg:px-5 h-14 border-b border-line flex items-center justify-between gap-1 lg:gap-2 shrink-0\">\n        <div className=\"flex items-center gap-1 lg:gap-2.5 min-w-0\">\n          {/* Below lg this header IS the page''s top bar — App.tsx skips its own for\n              this page — so the hamburger lives here. */}\n          <button\n            onClick={() => window.dispatchEvent(new CustomEvent(''nyyon:open-menu''))}\n            aria-label=\"Open menu\"\n            className=\"lg:hidden h-11 w-11 shrink-0 grid place-items-center text-ink\"\n          >\n            <Menu size={22} />\n          </button>\n          {/* The date leads the header at every width, with ‹ › time travel —\n              ‹ walks back through past days (read-only), › returns toward today. */}\n          <button\n            onClick={() => shiftDay(-1)}\n            aria-label=\"Previous day\"\n            className=\"h-11 w-8 lg:h-8 lg:w-7 shrink-0 grid place-items-center rounded-sm text-mute hover:text-ink hover:bg-card/70 transition text-base leading-none\"\n          >‹</button>\n          <span className=\"text-base font-semibold tracking-tight text-ink truncate min-w-0\">\n            🗓️ {fmtDate(viewDate)}\n            {isToday && <span className=\"hidden lg:inline text-mute font-normal\"> · Today</span>}\n          </span>\n          <button\n            onClick={() => shiftDay(1)}\n            disabled={isToday}\n            aria-label=\"Next day\"\n            className=\"h-11 w-8 lg:h-8 lg:w-7 shrink-0 grid place-items-center rounded-sm text-mute hover:text-ink hover:bg-card/70 transition text-base leading-none disabled:opacity-25 disabled:hover:bg-transparent\"\n          >›</button>\n          {/* Mode chip (Strategic / Wing it): desktop only — noise in the tight mobile header. */}\n          {shown && shown.mode && !viewing && (\n            <span className={''hidden lg:inline-block mono text-[9px] uppercase tracking-wider px-1.5 py-0.5 rounded-sm shrink-0 '' + (shown.mode === ''strategic'' ? ''bg-ink text-paper'' : ''bg-card text-mute hairline'')}>\n              {shown.mode === ''strategic'' ? ''Strategic'' : ''Wing it''}\n            </span>\n          )}\n        </div>\n        <div className=\"flex items-center gap-0.5 lg:gap-1 shrink-0\">\n          {(saving || updating) && <Spinner />}\n          {!viewing && (\n            <button onClick={undo} disabled={!history.length} title=\"Undo last change\" aria-label=\"Undo last change\"\n              className=\"h-11 w-11 lg:h-8 lg:w-8 grid place-items-center rounded-sm text-mute hover:text-ink hover:bg-card/70 transition disabled:opacity-25 disabled:hover:bg-transparent text-base leading-none\">↩</button>\n          )}\n          {!viewing && (\n            <button onClick={redo} disabled={!future.length} title=\"Redo last change\" aria-label=\"Redo last change\"\n              className=\"h-11 w-11 lg:h-8 lg:w-8 grid place-items-center rounded-sm text-mute hover:text-ink hover:bg-card/70 transition disabled:opacity-25 disabled:hover:bg-transparent text-base leading-none\">↪</button>\n          )}\n          <button onClick={() => { setSearchOpen((v) => !v); setViewing(null); }} title=\"Search past days\" aria-label=\"Search past days\"\n            className={''h-11 w-11 lg:h-8 lg:w-8 grid place-items-center rounded-sm transition '' + (searchOpen ? ''bg-card text-ink hairline'' : ''text-mute hover:text-ink hover:bg-card/70'')}>\n            <Search size={16} />\n          </button>\n          {/* Below lg the chat is a drawer — this is the way back to it. */}\n          {onOpenChat && (\n            <button onClick={onOpenChat} title=\"Open the planner chat\" aria-label=\"Open the planner chat\"\n              className=\"h-11 w-11 grid place-items-center rounded-sm bg-ink text-paper ml-0.5\">\n              <MessageSquare size={17} />\n            </button>\n          )}\n        </div>\n      </div>\n\n      {/* history search */}\n      {searchOpen && (\n        <div className=\"border-b border-line p-3 shrink-0 bg-card/30\">\n          <div className=\"flex items-center gap-2\">\n            {/* text-base below lg: iOS Safari auto-zooms the page on focus when\n                an input''s font-size is under 16px. */}\n            <input value={q} onChange={(e) => setQ(e.target.value)} onKeyDown={(e) => { if (e.key === ''Enter'') runSearch(); }}\n              placeholder=\"🔍 Search past plans…\" autoFocus\n              className=\"flex-1 min-w-0 rounded-sm hairline bg-card/90 px-2.5 py-2 lg:py-1.5 text-base lg:text-sm placeholder:text-mute focus:border-ink focus:outline-none\" />\n            <button onClick={runSearch} className=\"mono text-[10px] uppercase tracking-wider h-11 lg:h-8 px-3 lg:px-2.5 shrink-0 rounded-sm bg-ink text-paper\">Go</button>\n          </div>\n          {results && (\n            <ul className=\"mt-2 space-y-1 max-h-56 overflow-y-auto\">\n              {results.length === 0 && <li className=\"text-xs text-mute px-1 py-2\">No matching days.</li>}\n              {results.map((r) => (\n                <li key={r.date}>\n                  <button onClick={() => void gotoDate(r.date)} className=\"w-full text-left px-2 py-2.5 lg:py-1.5 rounded-sm hover:bg-card/70 transition\">\n                    <div className=\"flex items-center justify-between gap-2\">\n                      <span className=\"text-sm text-ink\">{fmtDate(r.date)}</span>\n                      <span className=\"mono text-[9px] text-mute\">{r.schedule.length}b · {r.todos.length}t</span>\n                    </div>\n                    {r.summary && <div className=\"text-xs text-mute truncate\">{r.summary}</div>}\n                  </button>\n                </li>\n              ))}\n            </ul>\n          )}\n        </div>\n      )}\n\n      {loading ? (\n        <div className=\"p-5 text-sm text-mute\">Loading…</div>\n      ) : (\n        <div className=\"flex-1 min-h-0 flex flex-col overflow-hidden\">\n          {/* 🎯 Weekly Objectives — persist for the whole workweek: a past day\n              shows ITS week''s objectives (read-only); today''s are editable. */}\n          {(\n            <div className=\"shrink-0 px-4 lg:px-5 pt-3 lg:pt-4 pb-2.5 lg:pb-3.5 border-b border-line bg-paper/70\">\n              {/* The heading toggles the list below lg, where vertical space is\n                  scarce; at lg+ it is a plain heading and the list is always open. */}\n              <button\n                onClick={() => setObjOpen((v) => !v)}\n                aria-expanded={objOpen}\n                className=\"w-full flex items-center gap-2 text-left lg:pointer-events-none min-h-[44px] lg:min-h-0\"\n              >\n                <h2 className=\"text-lg font-bold tracking-tight text-ink flex items-center gap-2\">🎯 Weekly Objectives</h2>\n                {objList.length > 0 && (\n                  <span className=\"mono text-[10px] text-mute shrink-0\">\n                    {objList.filter((o) => o.done).length}/{objList.length}\n                  </span>\n                )}\n                <span className={''lg:hidden ml-auto text-mute text-xs transition-transform '' + (objOpen ? ''rotate-180'' : '''')} aria-hidden>▾</span>\n              </button>\n\n              <div className={objOpen ? ''block'' : ''hidden lg:block''}>\n                <ul className=\"mt-1.5 lg:mt-2 space-y-0.5 lg:space-y-1\">\n                  {objList.map((ob) => (\n                    <li key={ob.id} className=\"flex items-start gap-2.5 lg:gap-2 text-[15px] leading-snug py-1 lg:py-0\">\n                      <input type=\"checkbox\" checked={ob.done} disabled={!!viewing} onChange={() => toggleObjective(ob.id)} className=\"mt-0.5 lg:mt-1 shrink-0 accent-ink h-5 w-5 lg:h-3.5 lg:w-3.5\" />\n                      <span className={''flex-1 '' + (ob.done ? ''line-through text-mute'' : ''text-ink font-medium'')}>{ob.text}</span>\n                    </li>\n                  ))}\n                </ul>\n                {objList.length === 0 && (\n                  <p className=\"mt-1.5 text-sm text-amber-700 dark:text-amber-400 flex items-center gap-1.5\">\n                    <span aria-hidden>⚠️</span> No weekly objectives were set yet\n                  </p>\n                )}\n              </div>\n            </div>\n          )}\n\n          {/* scrolling: summary + focus sessions + to-dos */}\n          <div className=\"flex-1 overflow-y-auto p-4 lg:p-5 space-y-6 lg:space-y-7\">\n            {viewing && (\n              <button onClick={() => void gotoDate(todayLocal())} className=\"mono text-[10px] uppercase tracking-wider text-mute hover:text-ink flex items-center gap-1\">\n                <X size={12} /> back to today\n              </button>\n            )}\n            {shown?.summary && <div className=\"text-base text-ink leading-relaxed\">{shown.summary}</div>}\n\n            {/* 🔥 Focus Sessions / schedule */}\n            <section>\n              <h3 className=\"text-base font-bold text-ink flex items-center gap-2 mb-2.5\">🔥 Focus Sessions</h3>\n              {blocks.length === 0 ? (\n                <div className=\"space-y-2\">\n                  {[1, 2, 3].map((n) => (\n                    <div key={n} className=\"rounded-lg border-2 border-ink px-4 py-3 flex items-center justify-between opacity-60\">\n                      <span className=\"font-bold text-ink flex items-center gap-2\">🎯 Session {n}</span>\n                      <span className=\"mono text-[11px] text-mute\">2h</span>\n                    </div>\n                  ))}\n                  {onOpenChat ? (\n                    <button onClick={onOpenChat} className=\"mt-1 w-full h-11 rounded-sm bg-ink text-paper mono text-[10px] uppercase tracking-wider\">\n                      Plan the day\n                    </button>\n                  ) : (\n                    <p className=\"text-xs text-mute pt-0.5\">Placeholders — plan the day with the chat.</p>\n                  )}\n                </div>\n              ) : (\n                <ul className=\"space-y-2\">{blocks.map(renderBlock)}</ul>\n              )}\n            </section>\n\n            {/* ✅ To-do (today only) */}\n            <section>\n              <h3 className=\"text-base font-bold text-ink flex items-center gap-2 mb-2.5\">✅ Today’s To-do</h3>\n              {todos.length === 0 ? (\n                onOpenChat ? (\n                  <button onClick={onOpenChat} className=\"w-full h-11 rounded-sm hairline bg-card/40 text-mute text-sm\">\n                    Nothing yet — tap to plan the day\n                  </button>\n                ) : (\n                  <div className=\"text-sm text-mute\">Nothing yet — plan the day with the chat.</div>\n                )\n              ) : (\n                <ul className=\"space-y-0.5\">{todos.map(renderTodo)}</ul>\n              )}\n              {viewing && (\n                <button onClick={() => reuseAsToday(viewing)} className=\"mt-4 mono text-[10px] uppercase tracking-wider h-11 lg:h-8 px-4 lg:px-3 rounded-sm bg-ink text-paper\">\n                  ♻️ Reuse as today’s draft\n                </button>\n              )}\n            </section>\n          </div>\n        </div>\n      )}\n    </div>\n  );\n}\n"},{"path":"data.ts","code":"// Daily Planner plugin — the surface''s data layer.\n//\n// The host REST routes this page used to call are gone: a plugin surface\n// drives its OWN plugin''s tools through the scoped invoke route, so the page\n// and the planner chat write through the exact same seven verbs and can never\n// diverge. The types live here too — they travel with the module.\n\nexport type PlanBlock = {\n  id: string;\n  start: string | null;\n  end: string | null;\n  title: string;\n  deliverable: string | null;\n  done: boolean;\n  focus: boolean;\n};\nexport type PlanTodo = { id: string; text: string; done: boolean; star: boolean; priority: number };\nexport type DailyPlan = {\n  date: string;\n  mode: ''strategic'' | ''wing_it'';\n  summary: string;\n  weekly_ref: string | null;\n  schedule: PlanBlock[];\n  todos: PlanTodo[];\n  created_at: number;\n  updated_at: number;\n};\nexport type WeeklyObjective  = { id: string; text: string; done: boolean };\nexport type WeeklyObjectives = { week_start: string; objectives: WeeklyObjective[]; created_at: number; updated_at: number };\n\nasync function invoke<T>(tool: string, input: unknown): Promise<T> {\n  const r = await fetch(`/api/plugins/daily-planner/invoke/${tool}`, {\n    method: ''POST'',\n    headers: { ''content-type'': ''application/json'' },\n    body: JSON.stringify(input ?? {}),\n  });\n  const d = await r.json();\n  if (!d.ok) throw new Error(d.error || `HTTP ${r.status}`);\n  return d.result as T;\n}\n\ntype ObjectivesResult = { week_start: string; objectives: WeeklyObjective[]; created_at?: number; updated_at?: number };\nconst toRow = (r: ObjectivesResult): WeeklyObjectives => ({\n  week_start: r.week_start,\n  objectives: r.objectives || [],\n  created_at: r.created_at ?? 0,\n  updated_at: r.updated_at ?? 0,\n});\n\nexport const planner = {\n  dailyPlan: (date?: string) =>\n    invoke<{ date: string; plan: DailyPlan | null }>(''read_daily_plan'', date ? { date } : {}),\n  saveDailyPlan: (plan: Partial<DailyPlan>) =>\n    invoke<{ date: string; plan: DailyPlan }>(''save_daily_plan'', plan).then((r) => r.plan),\n  searchDailyPlans: (q: string, limit = 30) =>\n    invoke<{ query: string; plans: DailyPlan[] }>(''search_daily_plans'', { query: q, limit }).then((r) => r.plans),\n  // `week` = a literal week_start; `date` = any day, anchored to its workweek\n  // by the tool (the convention lives server-side, never re-derived here).\n  weeklyObjectives: ({ week, date }: { week?: string; date?: string } = {}) =>\n    invoke<ObjectivesResult>(''read_weekly_objectives'', { week_start: week, date })\n      .then((r) => ({ week_start: r.week_start, objectives: toRow(r) })),\n  saveWeeklyObjectives: (objectives: WeeklyObjective[], week_start?: string) =>\n    invoke<ObjectivesResult>(''set_weekly_objectives'', { objectives, week_start }).then(toRow),\n};\n"}],"icon":"CalendarCheck","page_code":"import { useEffect, useState } from ''react'';\nimport { Chat } from ''../../components/Chat'';\nimport { PlanPanel } from ''./PlanPanel'';\n\n// Daily Planner workspace — MOBILE FIRST.\n//\n// The plan is the product: it renders at every width and is what you check off\n// all day. The planning conversation is the TOOL that produces it, used once in\n// the morning — so on a phone it slides in over the plan as a drawer (mirroring\n// ChatDrawer), and at lg+ it settles into a fixed column beside it. Previously\n// the panel was `hidden md:flex`, which meant the plan — the whole point of the\n// module — did not render on a phone at all.\n//\n// The breakpoint is lg, matching the app shell: Sidebar, the mobile top bar and\n// ChatDrawer all switch at lg. The old md: split left a dead zone at 768-1024px\n// where the mobile chrome and the desktop two-column layout were on screen at\n// once.\n\nconst DESKTOP = ''(min-width: 1024px)''; // Tailwind lg\n\nexport default function DailyPlanner() {\n  const [chatOpen, setChatOpen] = useState(false);\n  const [desktop, setDesktop] = useState(\n    () => typeof window !== ''undefined'' && window.matchMedia(DESKTOP).matches,\n  );\n\n  // Track the breakpoint so the chat can be a REAL drawer below lg (hidden from\n  // assistive tech while closed, and closable) and a plain static column above\n  // it. CSS alone can''t express that — aria-hidden and the close button both\n  // have to be off on desktop, where the chat is always visible.\n  //\n  // Sync on mount as well as on change: the useState initializer runs once, and\n  // if the viewport differs by the time the effect attaches (or a change event\n  // is missed) the state would otherwise stay wrong for the life of the page.\n  useEffect(() => {\n    const mq = window.matchMedia(DESKTOP);\n    const sync = () => {\n      setDesktop(mq.matches);\n      if (mq.matches) setChatOpen(false); // resizing up shouldn''t strand drawer state\n    };\n    sync();\n    mq.addEventListener(''change'', sync);\n    return () => mq.removeEventListener(''change'', sync);\n  }, []);\n\n  useEffect(() => {\n    if (!chatOpen || desktop) return;\n    const h = (e: KeyboardEvent) => { if (e.key === ''Escape'') setChatOpen(false); };\n    window.addEventListener(''keydown'', h);\n    return () => window.removeEventListener(''keydown'', h);\n  }, [chatOpen, desktop]);\n\n  return (\n    <div className=\"h-full min-h-0 flex bg-paper\">\n      {/* Scrim — mobile only; over the plan, under the drawer. */}\n      <div\n        onClick={() => setChatOpen(false)}\n        className={\n          ''lg:hidden fixed inset-0 bg-black/25 backdrop-blur-[1px] z-40 transition-opacity duration-200 '' +\n          (chatOpen ? ''opacity-100 pointer-events-auto'' : ''opacity-0 pointer-events-none'')\n        }\n      />\n\n      {/* The planning chat: drawer below lg, static column at lg+. */}\n      <aside\n        // aria-hidden alone would hide the closed drawer from screen readers while\n        // leaving its buttons and composer in the tab order — focus could land on\n        // content that is off-screen and announced as hidden. `inert` (React 19)\n        // removes it from the tab order too. Both, so the intent is explicit.\n        aria-hidden={!desktop && !chatOpen}\n        inert={!desktop && !chatOpen}\n        className={\n          ''fixed top-0 right-0 h-full w-full sm:w-[460px] bg-paper border-l border-line z-50 '' +\n          ''shadow-[-16px_0_40px_-20px_rgba(10,10,10,0.18)] transition-transform duration-300 ease-out '' +\n          // max-lg: scopes the closed-drawer transform to BELOW lg. Emitting a bare\n          // `translate-x-full` alongside `lg:translate-x-0` does not work — the lg\n          // variant loses the cascade and the column renders shifted a full width\n          // to the right, on top of the plan. Scoping it means the two never collide.\n          (chatOpen ? ''translate-x-0 '' : ''max-lg:translate-x-full '') +\n          ''lg:static lg:z-auto lg:w-[480px] lg:shrink-0 lg:flex lg:flex-col '' +\n          ''lg:border-l-0 lg:border-r lg:shadow-none''\n        }\n      >\n        <Chat\n          scope=\"daily-planner\"\n          title=\"Daily Planner · your day\"\n          // Below lg the chat covers the plan, so it gets a full-width \"Back to\n          // plan\" bar instead of a ✕. At lg+ the plan is already beside it and\n          // neither is needed.\n          onBack={desktop ? undefined : () => setChatOpen(false)}\n        />\n      </aside>\n\n      {/* The plan — the base layer, visible at every width. */}\n      <div className=\"flex-1 min-w-0 min-h-0 flex\">\n        <PlanPanel onOpenChat={desktop ? undefined : () => setChatOpen(true)} />\n      </div>\n    </div>\n  );\n}\n"}]}}', '{}', '{"step":"bundled"}', 1788437398264, 1788437398264)
ON CONFLICT(name) DO UPDATE SET version=excluded.version, title=excluded.title, status='active',
  manifest_json=excluded.manifest_json, binding_json=excluded.binding_json, updated_at=excluded.updated_at;
INSERT INTO plugins (name, version, title, status, manifest_json, binding_json, report_json, installed_at, updated_at)
VALUES ('digest', '3.1.3', 'Digest', 'active', '{"nyyon_plugin":2,"name":"digest","title":"Digest","version":"3.1.3","description":"The morning brief: two sources, search and calendar. Search files fresh headlines for the operator''s topics through any installed search provider; calendar mirrors the coming week''s events. Everything lands in one urgency-sorted feed of cards the operator opens, stars, snoozes, marks read or keeps a draft note on. It learns continuously: dismissals tune the interest filter, and score feedback grows taste rules the prioritizer reads.","origin":{"system":"cmd.nyyon.com","exported_at":1788182094620},"lib":[{"path":"digest.mjs","code":"// Digest plugin: the morning brief. Every function that needs the outside\n// world takes `api` as its FIRST argument (api.db / api.gateway /\n// api.knowledge / api.saveKnowledge / api.log / api.discoverGateways). This\n// file imports NOTHING.\n//\n// Two sources feed the brief, both probed live on every run:\n//   search   - headlines for the operator''s topics, through any installed\n//              gateway that advertises the ''search'' capability\n//   calendar - the host calendar mirror''s 7-day look-ahead\n// Both materialize \"cards\" into plugin_digest_items. The page reads that\n// table; the operator marks read / stars / snoozes / keeps a draft note.\n//\n// Tables written (plugin-owned): plugin_digest_items,\n//   plugin_digest_signal_snoozes (read here; written by signal-priority.mjs)\n// Host tables (SELECT-only, declared in requires.host_reads):\n//   calendar_events, events\n// Gateways: setup(read) for the fresh-install check. No LLM here: the\n//   scorer (signal-priority.mjs) and the dismissal learner\n//   (digest-relevance.mjs) are the pack''s two reasoning passes.\n// Knowledge (own docs, seeded on first read): plugin-digest-policy,\n//   plugin-digest-search-topics.\n//\n// Cross-lib seam (lib files may not import each other): the snooze action in\n// executeDigestAction rides ./signal-priority.mjs; the calling tool imports\n// that lib and passes { snoozeItem } as the trailing `deps` argument. The\n// snooze key builder below is duplicated there on purpose.\n\nconst now = () => Date.now();\nconst uid = () => crypto.randomUUID();\nfunction safeJSON(s) {\n  if (!s) return null;\n  try { return JSON.parse(s); } catch { return s; }\n}\n\n// ─── CRUD ───────────────────────────────────────────────────\nexport async function listDigestItems(api, { unread_only = false, starred_only = false, limit = 200 } = {}) {\n  const where = [];\n  if (unread_only)  where.push(''read_at IS NULL'');\n  if (starred_only) where.push(''starred = 1'');\n  const sql = `\n    SELECT * FROM plugin_digest_items\n    ${where.length ? ''WHERE '' + where.join('' AND '') : ''''}\n    ORDER BY urgency ASC, created_at DESC\n    LIMIT ?\n  `;\n  const r = await api.db.prepare(sql).bind(limit).all();\n  return (r.results || []).map((x) => ({ ...x, meta: safeJSON(x.meta_json) }));\n}\n\nexport async function readDigestItem(api, id) {\n  const r = await api.db.prepare(''SELECT * FROM plugin_digest_items WHERE id = ?'').bind(id).first();\n  return r ? { ...r, meta: safeJSON(r.meta_json) } : null;\n}\n\nexport async function patchDigestItem(api, id, patch) {\n  const existing = await readDigestItem(api, id);\n  if (!existing) throw new Error(`digest item ${id} not found`);\n  const fields = [];\n  const args   = [];\n  if (patch.read !== undefined) {\n    fields.push(''read_at = ?'');\n    args.push(patch.read ? now() : null);\n  }\n  if (patch.starred !== undefined) {\n    fields.push(''starred = ?'');\n    args.push(patch.starred ? 1 : 0);\n  }\n  // Draft note auto-save: the card''s editable note lives in meta_json.\n  if (typeof patch.draft === ''string'') {\n    const meta = existing.meta && typeof existing.meta === ''object'' ? existing.meta : {};\n    meta.draft = patch.draft.slice(0, 2000);\n    meta.draft_edited_at = now();\n    fields.push(''meta_json = ?'');\n    args.push(JSON.stringify(meta));\n  }\n  if (fields.length === 0) return existing;\n  args.push(id);\n  await api.db.prepare(`UPDATE plugin_digest_items SET ${fields.join('', '')} WHERE id = ?`).bind(...args).run();\n  return readDigestItem(api, id);\n}\n\n// The item plus its source row where one exists: a calendar card carries the\n// calendar_events row it was derived from (declared host read); a news card\n// is self-contained (the headline, the link, the topic it matched).\nexport async function getDigestItemContext(api, id) {\n  const item = await readDigestItem(api, id);\n  if (!item) return null;\n  const out = { item, event: null };\n  if (item.ref_kind === ''calendar_events'' && item.ref_id) {\n    try {\n      const e = await api.db.prepare(\n        `SELECT id, kind, title, description, starts_at, ends_at, all_day, status, location, link_url, platform\n           FROM calendar_events WHERE id = ?`,\n      ).bind(item.ref_id).first();\n      if (e) out.event = e;\n    } catch { /* calendar table absent on this install */ }\n  }\n  return out;\n}\n\nexport async function insertDigestItem(api, item, { refresh = false } = {}) {\n  const id = item.id || (''dig_'' + uid().slice(0, 12));\n  const cols = `(id, kind, ref_kind, ref_id, title, summary, source_label, source_url,\n       urgency, actionable, suggested_action, starred, read_at, created_at, meta_json)`;\n  const vals = `VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0, NULL, ?, ?)`;\n  // Two modes on an id collision:\n  //  - default: INSERT OR IGNORE. A re-run of the same id is a silent no-op,\n  //    so a read or dismissed card never resurrects and created_at stays put.\n  //  - refresh: upsert the VOLATILE fields (title, summary, urgency, ...)\n  //    while preserving read_at / starred / created_at. pullCalendar uses\n  //    this so an approaching meeting''s urgency and \"when\" text track the\n  //    clock instead of freezing at first insert.\n  const sql = refresh\n    ? `INSERT INTO plugin_digest_items ${cols} ${vals}\n       ON CONFLICT(id) DO UPDATE SET\n         title            = excluded.title,\n         summary          = excluded.summary,\n         source_label     = excluded.source_label,\n         suggested_action = excluded.suggested_action,\n         urgency          = excluded.urgency,\n         actionable       = excluded.actionable`\n    : `INSERT OR IGNORE INTO plugin_digest_items ${cols} ${vals}`;\n  await api.db.prepare(sql).bind(\n    id,\n    item.kind,\n    item.ref_kind || null,\n    item.ref_id   || null,\n    item.title,\n    item.summary  || null,\n    item.source_label || null,\n    item.source_url   || null,\n    item.urgency != null ? item.urgency : 2,\n    item.actionable ? 1 : 0,\n    item.suggested_action || null,\n    now(),\n    item.meta ? JSON.stringify(item.meta) : null,\n  ).run();\n  return readDigestItem(api, id);\n}\n\nexport async function clearReadDigestItems(api) {\n  const r = await api.db.prepare(''DELETE FROM plugin_digest_items WHERE read_at IS NOT NULL'').run();\n  const cleared = r.meta?.changes ?? 0;\n  if (cleared > 0) await api.log(''digest_cleared'', { cleared });\n  return { cleared };\n}\n\n// ─── snooze keys (shared with signal-priority.mjs, duplicated by contract) ──\n// What \"snooze this\" mutes for a while: a news card mutes its outlet\n// (source_label), a card derived from a host row mutes that row, anything\n// else mutes just itself. The pullers consult the active keys so a snoozed\n// outlet or event stays out of the brief until the snooze expires.\nexport function digestSnoozeKey(item) {\n  if (!item) return null;\n  const label = String(item.source_label || '''').trim().toLowerCase();\n  if (item.kind === ''news'' && label) return ''source:'' + label;\n  if (item.ref_kind && item.ref_id) return `ref:${item.ref_kind}:${item.ref_id}`;\n  return ''item:'' + item.id;\n}\n\nasync function activeSnoozeKeys(api) {\n  try {\n    const r = await api.db.prepare(''SELECT key FROM plugin_digest_signal_snoozes WHERE until > ?'').bind(now()).all();\n    return new Set((r.results || []).map((x) => String(x.key)));\n  } catch { return new Set(); }\n}\n\n// Snoozing one card also archives its unread siblings that share the key\n// (the other headlines from the same outlet, say). deps-wired into\n// signal-priority.mjs''s snoozeItem by the calling tool.\nexport async function archiveItemsByKey(api, key, { except_id = null } = {}) {\n  if (!key) return 0;\n  const rows = (await api.db.prepare(\n    ''SELECT id, kind, ref_kind, ref_id, source_label FROM plugin_digest_items WHERE read_at IS NULL'',\n  ).all()).results || [];\n  let archived = 0;\n  for (const row of rows) {\n    if (except_id && row.id === except_id) continue;\n    if (digestSnoozeKey(row) !== key) continue;\n    await api.db.prepare(''UPDATE plugin_digest_items SET read_at = ? WHERE id = ?'').bind(now(), row.id).run();\n    archived++;\n  }\n  if (archived) await api.log(''digest_items_archived_by_key'', { key, archived });\n  return archived;\n}\n\n// ─── per-item actions ───────────────────────────────────────\n// The actions an operator can take on a card. No drafting, no LLM: every\n// action is a one-step verb the page and Nyo both run through\n// executeDigestAction.\n//   { type, label, description, url? }\nexport async function draftDigestActions(api, id) {\n  const ctx = await getDigestItemContext(api, id);\n  if (!ctx) return { item: null, actions: [] };\n  const item = ctx.item;\n  const actions = [];\n  if (item.source_url) {\n    actions.push({ type: ''open_link'', label: ''Open link'', description: item.source_url, url: item.source_url });\n  }\n  actions.push({\n    type: ''mark_read'',\n    label: item.read_at ? ''Mark unread'' : ''Mark read'',\n    description: item.read_at ? ''Put the card back in the brief.'' : ''Dismiss from the brief. The item stays in the activity log.'',\n  });\n  actions.push({\n    type: ''star'',\n    label: item.starred ? ''Unstar'' : ''Star'',\n    description: ''Pinned cards stay visible across day rolls.'',\n  });\n  actions.push({\n    type: ''save_draft'',\n    label: ''Save draft note'',\n    description: ''Keep a note on the card (auto-saves from the page).'',\n  });\n  actions.push({\n    type: ''snooze'',\n    label: ''Snooze'',\n    description: item.kind === ''news''\n      ? `Keep ${item.source_label || ''this outlet''} out of the brief for a while.`\n      : ''Keep this out of the brief for a while.'',\n  });\n  return { item, context: ctx, actions };\n}\n\nexport async function executeDigestAction(api, id, action, deps = {}) {\n  if (!action?.type) throw new Error(''action.type required'');\n  const item = await readDigestItem(api, id);\n  if (!item) throw new Error(''digest item not found'');\n\n  if (action.type === ''open_link'') {\n    if (!item.source_url) throw new Error(''this card has no link'');\n    await api.log(''digest_action'', { id, type: ''open_link'', url: item.source_url });\n    return { ok: true, url: item.source_url };\n  }\n  if (action.type === ''mark_read'') {\n    const read = action.read !== undefined ? !!action.read : true;\n    const next = await patchDigestItem(api, id, { read });\n    await api.log(''digest_action'', { id, type: ''mark_read'', read });\n    return { ok: true, item: next };\n  }\n  if (action.type === ''star'') {\n    const starred = action.starred !== undefined ? !!action.starred : !item.starred;\n    const next = await patchDigestItem(api, id, { starred });\n    await api.log(''digest_action'', { id, type: ''star'', starred });\n    return { ok: true, item: next };\n  }\n  if (action.type === ''save_draft'') {\n    if (typeof action.draft !== ''string'') throw new Error(''save_draft needs draft text'');\n    const next = await patchDigestItem(api, id, { draft: action.draft });\n    await api.log(''digest_action'', { id, type: ''save_draft'', chars: action.draft.length });\n    return { ok: true, item: next };\n  }\n  if (action.type === ''snooze'') {\n    if (typeof deps.snoozeItem !== ''function'') {\n      throw new Error(''snooze needs deps.snoozeItem (from ./signal-priority.mjs): wire it in the calling tool'');\n    }\n    const r = await deps.snoozeItem(api, id, { archiveItemsByKey });\n    await api.log(''digest_action'', { id, type: ''snooze'', until: r?.until || null });\n    return { ok: true, ...r };\n  }\n  throw new Error(`unknown action type: ${action.type}`);\n}\n\n// ─── digest policy (knowledge-backed) ────────────────────────\n// The tunable thresholds live in the plugin-digest-policy knowledge doc as\n// JSON: the operator edits the doc, no deploy. A missing or broken doc falls\n// back to these defaults.\nconst DIGEST_POLICY_DEFAULTS = Object.freeze({\n  sources_off: [],             // sources to skip even when present, e.g. [\"calendar\"]\n  search_topics_cap: 5,        // most topics looked up per run\n  search_per_topic_limit: 5,   // most headlines kept per topic per provider\n  search_urgency: 2,           // where search items land in the brief\n  calendar_lookahead_days: 7,  // how far ahead calendar cards reach\n  stale_after_days: 7,         // soft-archive unread, unstarred, non-urgent items\n  delete_after_days: 14,       // hard-delete read items past this horizon\n});\nfunction polNum(v, fallback) {\n  const n = Number(v);\n  return Number.isFinite(n) && n > 0 ? n : fallback;\n}\nasync function loadDigestPolicy(api) {\n  try {\n    const row = await api.knowledge(''plugin-digest-policy'');\n    if (!row?.body) {\n      await api.saveKnowledge(''plugin-digest-policy'', {\n        title: ''Digest policy: scan windows + caps'',\n        body: JSON.stringify(DIGEST_POLICY_DEFAULTS, null, 2),\n      }).catch(() => {});\n      return { ...DIGEST_POLICY_DEFAULTS };\n    }\n    const m = String(row.body).match(/\\{[\\s\\S]*\\}/);\n    const src = m ? JSON.parse(m[0]) : {};\n    const out = {};\n    for (const [k, dflt] of Object.entries(DIGEST_POLICY_DEFAULTS)) {\n      out[k] = Array.isArray(dflt)\n        ? (Array.isArray(src[k]) ? src[k].map(String) : [...dflt])\n        : polNum(src[k], dflt);\n    }\n    return out;\n  } catch {\n    return { ...DIGEST_POLICY_DEFAULTS };\n  }\n}\n\n// ─── search: operator topics x every installed search provider ────────────\n// The provider is DISCOVERED, never named: any plugin whose gateway advertises\n// capability ''search'' is queried for each topic in the\n// plugin-digest-search-topics doc. No providers or no topics = a soft note,\n// not an error: the source simply has nothing to say yet.\nconst SEARCH_TOPICS_DEFAULT = `# Digest search topics\n\nOne topic per line. The digest''s search source looks each of these up every\nrun and files fresh headlines into the brief. Lines starting with # are\nignored. Keep it to a handful: the brief should stay a brief.\n\nAI agents\n`;\n\nasync function pullSearch(api) {\n  const providers = await api.discoverGateways(''search'');\n  if (!providers.length) return { ids: [], error: ''no search provider installed: add one (e.g. the News Search plugin)'' };\n  const policy = await loadDigestPolicy(api);\n\n  let doc = null;\n  try { doc = await api.knowledge(''plugin-digest-search-topics''); } catch { doc = null; }\n  if (!doc) {\n    try {\n      await api.saveKnowledge(''plugin-digest-search-topics'', { title: ''Digest search topics'', body: SEARCH_TOPICS_DEFAULT });\n      doc = { body: SEARCH_TOPICS_DEFAULT };\n    } catch { doc = { body: SEARCH_TOPICS_DEFAULT }; }\n  }\n  const topics = String(doc.body || '''').split(''\\n'')\n    .map((l) => l.trim())\n    .filter((l) => l && !l.startsWith(''#''))\n    .slice(0, policy.search_topics_cap);\n  if (!topics.length) return { ids: [], error: ''no topics listed: edit the \"Digest search topics\" doc in Knowledge'' };\n\n  const snoozed = await activeSnoozeKeys(api);\n  const ids = [];\n  const seen = new Set();\n  let lastErr = null;\n  let muted = 0;\n  for (const topic of topics) {\n    for (const p of providers) {\n      let r = null;\n      try { r = await p.call({ query: topic, limit: policy.search_per_topic_limit }); }\n      catch (e) { lastErr = String(e?.message || e); r = null; }\n      if (!r?.ok) { if (r?.error) lastErr = String(r.error); continue; }\n      for (const hit of r.results || []) {\n        if (!hit?.url || seen.has(hit.url)) continue;\n        seen.add(hit.url);\n        const label = hit.source || p.label || null;\n        // A snoozed outlet stays out until the snooze expires.\n        if (label && snoozed.has(''source:'' + String(label).trim().toLowerCase())) { muted++; continue; }\n        // One stable id per URL: a headline that was read or dismissed stays\n        // read on every later run (INSERT OR IGNORE semantics).\n        let h = 0;\n        for (let i = 0; i < hit.url.length; i++) h = ((h << 5) - h + hit.url.charCodeAt(i)) | 0;\n        const id = ''srch_'' + (h >>> 0).toString(36);\n        const inserted = await insertDigestItem(api, {\n          id, kind: ''news'', ref_kind: ''search'', ref_id: topic,\n          title: hit.title,\n          summary: [hit.source, hit.published_at, `topic: ${topic}`].filter(Boolean).join('' · ''),\n          source_label: label, source_url: hit.url,\n          urgency: policy.search_urgency, actionable: 0, suggested_action: null,\n        });\n        if (inserted) ids.push(id);\n      }\n    }\n  }\n  // Nothing landed AND a provider was failing: that is a source problem, not\n  // a quiet news day. Surface it in the generate result.\n  if (!ids.length && lastErr) return { ids, error: `search provider failing: ${lastErr.slice(0, 160)}` };\n  return { ids, error: null, meta: { topics: topics.length, providers: providers.length, muted } };\n}\n\n// ─── calendar: the host mirror''s look-ahead ──────────────────────────────\nasync function pullCalendar(api, nowMs) {\n  // Look-AHEAD window: events in the next calendar_lookahead_days.\n  // calendar_events is a declared host_read (SELECT only); the derived digest\n  // rows land in the plugin table.\n  const policy = await loadDigestPolicy(api);\n  const snoozed = await activeSnoozeKeys(api);\n  const inserted = [];\n  const horizon = nowMs + policy.calendar_lookahead_days * 24 * 60 * 60 * 1000;\n  // Window on END, not start: include events that start within the window\n  // AND have not finished yet (assume a 1h duration when ends_at is null), so\n  // an ongoing meeting stays on the brief instead of vanishing the moment it\n  // begins.\n  const r = await api.db.prepare(`\n    SELECT id, kind, title, description, starts_at, ends_at, all_day, status,\n           location, link_url, platform\n      FROM calendar_events\n     WHERE starts_at <= ?\n       AND COALESCE(ends_at, starts_at + 3600000) >= ?\n       AND status != ''cancelled''\n     ORDER BY starts_at ASC\n     LIMIT 50\n  `).bind(horizon, nowMs).all();\n  for (const e of (r.results || [])) {\n    if (snoozed.has(`ref:calendar_events:${e.id}`)) continue;\n    const startsIn = e.starts_at - nowMs;\n    const minutes  = Math.round(startsIn / 60000);\n    let when;\n    if (Math.abs(minutes) < 60) when = minutes <= 0 ? ''now'' : `in ${minutes}m`;\n    else if (Math.abs(minutes) < 1440) when = `in ${Math.round(minutes / 60)}h`;\n    else when = `${new Date(e.starts_at).toLocaleString(undefined, { weekday: ''short'', hour: ''numeric'', minute: ''2-digit'' })}`;\n\n    // Urgency: soon = high; today = medium; later = low.\n    const urgency = minutes < 60 ? 1 : minutes < 12 * 60 ? 2 : 3;\n    const inserted_ = await insertDigestItem(api, {\n      id: ''cal_'' + e.id,\n      kind: ''opportunity'', // reads as \"upcoming\" under the amber chip\n      ref_kind: ''calendar_events'',\n      ref_id:   e.id,\n      title:    `${e.title} · ${when}`,\n      summary:  e.description || (e.location ? `Location: ${e.location}` : null),\n      source_label: `Calendar · ${e.kind || ''event''}`,\n      source_url:   e.link_url,\n      urgency,\n      actionable: 1,\n      suggested_action: e.kind === ''meeting'' ? ''Open invite'' : ''Confirm / prep'',\n    }, { refresh: true }); // re-run updates urgency + \"when\" as the meeting nears\n    if (inserted_) inserted.push(inserted_.id);\n  }\n  return inserted;\n}\n\n// ─── prune ───────────────────────────────────────────────────────────────\n// Sweep stale cards off the brief. Anything older than stale_after_days that\n// is not starred AND not urgency=1 gets soft-archived (read_at set): the row\n// stays for audit, it just stops topping the brief. Well past that,\n// delete_after_days hard-deletes read, unstarred, non-urgent rows so the\n// table never grows without bound. The pullers dedupe on stable ids, so a\n// deleted card that is still current simply comes back fresh.\nexport async function pruneStaleDigestItems(api, { staleAfterMs = null } = {}) {\n  const policy = await loadDigestPolicy(api);\n  const cutoff = now() - (staleAfterMs ?? policy.stale_after_days * 24 * 60 * 60 * 1000);\n  const r = await api.db.prepare(\n    `UPDATE plugin_digest_items\n        SET read_at = ?\n      WHERE read_at IS NULL\n        AND starred = 0\n        AND urgency != 1\n        AND created_at < ?`,\n  ).bind(now(), cutoff).run();\n  const pruned = r?.meta?.changes ?? r?.changes ?? 0;\n\n  const delCutoff = now() - policy.delete_after_days * 24 * 60 * 60 * 1000;\n  const d = await api.db.prepare(\n    `DELETE FROM plugin_digest_items\n      WHERE read_at IS NOT NULL\n        AND starred = 0\n        AND urgency != 1\n        AND created_at < ?`,\n  ).bind(delCutoff).run();\n  const deleted = d?.meta?.changes ?? d?.changes ?? 0;\n\n  if (pruned > 0 || deleted > 0) {\n    await api.log(''digest_pruned_stale'', { pruned, deleted, cutoff_ms: cutoff, delete_cutoff_ms: delCutoff, stale_after_ms: staleAfterMs });\n  }\n  return { pruned, deleted, cutoff };\n}\n\n// ─── generate ────────────────────────────────────────────────────────────\n// A digest has nothing to say before the install is onboarded: no search\n// provider, no calendar rows, no prior items, no setup receipt. Instead of\n// day-zero noise the run points the operator at Nyo to onboard.\nasync function isFreshUnonboarded(api) {\n  const anyItem = await api.db.prepare(''SELECT id FROM plugin_digest_items LIMIT 1'').first().catch(() => null);\n  if (anyItem) return false;\n  const receipt = await api.gateway(''setup'', ''read'', { module: ''digest'' }).catch(() => null);\n  if (receipt) return false;\n  let providers = 0;\n  try { providers = (await api.discoverGateways(''search'')).length; } catch { providers = 0; }\n  if (providers > 0) return false;\n  const anyEvent = await api.db.prepare(''SELECT id FROM calendar_events LIMIT 1'').first().catch(() => null);\n  return !anyEvent;\n}\n\nexport async function generateDigest(api, { since_ms = 24 * 60 * 60 * 1000 } = {}) {\n  const nowMs = now();\n  const inserted = [];\n  const perSource = {};\n\n  if (await isFreshUnonboarded(api)) {\n    return {\n      ok: true,\n      onboarding_needed: true,\n      note: ''Nothing to digest yet: this install has no sources connected. Ask Nyo to onboard: install a search provider and set your topics, or connect the calendar, and the digest starts filling on its own.'',\n      inserted: 0, per_source: {}, archived: 0,\n    };\n  }\n  // Step 0: archive anything that has gone stale since the last run. The\n  // count flows back so the page can show \"N archived\" beside the +N adds.\n  const prune = await pruneStaleDigestItems(api);\n\n  // A source runs only while its backing exists on THIS install, probed live\n  // every run: a search provider installed means search runs; a readable\n  // calendar mirror means calendar runs. The knobs that matter (topics,\n  // caps, sources_off) live in Knowledge.\n  const probeTable = async (table) => {\n    try { await api.db.prepare(`SELECT 1 FROM ${table} LIMIT 1`).all(); return true; }\n    catch { return false; }\n  };\n  const available = {\n    search: async () => { try { return (await api.discoverGateways(''search'')).length > 0; } catch { return false; } },\n    calendar: () => probeTable(''calendar_events''),\n  };\n  const policy = await loadDigestPolicy(api);\n  const off = new Set(Array.isArray(policy.sources_off) ? policy.sources_off.map(String) : []);\n  async function maybeRun(source, runFn) {\n    if (off.has(source)) { perSource[source] = { count: 0, skipped: ''off in policy'' }; return; }\n    let on = false;\n    try { on = await available[source](); } catch { on = false; }\n    if (!on) {\n      perSource[source] = { count: 0, skipped: ''not on this install'' };\n      return;\n    }\n    let added = 0, softErr = null, hardErr = null;\n    try {\n      // A puller returns either `string[]` (just ids, success) or\n      // `{ ids, error }` (success or partial plus a soft note). A soft error\n      // is NOT a failure: data landed, or there was simply nothing to digest.\n      // Only a thrown error is a real failure.\n      const r = await runFn();\n      const ids   = Array.isArray(r) ? r : (r?.ids || []);\n      softErr     = Array.isArray(r) ? null : (r?.error || null);\n      inserted.push(...ids);\n      added = ids.length;\n    } catch (e) {\n      hardErr = String(e?.message || e);\n    }\n    const error = hardErr || softErr;\n    perSource[source] = { count: added, error };\n  }\n\n  await maybeRun(''search'',   () => pullSearch(api));\n  await maybeRun(''calendar'', () => pullCalendar(api, nowMs));\n\n  await api.log(''digest_generated'', { count: inserted.length, per_source: perSource, pruned: prune.pruned });\n  return { generated: inserted.length, pruned: prune.pruned, since_ms, per_source: perSource };\n}\n\nexport async function digestStats(api) {\n  const r = await api.db.prepare(`\n    SELECT\n      COUNT(*)                                                AS total,\n      SUM(CASE WHEN read_at IS NULL THEN 1 ELSE 0 END)        AS unread,\n      SUM(CASE WHEN read_at IS NULL AND urgency = 1 THEN 1 ELSE 0 END) AS high,\n      SUM(CASE WHEN read_at IS NULL AND actionable = 1 THEN 1 ELSE 0 END) AS action_count,\n      SUM(CASE WHEN starred = 1 THEN 1 ELSE 0 END)            AS starred\n    FROM plugin_digest_items\n  `).first();\n  // The most recent generate() run, read off the activity bus (events is a\n  // declared host_read). api.log prefixes kinds with plugin_digest_, so the\n  // generate event lands as ''plugin_digest_digest_generated''.\n  const last = await api.db.prepare(\n    `SELECT created_at FROM events WHERE kind = ''plugin_digest_digest_generated'' ORDER BY created_at DESC LIMIT 1`\n  ).first();\n  return {\n    ...(r || { total: 0, unread: 0, high: 0, action_count: 0, starred: 0 }),\n    last_generated_at: last?.created_at || null,\n  };\n}\n"},{"path":"digest-relevance.mjs","code":"// Digest plugin — the consideration layer. Ported from\n// workers/api/src/lib/digest-relevance.js under the plugin capability\n// contract: every function takes `api` first; this file imports NOTHING.\n//\n// Learns from what the operator DISMISSES and feeds it back into the digest''s\n// interest filter, so the same uninteresting items stop showing up.\n//\n// The digest generator already weighs the `plugin-digest-interests`\n// knowledge doc when deciding which items to surface vs drop (see digest.mjs).\n// The gap was that the doc was static. This closes the loop: it reads\n// recently-dismissed items, distills the patterns behind them through the\n// `llm` gateway, and rewrites a \"Learned from your dismissals\" section of that\n// same doc. No new surface — the existing generator consumes the improved doc\n// on its next run.\n//\n// Reaches the model ONLY through the `llm` gateway; the rule set lives in the\n// editable knowledge doc; every learning pass logs.\n//\n// State note (port): the host version tracked \"last learn at\" in the\n// feature_flags table. feature_flags is host-owned and SELECT-only for\n// plugins, so the marker now lives on the activity bus instead: every\n// completed learn pass logs `digest_learn_pass` (which api.log lands as kind\n// ''plugin_digest_digest_learn_pass''), and the next run reads the newest\n// such row from the declared `events` host_read. Same semantics, no host\n// table write.\n\nconst now = () => Date.now();\n\nconst DOC_SLUG = ''plugin-digest-interests'';\nconst LEARN_MARK = ''\\n\\n## Learned — auto-tuned from your dismissals\\n'';\n// api.log prefixes with plugin_digest_ — this is the stored `kind`.\nconst LEARN_PASS_EVENT_KIND = ''plugin_digest_digest_learn_pass'';\n\nconst LEARN_SYSTEM = `You maintain the \"avoid\" rules for an operator''s morning digest.\n\nYou are given (a) the operator''s current interest profile, and (b) a list of digest\nitems they recently DISMISSED without acting on (a strong signal they don''t want to\nsee that kind of thing). Distill the dismissals into a SHORT list of concrete,\ngeneral patterns the digest should stop surfacing — by topic, source, sender type,\nor shape (e.g. \"automated delivery/OTP notifications\", \"group banter with no ask\",\n\"newsletters about X\"). Be specific enough to act on, general enough to catch\nfuture look-alikes. Do NOT contradict things the profile says ARE wanted, and do\nNOT suppress anything that looks like a real business opportunity, a client\nmessage, or a direct question to the operator.\n\nReturn STRICT JSON: {\"avoid\":[\"pattern 1\",\"pattern 2\", ...]}  (max 12, most common first).`;\n\n// How many NEW dismissals (since the last learn) before it''s worth a pass.\nconst MIN_NEW_DISMISSALS = 6;\n\n// The cheap utility model for the distillation pass. The host read the\n// `llm-models` knowledge doc (writer_small field) through loadModelConfig;\n// the plugin reads the same doc via a declared requires.knowledge grant.\n// A missing/unparseable doc simply omits `model` so the llm gateway''s own\n// default applies (model choice stays in knowledge, never a code literal).\nasync function writerSmallModel(api) {\n  try {\n    const doc = await api.knowledge(''llm-models'');\n    const m = String(doc?.body || '''').match(/```json\\s*([\\s\\S]*?)```/);\n    const src = m ? JSON.parse(m[1]) : {};\n    const v = String(src.writer_small ?? '''').trim();\n    return v && v.length <= 120 && !/\\s{2,}|\\n/.test(v) ? v : undefined;\n  } catch { return undefined; }\n}\n\n// When did the last learn pass run? Newest learn-pass row on the activity\n// bus (events is a declared SELECT-only host_read). 0 when never.\nasync function lastLearnAt(api) {\n  try {\n    const row = await api.db.prepare(\n      `SELECT created_at FROM events WHERE kind = ? ORDER BY created_at DESC LIMIT 1`,\n    ).bind(LEARN_PASS_EVENT_KIND).first();\n    return Number(row?.created_at || 0);\n  } catch { return 0; }\n}\n\nexport async function learnFromDismissals(api, { force = false, lookbackDays = 21 } = {}) {\n  const lastLearn = await lastLearnAt(api);\n  const lookbackMs = lookbackDays * 24 * 60 * 60 * 1000;\n  const since = Date.now() - lookbackMs;\n\n  // Negative signal: dismissed (read), not starred, not acted. `read_at` is set\n  // when the operator hits ✕. Starred items are explicit keeps — never learn\n  // \"avoid\" from them.\n  let dismissed = [];\n  try {\n    dismissed = (await api.db.prepare(\n      `SELECT kind, title, summary, read_at FROM plugin_digest_items\n       WHERE read_at IS NOT NULL AND starred = 0 AND created_at >= ?\n       ORDER BY read_at DESC LIMIT 80`,\n    ).bind(since).all()).results || [];\n  } catch { return { ok: false, error: ''digest_items unavailable'' }; }\n\n  const newDismissals = dismissed.filter((d) => (d.read_at || 0) > lastLearn).length;\n  if (!force && newDismissals < MIN_NEW_DISMISSALS) {\n    return { ok: true, learned: false, new_dismissals: newDismissals, need: MIN_NEW_DISMISSALS };\n  }\n  if (!dismissed.length) return { ok: true, learned: false, new_dismissals: 0 };\n\n  const doc = await api.knowledge(DOC_SLUG);\n  const base = String(doc?.body || '''').split(LEARN_MARK)[0].trimEnd();\n  const profileForModel = base;\n  const items = dismissed.slice(0, 60).map((d, i) => `[${i}] (${d.kind}) ${String(d.title || '''').slice(0, 140)}${d.summary ? '' — '' + String(d.summary).slice(0, 120) : ''''}`).join(''\\n'');\n\n  const model = await writerSmallModel(api);\n  let out;\n  try {\n    out = await api.gateway(''llm'', ''json'', {\n      system: LEARN_SYSTEM,\n      prompt: `CURRENT INTEREST PROFILE:\\n${profileForModel}\\n\\nRECENTLY DISMISSED (${dismissed.length}):\\n${items}\\n\\nProduce the JSON.`,\n      model, max_tokens: 900,\n    });\n  } catch (e) {\n    return { ok: false, error: `llm: ${String(e?.message || e)}` };\n  }\n  const avoid = Array.isArray(out?.avoid) ? out.avoid.filter((s) => typeof s === ''string'' && s.trim()).slice(0, 12) : [];\n  if (!avoid.length) {\n    // Advance the marker even with nothing learned — same role as the host''s\n    // flag write: don''t re-run the LLM on the same dismissal set tomorrow.\n    await api.log(''digest_learn_pass'', { learned: false, from_dismissals: dismissed.length });\n    return { ok: true, learned: false, new_dismissals: newDismissals };\n  }\n\n  const learnedSection = `_Auto-maintained from items you dismissed. The generator treats these as low-interest; edit or delete freely — they''ll be re-derived on the next pass._\\n\\n${avoid.map((a) => `- ${a}`).join(''\\n'')}`;\n  const newBody = `${base}${LEARN_MARK}${learnedSection}\\n`;\n  await api.saveKnowledge(DOC_SLUG, { title: doc?.title || ''Nyyon — what counts as \\''of interest\\'' for the digest'', body: newBody });\n  await api.log(''digest_learn_pass'', { learned: true, avoid_count: avoid.length });\n  await api.log(''digest_interests_learned'', { avoid_count: avoid.length, from_dismissals: dismissed.length });\n  return { ok: true, learned: true, avoid, from_dismissals: dismissed.length };\n}\n"},{"path":"signal-priority.mjs","code":"// Digest plugin: signal priority, the reasoning layer over digest cards.\n// Under the plugin capability contract (api first, imports NOTHING).\n//\n// A scored card gets a 0-100 relevance score plus a stated reason, so the\n// brief reads most-relevant first and background noise last. The rubric,\n// the scoring prompt, which kinds get scored, and every threshold live in\n// the plugin-digest-signal-priority knowledge doc; the score maps onto the\n// digest''s urgency groups (high / mid / low) and the raw score + reason\n// persist on the item''s meta. The operator''s interest profile\n// (plugin-digest-interests) rides along in the prompt, and taste_rules grow\n// from his comments on scores.\n//\n// Snooze lives here too: \"keep this out of the brief for a while\" keyed the\n// same way digest.mjs keys it (a news card mutes its outlet, a card derived\n// from a host row mutes that row, anything else mutes itself). The key\n// builder is duplicated from digest.mjs on purpose: lib files may not import\n// each other.\n// Tables: plugin_digest_items, plugin_digest_signal_snoozes (own).\n// Gateway: llm(text).\n\nconst now = () => Date.now();\n\nconst DOC_SLUG = ''plugin-digest-signal-priority'';\n\nconst DEFAULT_PROMPT = `You score ONE card from an operator''s morning digest for how much of their attention it deserves today, 0-100.\n\nScore bands:\n- 70-100 act on it: a concrete, timely development the operator should react to or that directly touches what they track (their named topics, markets, products, competitors).\n- 40-69 worth knowing: relevant background, a real development in an adjacent area, something to skim.\n- 0-39 can wait: evergreen filler, listicles, reviews, vendor press releases, coincidental keyword matches, anything that gives no reason to act.\n\nJudge what the card gives the operator to DO or LEARN, not how loud the headline is. Return STRICT JSON: {\"score\": <0-100>, \"reason\": \"<one short sentence naming why it matters or why it does not>\"}`;\n\nconst DEFAULT_FEEDBACK_PROMPT = ''You maintain a short list of durable TASTE rules describing how an operator wants their digest cards prioritized. Given a card, the scorer\\''s verdict, and the operator\\''s comment on that verdict, extract at most 2 NEW durable rules (what they value, what bores them, how to weigh kinds of news), merge with the existing rules, drop duplicates and one-off gripes, keep under {max} rules, each short and imperative. Return STRICT JSON: {\"rules\":[\"...\"]}'';\n\nconst DEFAULTS = {\n  prompt: DEFAULT_PROMPT,\n  urgency_thresholds: { high: 70, mid: 40 },\n  // which card kinds the sweep scores; calendar cards keep their clock-based\n  // urgency and are left alone\n  score_kinds: [''news''],\n  batch_limit: 10,\n  taste_rules: [],\n  max_taste_rules: 20,\n  feedback_prompt: DEFAULT_FEEDBACK_PROMPT,\n  // ''snooze'' on a card mutes its key for this long\n  snooze_days: 7,\n};\n\nconst seedBody = (cfg = DEFAULTS) => `# Signal priority\n\nThe reasoning rubric behind digest ordering: every card of a scored kind is\nscored 0-100 for the attention it deserves, with a one-line reason, and the\nscore maps to the brief''s urgency groups. score_kinds picks which kinds get\nscored (calendar cards keep their clock-based urgency). taste_rules grow\nfrom the operator''s comments on scores (the chip''s comment box) and bind\nevery future score. snooze_days is how long a snoozed card''s key stays\nmuted. Edit anything here; no deploy needed.\n\n\\`\\`\\`json\n${JSON.stringify(cfg, null, 2)}\n\\`\\`\\`\n`;\n\nexport async function signalPriorityCfg(api) {\n  let doc = null;\n  try { doc = await api.knowledge(DOC_SLUG); } catch { doc = null; }\n  if (!doc) {\n    await api.saveKnowledge(DOC_SLUG, { title: ''Signal priority'', body: seedBody() }).catch(() => {});\n    doc = { body: seedBody() };\n  }\n  try {\n    const m = String(doc.body || '''').match(/```json\\s*([\\s\\S]*?)```/);\n    const parsed = m ? JSON.parse(m[1]) : null;\n    if (parsed && typeof parsed === ''object'') return { ...DEFAULTS, ...parsed };\n  } catch { /* malformed edit must not break scoring: defaults win */ }\n  return DEFAULTS;\n}\n\n// The operator''s interest profile, when present, steers the scorer.\nasync function interestProfile(api) {\n  try {\n    const doc = await api.knowledge(''plugin-digest-interests'');\n    const body = String(doc?.body || '''').trim();\n    return body ? `\\n\\nOPERATOR''S INTEREST PROFILE (weigh the card against this):\\n${body.slice(0, 4000)}` : '''';\n  } catch { return ''''; }\n}\n\n// Score ONE digest item: the llm rubric + interest profile + taste rules.\n// Persists meta.priority / meta.priority_reason, remaps the item''s urgency,\n// logs signal_scored. Idempotent: rescoring overwrites.\nexport async function scoreSignalItem(api, id) {\n  const cfg = await signalPriorityCfg(api);\n  const item = await api.db.prepare(\n    ''SELECT id, kind, title, summary, source_label, urgency, meta_json FROM plugin_digest_items WHERE id = ?'',\n  ).bind(id).first();\n  if (!item) return { ok: false, error: ''digest item not found'' };\n  let meta = {};\n  try { meta = JSON.parse(item.meta_json || ''{}''); } catch { meta = {}; }\n\n  const taste = Array.isArray(cfg.taste_rules) && cfg.taste_rules.length\n    ? `\\n\\nOPERATOR TASTE, learned from their feedback. Weigh these over the generic bands:\\n${cfg.taste_rules.map((r) => ''- '' + r).join(''\\n'')}`\n    : '''';\n  const profile = await interestProfile(api);\n  const raw = await api.gateway(''llm'', ''text'', {\n    system: cfg.prompt + profile + taste,\n    prompt: `Kind: ${item.kind}\nSource: ${item.source_label || ''?''}\nTitle: ${item.title}\nSummary: ${String(item.summary || '''').slice(0, 600)}`,\n    max_tokens: 300,\n  });\n  const s = String(raw || '''');\n  let score = 50, reason = ''unscored'';\n  try {\n    const j = JSON.parse(s.slice(s.indexOf(''{''), s.lastIndexOf(''}'') + 1));\n    score = Math.max(0, Math.min(100, Number(j.score) || 0));\n    reason = String(j.reason || '''').slice(0, 240) || ''no reason given'';\n  } catch { return { ok: false, error: ''scorer returned no parseable verdict'' }; }\n\n  const th = cfg.urgency_thresholds || DEFAULTS.urgency_thresholds;\n  const urgency = score >= (Number(th.high) || 70) ? 1 : score >= (Number(th.mid) || 40) ? 2 : 3;\n\n  meta.priority = score;\n  meta.priority_reason = reason;\n  meta.priority_at = now();\n  await api.db.prepare(''UPDATE plugin_digest_items SET urgency = ?, meta_json = ? WHERE id = ?'')\n    .bind(urgency, JSON.stringify(meta), id).run();\n  await api.log(''signal_scored'', { id, score, urgency });\n  return { ok: true, id, score, urgency, reason };\n}\n\n// Score every unread, unscored card of a scored kind (bounded per run by\n// batch_limit). Safe to call spuriously; already-scored items are skipped.\nexport async function sweepSignalPriorities(api, { limit } = {}) {\n  const cfg = await signalPriorityCfg(api);\n  const cap = Math.max(1, Math.min(25, Number(limit) || Number(cfg.batch_limit) || 10));\n  const kinds = (Array.isArray(cfg.score_kinds) ? cfg.score_kinds : DEFAULTS.score_kinds)\n    .map((k) => String(k)).filter(Boolean);\n  if (!kinds.length) return { ok: true, scored: 0, pending: 0, results: [] };\n  // Unscored selected in SQL, so no recency window can strand old cards:\n  // every unread card is eventually scored, newest first.\n  const rows = (await api.db.prepare(\n    `SELECT id FROM plugin_digest_items\n     WHERE kind IN (${kinds.map(() => ''?'').join('','')}) AND read_at IS NULL\n       AND json_extract(meta_json, ''$.priority_at'') IS NULL\n     ORDER BY created_at DESC LIMIT ?`,\n  ).bind(...kinds, cap).all()).results || [];\n  const out = [];\n  for (const r of rows) {\n    out.push(await scoreSignalItem(api, r.id).catch((e) => ({ ok: false, id: r.id, error: String(e?.message || e) })));\n  }\n  const scored = out.filter((x) => x.ok).length;\n  if (scored) await api.log(''signals_prioritized'', { scored, of: rows.length });\n  return { ok: true, scored, pending: rows.length, results: out };\n}\n\n// Operator comment on a score: durable taste rules, then an immediate\n// rescore under the updated rubric so the effect shows at once.\nexport async function distillPriorityFeedback(api, id, comment) {\n  const text = String(comment || '''').trim();\n  if (!text) return { ok: false, error: ''comment required'' };\n  const cfg = await signalPriorityCfg(api);\n  const item = await api.db.prepare(\n    ''SELECT id, kind, title, source_label, meta_json FROM plugin_digest_items WHERE id = ?'',\n  ).bind(id).first();\n  if (!item) return { ok: false, error: ''digest item not found'' };\n  let meta = {};\n  try { meta = JSON.parse(item.meta_json || ''{}''); } catch { meta = {}; }\n\n  const raw = await api.gateway(''llm'', ''text'', {\n    system: (cfg.feedback_prompt || DEFAULT_FEEDBACK_PROMPT).replace(''{max}'', String(cfg.max_taste_rules || 20)),\n    prompt: `EXISTING RULES:\\n${JSON.stringify(cfg.taste_rules || [])}\\n\\nCARD (${item.kind}, ${item.source_label || ''?''}): ${item.title}\\nSCORER''S VERDICT: P${meta.priority ?? ''?''}: ${meta.priority_reason || ''?''}\\n\\nOPERATOR''S COMMENT:\\n\"${text.slice(0, 600)}\"`,\n    max_tokens: 600,\n  });\n  const sRaw = String(raw || '''');\n  let rules;\n  try {\n    const j = JSON.parse(sRaw.slice(sRaw.indexOf(''{''), sRaw.lastIndexOf(''}'') + 1));\n    rules = (Array.isArray(j.rules) ? j.rules : []).filter((r) => typeof r === ''string'' && r.trim())\n      .slice(0, Number(cfg.max_taste_rules) || 20);\n  } catch { return { ok: false, error: ''feedback distiller returned no parseable rules'' }; }\n\n  const next = { ...cfg, taste_rules: rules };\n  await api.saveKnowledge(DOC_SLUG, { title: ''Signal priority'', body: seedBody(next) });\n  await api.log(''signal_feedback'', { id, comment: text.slice(0, 240), rules: rules.length });\n  const rescored = await scoreSignalItem(api, id);\n  return { ok: true, rules: rules.length, rescored };\n}\n\n// ── snooze: keep this out of the brief for a while ──────────────\n// Same key shape as digest.mjs''s digestSnoozeKey (duplicated by contract).\nexport function snoozeKeyFor(item) {\n  if (!item) return null;\n  const label = String(item.source_label || '''').trim().toLowerCase();\n  if (item.kind === ''news'' && label) return ''source:'' + label;\n  if (item.ref_kind && item.ref_id) return `ref:${item.ref_kind}:${item.ref_id}`;\n  return ''item:'' + item.id;\n}\n\n// Is this key muted right now?\nexport async function isSnoozed(api, key) {\n  if (!key) return null;\n  const row = await api.db.prepare(\n    ''SELECT key, until FROM plugin_digest_signal_snoozes WHERE until > ? AND key = ? LIMIT 1'',\n  ).bind(now(), key).first().catch(() => null);\n  return row || null;\n}\n\n// Snooze the card''s key for snooze_days: archives the card and its unread\n// siblings on the same key (deps.archiveItemsByKey from ./digest.mjs, wired\n// by the calling tool) and keeps new arrivals on that key out of the brief\n// until the snooze expires.\nexport async function snoozeItem(api, id, deps = {}) {\n  const cfg = await signalPriorityCfg(api);\n  const item = await api.db.prepare(\n    ''SELECT id, kind, ref_kind, ref_id, source_label, title FROM plugin_digest_items WHERE id = ?'',\n  ).bind(id).first();\n  if (!item) return { ok: false, error: ''digest item not found'' };\n  const key = snoozeKeyFor(item);\n  if (!key) return { ok: false, error: ''nothing identifies this card'' };\n  const days = Number(cfg.snooze_days) || 7;\n  const until = now() + days * 24 * 60 * 60 * 1000;\n  const label = key.startsWith(''source:'') ? (item.source_label || null) : String(item.title || '''').slice(0, 120);\n  await api.db.prepare(\n    `INSERT INTO plugin_digest_signal_snoozes (key, until, label, reason, created_at) VALUES (?, ?, ?, ''snoozed by the operator'', ?)\n     ON CONFLICT(key) DO UPDATE SET until = MAX(plugin_digest_signal_snoozes.until, excluded.until), label = excluded.label`,\n  ).bind(key, until, label, now()).run();\n  const archived = typeof deps.archiveItemsByKey === ''function''\n    ? await deps.archiveItemsByKey(api, key, { except_id: id })\n    : 0;\n  await api.db.prepare(''UPDATE plugin_digest_items SET read_at = ? WHERE id = ?'').bind(now(), id).run();\n  await api.log(''signal_snoozed'', { id, key, days, until, archived: archived + 1 });\n  return { ok: true, key, until, days, archived: archived + 1 };\n}\n\n// Undo: wake a key again. Identify it by the card that was snoozed or by the\n// key itself (e.g. \"source:techcrunch\").\nexport async function unsnoozeItem(api, { digest_id = null, key = null } = {}) {\n  let k = key ? String(key) : null;\n  if (!k && digest_id) {\n    const item = await api.db.prepare(\n      ''SELECT id, kind, ref_kind, ref_id, source_label FROM plugin_digest_items WHERE id = ?'',\n    ).bind(digest_id).first();\n    if (!item) return { ok: false, error: ''digest item not found'' };\n    k = snoozeKeyFor(item);\n  }\n  if (!k) return { ok: false, error: ''pass digest_id or key'' };\n  const r = await api.db.prepare(''DELETE FROM plugin_digest_signal_snoozes WHERE key = ?'').bind(k).run();\n  await api.log(''signal_unsnoozed'', { key: k, removed: r.meta?.changes || 0 });\n  return { ok: true, key: k, removed: r.meta?.changes || 0 };\n}\n"}],"requires":{"gateways":[{"slug":"llm","modes":["json","text"],"purpose":"card scoring, the taste distiller, the dismissal learner"},{"slug":"setup","modes":["read"],"purpose":"first-run receipt: a fresh un-onboarded install gets the Nyo onboarding pointer instead of day-zero noise"},{"slug":"web","modes":["text"],"purpose":"read the operator website during digest setup"}],"host_reads":[{"table":"calendar_events","purpose":"the calendar source''s look-ahead cards; the drawer''s event context"},{"table":"events","purpose":"activity-bus reads: last-generated stamp, dismissal-learning marker"}],"knowledge":[{"slug":"llm-models","purpose":"writer_small model id for the light dismissal-learning pass"}],"tables":[{"name":"plugin_digest_items","ddl":"CREATE TABLE IF NOT EXISTS plugin_digest_items (id TEXT PRIMARY KEY, kind TEXT NOT NULL, ref_kind TEXT, ref_id TEXT, title TEXT NOT NULL, summary TEXT, source_label TEXT, source_url TEXT, urgency INTEGER NOT NULL DEFAULT 2, actionable INTEGER NOT NULL DEFAULT 0, suggested_action TEXT, starred INTEGER NOT NULL DEFAULT 0, read_at INTEGER, created_at INTEGER NOT NULL, meta_json TEXT); CREATE INDEX IF NOT EXISTS idx_plugin_digest_items_created_at ON plugin_digest_items (created_at); CREATE INDEX IF NOT EXISTS idx_plugin_digest_items_read_at ON plugin_digest_items (read_at)"},{"name":"plugin_digest_signal_snoozes","ddl":"CREATE TABLE IF NOT EXISTS plugin_digest_signal_snoozes (key TEXT PRIMARY KEY, until INTEGER NOT NULL, label TEXT, reason TEXT, created_at INTEGER NOT NULL, engaged_count INTEGER NOT NULL DEFAULT 0, last_engaged_at INTEGER); CREATE INDEX IF NOT EXISTS idx_plugin_digest_signal_snoozes_until ON plugin_digest_signal_snoozes (until)"}],"capabilities":[{"capability":"search","mode":"search","purpose":"headline lookups for the search source''s topics: any installed search provider"}]},"provides":{"tools":[{"name":"add_digest_item","def":{"name":"add_digest_item","description":"Manually drop something into the digest. Use when the operator says \"remind me about X tomorrow\" or \"add this to the brief\". Kind=opportunity for net-new chances; kind=note for free-form items; kind=news for a headline with a link.","input_schema":{"type":"object","properties":{"kind":{"type":"string","enum":["opportunity","note","news"]},"title":{"type":"string"},"summary":{"type":"string"},"source_label":{"type":"string"},"source_url":{"type":"string"},"urgency":{"type":"number","description":"1 high · 2 medium · 3 low"},"actionable":{"type":"boolean"},"suggested_action":{"type":"string"}},"required":["kind","title"]}},"code":"// Digest plugin: add_digest_item. Drops a card into the brief by hand.\n\nimport { insertDigestItem } from ''./digest.mjs'';\n\nexport const def = {\n  name: ''add_digest_item'',\n  description: ''Manually drop something into the digest. Use when the operator says \"remind me about X tomorrow\" or \"add this to the brief\". Kind=opportunity for net-new chances; kind=note for free-form items; kind=news for a headline with a link.'',\n  input_schema: {\n    type: ''object'',\n    properties: {\n      kind:             { type: ''string'', enum: [''opportunity'', ''note'', ''news''] },\n      title:            { type: ''string'' },\n      summary:          { type: ''string'' },\n      source_label:     { type: ''string'' },\n      source_url:       { type: ''string'' },\n      urgency:          { type: ''number'', description: ''1 high · 2 medium · 3 low'' },\n      actionable:       { type: ''boolean'' },\n      suggested_action: { type: ''string'' },\n    },\n    required: [''kind'', ''title''],\n  },\n};\n\nexport async function run(api, input) {\n  return {\n    item: await insertDigestItem(api, {\n      kind:       input.kind,\n      title:      input.title,\n      summary:    input.summary,\n      source_label: input.source_label,\n      source_url:   input.source_url,\n      urgency:    input.urgency ?? 2,\n      actionable: input.actionable ? 1 : 0,\n      suggested_action: input.suggested_action,\n    }),\n  };\n}\n"},{"name":"clear_read_digest","def":{"name":"clear_read_digest","description":"Delete every already-read digest item (the archive sweep). Unread and starred items stay. Use when the operator asks to clean the brief''s history.","input_schema":{"type":"object","properties":{},"required":[]}},"code":"// Digest plugin — clear_read_digest. cmd fronted this with\n// POST /api/digest/clear-read; same lib atom.\n\nimport { clearReadDigestItems } from ''./digest.mjs'';\n\nexport const def = {\n  name: ''clear_read_digest'',\n  description: ''Delete every already-read digest item (the archive sweep). Unread and starred items stay. Use when the operator asks to clean the brief\\''s history.'',\n  input_schema: { type: ''object'', properties: {}, required: [] },\n};\n\nexport async function run(api) {\n  return clearReadDigestItems(api);\n}\n"},{"name":"digest_actions","def":{"name":"digest_actions","description":"List the actions an operator can take on one digest item: open its link, mark it read (or unread), star it, save a draft note on it, or snooze it (a news card snoozes its outlet, a calendar card snoozes that event). Returns the item, its context, and the action list; run one with execute_digest_action.","input_schema":{"type":"object","properties":{"id":{"type":"string"}},"required":["id"]}},"code":"// Digest plugin: digest_actions. The verbs an operator can run on one card\n// (open link, mark read, star, save a draft note, snooze). No drafting, no\n// LLM: the list is mechanical and cheap.\n\nimport { draftDigestActions } from ''./digest.mjs'';\n\nexport const def = {\n  name: ''digest_actions'',\n  description: ''List the actions an operator can take on one digest item: open its link, mark it read (or unread), star it, save a draft note on it, or snooze it (a news card snoozes its outlet, a calendar card snoozes that event). Returns the item, its context, and the action list; run one with execute_digest_action.'',\n  input_schema: {\n    type: ''object'',\n    properties: { id: { type: ''string'' } },\n    required: [''id''],\n  },\n};\n\nexport async function run(api, input) {\n  return draftDigestActions(api, input.id);\n}\n"},{"name":"digest_context","def":{"name":"digest_context","description":"Source-enriched context for one digest item: the item itself, and for calendar cards the underlying calendar event (time, location, link). Use before discussing an item or deciding what to do with it.","input_schema":{"type":"object","properties":{"id":{"type":"string"}},"required":["id"]}},"code":"// Digest plugin: digest_context. The card plus its source row: a calendar\n// card carries the calendar_events row it came from; a news card is\n// self-contained (headline, link, topic).\n\nimport { getDigestItemContext } from ''./digest.mjs'';\n\nexport const def = {\n  name: ''digest_context'',\n  description: ''Source-enriched context for one digest item: the item itself, and for calendar cards the underlying calendar event (time, location, link). Use before discussing an item or deciding what to do with it.'',\n  input_schema: {\n    type: ''object'',\n    properties: { id: { type: ''string'' } },\n    required: [''id''],\n  },\n};\n\nexport async function run(api, input) {\n  const ctx = await getDigestItemContext(api, input.id);\n  if (!ctx) return { error: ''not found'' };\n  return ctx;\n}\n"},{"name":"digest_sources","def":{"name":"digest_sources","description":"What feeds the Digest on this install: installed search providers (discovered by capability), whether the calendar source is present, and the watched topics. Use to answer \"where does my brief pull from?\" or before onboarding.","input_schema":{"type":"object","properties":{},"required":[]}},"code":"export const def = {\n  name: ''digest_sources'',\n  description: ''What feeds the Digest on this install: installed search providers (discovered by capability), whether the calendar source is present, and the watched topics. Use to answer \"where does my brief pull from?\" or before onboarding.'',\n  input_schema: { type: ''object'', properties: {}, required: [] },\n};\nexport async function run(api) {\n  let providers = [];\n  try {\n    const found = await api.discoverGateways(''search'');\n    providers = await Promise.all(found.map(async (p) => {\n      let st = null; try { st = p.status ? await p.status() : null; } catch { st = null; }\n      return { slug: p.slug, label: st?.label || p.label, connected: st ? !!st.connected : true, note: st?.note || null };\n    }));\n  } catch { providers = []; }\n  let calendar = false;\n  try { await api.db.prepare(''SELECT 1 FROM calendar_events LIMIT 1'').all(); calendar = true; } catch { calendar = false; }\n  let topics = [];\n  try {\n    const doc = await api.knowledge(''plugin-digest-search-topics'');\n    topics = String(doc?.body || '''').split(''\\n'').map((l) => l.trim()).filter((l) => l && !l.startsWith(''#''));\n  } catch { topics = []; }\n  const configured = topics.length > 0 && !(topics.length === 1 && topics[0] === ''AI agents'');\n  return { ok: true, providers, calendar, topics, configured, ready: configured && providers.some((p) => p.connected) };\n}\n"},{"name":"digest_stats","def":{"name":"digest_stats","description":"Counts: total / unread / high-urgency / actionable / starred, plus when the digest last generated. Use for quick \"how does my morning look?\" reads.","input_schema":{"type":"object","properties":{},"required":[]}},"code":"// Digest plugin — digest_stats. Ported from cmd''s tools/digest.js pool.\n\nimport { digestStats } from ''./digest.mjs'';\n\nexport const def = {\n  name: ''digest_stats'',\n  description: ''Counts: total / unread / high-urgency / actionable / starred, plus when the digest last generated. Use for quick \"how does my morning look?\" reads.'',\n  input_schema: { type: ''object'', properties: {}, required: [] },\n};\n\nexport async function run(api) {\n  return digestStats(api);\n}\n"},{"name":"execute_digest_action","def":{"name":"execute_digest_action","description":"Execute one action on a digest item. type=open_link logs the open and returns the url; type=mark_read sets read (pass read:false to un-read); type=star sets starred (pass starred:false to unstar; omitted toggles); type=save_draft stores draft text as the card''s note; type=snooze keeps the card''s key (its outlet for news, the event for calendar) out of the brief for snooze_days and archives its unread siblings.","input_schema":{"type":"object","properties":{"id":{"type":"string","description":"the digest item id"},"type":{"type":"string","enum":["open_link","mark_read","star","save_draft","snooze"]},"read":{"type":"boolean","description":"mark_read: default true"},"starred":{"type":"boolean","description":"star: default toggles"},"draft":{"type":"string","description":"save_draft: the note text (max 2000 chars kept)"}},"required":["id","type"]}},"code":"// Digest plugin: execute_digest_action. Runs one card verb. Snooze rides\n// the signal-priority lib (lib files may not import each other, so the tool\n// wires it in as deps).\n\nimport { executeDigestAction } from ''./digest.mjs'';\nimport { snoozeItem } from ''./signal-priority.mjs'';\n\nexport const def = {\n  name: ''execute_digest_action'',\n  description: ''Execute one action on a digest item. type=open_link logs the open and returns the url; type=mark_read sets read (pass read:false to un-read); type=star sets starred (pass starred:false to unstar; omitted toggles); type=save_draft stores draft text as the card\\''s note; type=snooze keeps the card\\''s key (its outlet for news, the event for calendar) out of the brief for snooze_days and archives its unread siblings.'',\n  input_schema: {\n    type: ''object'',\n    properties: {\n      id:      { type: ''string'', description: ''the digest item id'' },\n      type:    { type: ''string'', enum: [''open_link'', ''mark_read'', ''star'', ''save_draft'', ''snooze''] },\n      read:    { type: ''boolean'', description: ''mark_read: default true'' },\n      starred: { type: ''boolean'', description: ''star: default toggles'' },\n      draft:   { type: ''string'',  description: ''save_draft: the note text (max 2000 chars kept)'' },\n    },\n    required: [''id'', ''type''],\n  },\n};\n\nexport async function run(api, input) {\n  const { id, ...action } = input;\n  return executeDigestAction(api, id, action, { snoozeItem });\n}\n"},{"name":"generate_digest","def":{"name":"generate_digest","description":"Scan and materialize new digest items. Prunes what has gone stale, then pulls the two sources this install has (search headlines for the operator''s topics through any installed search provider, and the calendar look-ahead), deduping against existing items. Run when the operator says \"give me today''s brief\", \"what''s new?\", or first thing each morning.","input_schema":{"type":"object","properties":{"since_ms":{"type":"number","description":"lookback window in ms; default 86_400_000 (24h)"}},"required":[]}},"code":"// Digest plugin: generate_digest. The generate pass without the cron\n// wrapper: prune, then pull search + calendar.\n\nimport { generateDigest } from ''./digest.mjs'';\n\nexport const def = {\n  name: ''generate_digest'',\n  description: ''Scan and materialize new digest items. Prunes what has gone stale, then pulls the two sources this install has (search headlines for the operator\\''s topics through any installed search provider, and the calendar look-ahead), deduping against existing items. Run when the operator says \"give me today\\''s brief\", \"what\\''s new?\", or first thing each morning.'',\n  input_schema: {\n    type: ''object'',\n    properties: { since_ms: { type: ''number'', description: ''lookback window in ms; default 86_400_000 (24h)'' } },\n    required: [],\n  },\n};\n\nexport async function run(api, input) {\n  return generateDigest(api, { since_ms: input?.since_ms || 86_400_000 });\n}\n"},{"name":"learn_dismissals","def":{"name":"learn_dismissals","description":"Learn from what the operator dismissed in the digest and tune the interest filter: reads the recent dismissed-not-starred items, asks the model what to avoid, and appends the learned avoid-list to the plugin-digest-interests note. No-op unless enough new dismissals accumulated since the last pass — pass force:true to learn now regardless. Use when the operator says \"stop showing me this stuff\" or \"the digest is noisy\".","input_schema":{"type":"object","properties":{"force":{"type":"boolean","description":"learn even below the new-dismissals threshold"},"lookback_days":{"type":"number","description":"how far back to harvest dismissals (default 21)"}},"required":[]}},"code":"// Digest plugin — learn_dismissals. The cron entry tool: the host\n// scheduled handler''s hourly leg invokes this by name (cmd exposed the same\n// pass as digest_learn_interests — this pack keeps the cron-facing name).\n// A no-op unless enough new dismissals accumulated since the last pass.\n\nimport { learnFromDismissals } from ''./digest-relevance.mjs'';\n\nexport const def = {\n  name: ''learn_dismissals'',\n  description: ''Learn from what the operator dismissed in the digest and tune the interest filter: reads the recent dismissed-not-starred items, asks the model what to avoid, and appends the learned avoid-list to the plugin-digest-interests note. No-op unless enough new dismissals accumulated since the last pass — pass force:true to learn now regardless. Use when the operator says \"stop showing me this stuff\" or \"the digest is noisy\".'',\n  input_schema: {\n    type: ''object'',\n    properties: {\n      force: { type: ''boolean'', description: ''learn even below the new-dismissals threshold'' },\n      lookback_days: { type: ''number'', description: ''how far back to harvest dismissals (default 21)'' },\n    },\n    required: [],\n  },\n};\n\nexport async function run(api, input) {\n  return learnFromDismissals(api, {\n    force: !!input?.force,\n    ...(input?.lookback_days ? { lookbackDays: input.lookback_days } : {}),\n  });\n}\n"},{"name":"list_digest","def":{"name":"list_digest","description":"Read today''s digest items, the morning brief. Sources: search headlines for the operator''s topics and the calendar look-ahead. Default returns UNREAD items, urgency-sorted (high first). Set unread_only=false to see everything.","input_schema":{"type":"object","properties":{"unread_only":{"type":"boolean","description":"default true"},"starred_only":{"type":"boolean"},"limit":{"type":"number","description":"default 200"}},"required":[]}},"code":"// Digest plugin: list_digest. The brief, urgency-sorted.\n\nimport { listDigestItems } from ''./digest.mjs'';\n\nexport const def = {\n  name: ''list_digest'',\n  description: ''Read today\\''s digest items, the morning brief. Sources: search headlines for the operator\\''s topics and the calendar look-ahead. Default returns UNREAD items, urgency-sorted (high first). Set unread_only=false to see everything.'',\n  input_schema: {\n    type: ''object'',\n    properties: {\n      unread_only:  { type: ''boolean'', description: ''default true'' },\n      starred_only: { type: ''boolean'' },\n      limit:        { type: ''number'',  description: ''default 200'' },\n    },\n    required: [],\n  },\n};\n\nexport async function run(api, input) {\n  return {\n    items: await listDigestItems(api, {\n      unread_only:  input?.unread_only !== false,\n      starred_only: !!input?.starred_only,\n      limit:        input?.limit ?? 200,\n    }),\n  };\n}\n"},{"name":"mark_digest_read","def":{"name":"mark_digest_read","description":"Mark a digest item as read (dismisses it from the unread list). Use after Nyo has acted on or answered an item for the operator.","input_schema":{"type":"object","properties":{"id":{"type":"string"},"read":{"type":"boolean","description":"default true; pass false to mark unread again"}},"required":["id"]}},"code":"// Digest plugin — mark_digest_read. Ported from cmd''s tools/digest.js pool.\n\nimport { patchDigestItem } from ''./digest.mjs'';\n\nexport const def = {\n  name: ''mark_digest_read'',\n  description: ''Mark a digest item as read (dismisses it from the unread list). Use after Nyo has acted on or answered an item for the operator.'',\n  input_schema: {\n    type: ''object'',\n    properties: {\n      id:     { type: ''string'' },\n      read:   { type: ''boolean'', description: ''default true; pass false to mark unread again'' },\n    },\n    required: [''id''],\n  },\n};\n\nexport async function run(api, input) {\n  return { item: await patchDigestItem(api, input.id, { read: input.read !== false }) };\n}\n"},{"name":"prioritize_signals","def":{"name":"prioritize_signals","description":"Score every unread, unscored digest card of a scored kind (bounded batch) so the brief reads most-relevant first and background noise last. Safe to run repeatedly; scored items are skipped. Rubric, score_kinds and thresholds live in the plugin-digest-signal-priority knowledge doc.","input_schema":{"type":"object","properties":{"limit":{"type":"number","description":"max cards this run (default from the doc)"}}}},"code":"// Digest plugin: prioritize_signals. The sweep scores every unread,\n// unscored card of a scored kind (score_kinds in the priority doc).\n\nimport { sweepSignalPriorities } from ''./signal-priority.mjs'';\n\nexport const def = {\n  name: ''prioritize_signals'',\n  description: ''Score every unread, unscored digest card of a scored kind (bounded batch) so the brief reads most-relevant first and background noise last. Safe to run repeatedly; scored items are skipped. Rubric, score_kinds and thresholds live in the plugin-digest-signal-priority knowledge doc.'',\n  input_schema: { type: ''object'', properties: { limit: { type: ''number'', description: ''max cards this run (default from the doc)'' } } },\n};\n\nexport async function run(api, input) {\n  return sweepSignalPriorities(api, { limit: input?.limit });\n}\n"},{"name":"read_digest_topics","def":{"name":"read_digest_topics","description":"Read the watched topics the Digest currently searches for.","input_schema":{"type":"object","properties":{},"required":[]}},"code":"export const def = {\n  name: ''read_digest_topics'',\n  description: ''Read the watched topics the Digest currently searches for.'',\n  input_schema: { type: ''object'', properties: {}, required: [] },\n};\nexport async function run(api) {\n  let doc = null;\n  try { doc = await api.knowledge(''plugin-digest-search-topics''); } catch { doc = null; }\n  const topics = String(doc?.body || '''').split(''\\n'').map((l) => l.trim()).filter((l) => l && !l.startsWith(''#''));\n  return { ok: true, topics, configured: topics.length > 0 && !(topics.length === 1 && topics[0] === ''AI agents'') };\n}\n"},{"name":"read_website","def":{"name":"read_website","description":"Read a website and return its readable text (title, description, main content, capped). Use during digest setup to learn what the operator does from their own site instead of asking them.","input_schema":{"type":"object","properties":{"url":{"type":"string","description":"the site, with or without https://"}},"required":["url"]}},"code":"export const def = {\n  name: ''read_website'',\n  description: ''Read a website and return its readable text (title, description, main content, capped). Use during digest setup to learn what the operator does from their own site instead of asking them.'',\n  input_schema: {\n    type: ''object'',\n    properties: { url: { type: ''string'', description: ''the site, with or without https://'' } },\n    required: [''url''],\n  },\n};\nconst strip = (html) => String(html || '''')\n  .replace(/<script[\\s\\S]*?<\\/script>/gi, '' '').replace(/<style[\\s\\S]*?<\\/style>/gi, '' '')\n  .replace(/<[^>]+>/g, '' '').replace(/&nbsp;/g, '' '').replace(/&amp;/g, ''&'').replace(/&lt;/g, ''<'').replace(/&gt;/g, ''>'')\n  .replace(/\\s+/g, '' '').trim();\nexport async function run(api, input) {\n  let url = String(input?.url || '''').trim();\n  if (!url) return { ok: false, error: ''url required'' };\n  if (!/^https?:\\/\\//i.test(url)) url = ''https://'' + url;\n  let r;\n  try { r = await api.gateway(''web'', ''text'', { url }); }\n  catch (e) { return { ok: false, error: `could not fetch ${url}: ${String(e?.message || e).slice(0, 120)}` }; }\n  if (r?.ok === false || r?.error) return { ok: false, error: r?.error || `could not fetch ${url}` };\n  const raw = String(r?.text ?? r?.body ?? r ?? '''');\n  const looksHtml = /<html|<body|<div|<p[ >]/i.test(raw);\n  const title = (raw.match(/<title[^>]*>([^<]{1,200})<\\/title>/i) || [])[1]?.trim() || null;\n  const description = (raw.match(/<meta[^>]+name=[\"'']description[\"''][^>]+content=[\"'']([^\"'']{1,300})[\"'']/i) || [])[1]?.trim() || null;\n  const text = (looksHtml ? strip(raw) : raw.replace(/\\s+/g, '' '').trim()).slice(0, 8000);\n  if (!text) return { ok: false, error: `${url} returned no readable text` };\n  await api.log(''website_read'', { url, chars: text.length });\n  return { ok: true, url, title, description, text };\n}\n"},{"name":"run_digest","def":{"name":"run_digest","description":"Run the digest tick the cron runs at :30: prune what has gone stale, pull search headlines and the calendar look-ahead, dedupe against what is already there. Safe to run by hand to refresh the morning digest now.","input_schema":{"type":"object","properties":{"since_ms":{"type":"number","description":"lookback window in ms (default 24h)"}},"required":[]}},"code":"// Digest plugin: run_digest. The cron entry tool: the host scheduled\n// handler''s :30 leg invokes this by name. Same generate pass as\n// generate_digest, kept as its own verb so the cron binding stays stable.\n\nimport { generateDigest } from ''./digest.mjs'';\n\nexport const def = {\n  name: ''run_digest'',\n  description: ''Run the digest tick the cron runs at :30: prune what has gone stale, pull search headlines and the calendar look-ahead, dedupe against what is already there. Safe to run by hand to refresh the morning digest now.'',\n  input_schema: {\n    type: ''object'',\n    properties: {\n      since_ms: { type: ''number'', description: ''lookback window in ms (default 24h)'' },\n    },\n    required: [],\n  },\n};\n\nexport async function run(api, input) {\n  return generateDigest(api, input?.since_ms ? { since_ms: input.since_ms } : {});\n}\n"},{"name":"save_digest_draft","def":{"name":"save_digest_draft","description":"Save the operator''s draft note on a digest card (auto-save from the page). The note lives on the card and shows again whenever it is opened.","input_schema":{"type":"object","properties":{"id":{"type":"string"},"draft":{"type":"string","description":"the current note text (max 2000 chars kept)"}},"required":["id","draft"]}},"code":"// Digest plugin: save_digest_draft. The page''s note auto-save.\n\nimport { patchDigestItem } from ''./digest.mjs'';\n\nexport const def = {\n  name: ''save_digest_draft'',\n  description: ''Save the operator\\''s draft note on a digest card (auto-save from the page). The note lives on the card and shows again whenever it is opened.'',\n  input_schema: {\n    type: ''object'',\n    properties: {\n      id:    { type: ''string'' },\n      draft: { type: ''string'', description: ''the current note text (max 2000 chars kept)'' },\n    },\n    required: [''id'', ''draft''],\n  },\n};\n\nexport async function run(api, input) {\n  return { item: await patchDigestItem(api, input.id, { draft: String(input.draft ?? '''') }) };\n}\n"},{"name":"save_digest_topics","def":{"name":"save_digest_topics","description":"Save the watched topics the Digest searches for (max 5 short search queries). Replaces the list in the Digest search topics knowledge doc.","input_schema":{"type":"object","properties":{"topics":{"type":"array","items":{"type":"string"},"description":"up to 5 search queries"}},"required":["topics"]}},"code":"export const def = {\n  name: ''save_digest_topics'',\n  description: ''Save the watched topics the Digest searches for (max 5 short search queries). Replaces the list in the Digest search topics knowledge doc.'',\n  input_schema: {\n    type: ''object'',\n    properties: { topics: { type: ''array'', items: { type: ''string'' }, description: ''up to 5 search queries'' } },\n    required: [''topics''],\n  },\n};\nexport async function run(api, input) {\n  const topics = (Array.isArray(input?.topics) ? input.topics : [])\n    .map((t) => String(t || '''').trim().replace(/^#+\\s*/, ''''))\n    .filter(Boolean).slice(0, 5);\n  if (!topics.length) return { ok: false, error: ''no topics given'' };\n  const body = `# Digest search topics\n\nOne topic per line. The digest looks each of these up every run and files fresh headlines into the brief. Lines starting with # are ignored. Keep it to a handful.\n\n${topics.join(''\\n'')}\n`;\n  await api.saveKnowledge(''plugin-digest-search-topics'', { title: ''Digest search topics'', body });\n  await api.log(''topics_saved'', { count: topics.length });\n  return { ok: true, topics };\n}\n"},{"name":"score_signal","def":{"name":"score_signal","description":"Score ONE digest card for the attention it deserves (0-100 + a one-line reason) against the plugin-digest-signal-priority rubric, the operator''s interest profile and learned taste rules. The score remaps the card into the brief''s high/mid/low groups.","input_schema":{"type":"object","properties":{"digest_id":{"type":"string"}},"required":["digest_id"]}},"code":"// Digest plugin: score_signal. Score ONE card on demand.\n\nimport { scoreSignalItem } from ''./signal-priority.mjs'';\n\nexport const def = {\n  name: ''score_signal'',\n  description: ''Score ONE digest card for the attention it deserves (0-100 + a one-line reason) against the plugin-digest-signal-priority rubric, the operator\\''s interest profile and learned taste rules. The score remaps the card into the brief\\''s high/mid/low groups.'',\n  input_schema: { type: ''object'', properties: { digest_id: { type: ''string'' } }, required: [''digest_id''] },\n};\n\nexport async function run(api, input) {\n  return scoreSignalItem(api, input.digest_id);\n}\n"},{"name":"signal_feedback","def":{"name":"signal_feedback","description":"Teach the scorer the operator''s taste: pass their comment on a card''s priority verdict. The comment distills into durable taste rules in the plugin-digest-signal-priority knowledge doc (bounded) and the card is immediately rescored under the updated rubric.","input_schema":{"type":"object","properties":{"digest_id":{"type":"string"},"comment":{"type":"string"}},"required":["digest_id","comment"]}},"code":"// Digest plugin: signal_feedback. The operator''s comment on a score becomes\n// durable taste rules, then the card is rescored.\n\nimport { distillPriorityFeedback } from ''./signal-priority.mjs'';\n\nexport const def = {\n  name: ''signal_feedback'',\n  description: ''Teach the scorer the operator\\''s taste: pass their comment on a card\\''s priority verdict. The comment distills into durable taste rules in the plugin-digest-signal-priority knowledge doc (bounded) and the card is immediately rescored under the updated rubric.'',\n  input_schema: {\n    type: ''object'',\n    properties: { digest_id: { type: ''string'' }, comment: { type: ''string'' } },\n    required: [''digest_id'', ''comment''],\n  },\n};\n\nexport async function run(api, input) {\n  return distillPriorityFeedback(api, input.digest_id, input.comment);\n}\n"},{"name":"signal_snooze","def":{"name":"signal_snooze","description":"Snooze a digest card for a while (snooze_days in the plugin-digest-signal-priority doc, default 7): a news card mutes its outlet, a calendar card mutes that event. Archives the card and its unread siblings on the same key and keeps new arrivals on that key out of the brief until the snooze expires.","input_schema":{"type":"object","properties":{"digest_id":{"type":"string"}},"required":["digest_id"]}},"code":"// Digest plugin: signal_snooze. Keep a card''s key out of the brief for a\n// while. The sibling-archive comes from digest.mjs (lib files may not import\n// each other; the tool wires it).\n\nimport { snoozeItem } from ''./signal-priority.mjs'';\nimport { archiveItemsByKey } from ''./digest.mjs'';\n\nexport const def = {\n  name: ''signal_snooze'',\n  description: ''Snooze a digest card for a while (snooze_days in the plugin-digest-signal-priority doc, default 7): a news card mutes its outlet, a calendar card mutes that event. Archives the card and its unread siblings on the same key and keeps new arrivals on that key out of the brief until the snooze expires.'',\n  input_schema: { type: ''object'', properties: { digest_id: { type: ''string'' } }, required: [''digest_id''] },\n};\n\nexport async function run(api, input) {\n  return snoozeItem(api, input.digest_id, { archiveItemsByKey });\n}\n"},{"name":"signal_unsnooze","def":{"name":"signal_unsnooze","description":"Wake a snoozed key again (undo a snooze). Identify it by the digest card that was snoozed, or by the key itself (e.g. \"source:techcrunch\" or \"ref:calendar_events:<id>\").","input_schema":{"type":"object","properties":{"digest_id":{"type":"string"},"key":{"type":"string"}}}},"code":"// Digest plugin: signal_unsnooze. Undo a snooze.\n\nimport { unsnoozeItem } from ''./signal-priority.mjs'';\n\nexport const def = {\n  name: ''signal_unsnooze'',\n  description: ''Wake a snoozed key again (undo a snooze). Identify it by the digest card that was snoozed, or by the key itself (e.g. \"source:techcrunch\" or \"ref:calendar_events:<id>\").'',\n  input_schema: {\n    type: ''object'',\n    properties: { digest_id: { type: ''string'' }, key: { type: ''string'' } },\n  },\n};\n\nexport async function run(api, input) {\n  return unsnoozeItem(api, input || {});\n}\n"},{"name":"star_digest_item","def":{"name":"star_digest_item","description":"Pin a digest item by starring it. Stays visible across day rolls. Use when the operator wants to come back to something.","input_schema":{"type":"object","properties":{"id":{"type":"string"},"starred":{"type":"boolean"}},"required":["id"]}},"code":"// Digest plugin — star_digest_item. Ported from cmd''s tools/digest.js pool.\n\nimport { patchDigestItem } from ''./digest.mjs'';\n\nexport const def = {\n  name: ''star_digest_item'',\n  description: ''Pin a digest item by starring it. Stays visible across day rolls. Use when the operator wants to come back to something.'',\n  input_schema: {\n    type: ''object'',\n    properties: { id: { type: ''string'' }, starred: { type: ''boolean'' } },\n    required: [''id''],\n  },\n};\n\nexport async function run(api, input) {\n  return { item: await patchDigestItem(api, input.id, { starred: input.starred !== false }) };\n}\n"}],"workflows":[{"slug":"digest-generate","name":"Digest · generate + prioritize","goal":"The digest tick as one named chain: prune stale items, pull the two sources this install has (search headlines for the operator''s topics, the calendar look-ahead), then score the fresh cards so the brief reads most-relevant first. Same pass the :30 cron runs; also runnable manually or by Nyo via run_workflow.","steps":[{"tool":"run_digest"},{"tool":"prioritize_signals","optional":true}]},{"slug":"prioritize-signals","name":"Digest · prioritize signals","goal":"Score every unread, unscored digest card of a scored kind (0-100 + reason, plugin-digest-signal-priority rubric): cards worth acting on rise to high urgency, background noise sinks. Fires after digest generation; also runnable manually or by Nyo via run_workflow.","steps":[{"tool":"prioritize_signals"}]},{"slug":"digest-learn","name":"Digest · learn from dismissals","goal":"The consideration layer''s learn pass: harvest recently dismissed-not-starred items, distill avoid-patterns through the llm gateway, and append them to the plugin-digest-interests note the scorer reads. No-op below the new-dismissals threshold, so it is safe on every cron tick.","steps":[{"tool":"learn_dismissals"}]}],"knowledge":[{"slug":"plugin-digest-interests","title":"What counts as ''of interest'' for the digest","body":"# What we care about\n\nThe relevance filter for incoming signals. Replace with your own subject matter.\n\n## Always relevant\n- Topics, markets, technologies and competitors we track by name.\n\n## Sometimes relevant\n- Adjacent areas, and the condition that makes them matter to us.\n\n## Never relevant\n- The recurring noise you never want to see again: funding-round roundups,\n  listicles, vendor press releases, whatever else wastes your morning.\n\nBe concrete. A named company or product filters far better than a category.\n"},{"slug":"plugin-digest-policy","title":"Digest policy: scan windows + caps","body":"{\n  \"sources_off\": [],\n  \"search_topics_cap\": 5,\n  \"search_per_topic_limit\": 5,\n  \"search_urgency\": 2,\n  \"calendar_lookahead_days\": 7,\n  \"stale_after_days\": 7,\n  \"delete_after_days\": 14\n}\n"},{"slug":"plugin-digest-signal-priority","title":"Signal priority","body":"# Signal priority\n\nThe reasoning rubric behind digest ordering: every card of a scored kind is\nscored 0-100 for the attention it deserves, with a one-line reason, and the\nscore maps to the brief''s urgency groups. score_kinds picks which kinds get\nscored (calendar cards keep their clock-based urgency). taste_rules grow\nfrom the operator''s comments on scores (the chip''s comment box) and bind\nevery future score. snooze_days is how long a snoozed card''s key stays\nmuted. Edit anything here; no deploy needed.\n\n```json\n{\n  \"prompt\": \"You score ONE card from an operator''s morning digest for how much of their attention it deserves today, 0-100.\\n\\nScore bands:\\n- 70-100 act on it: a concrete, timely development the operator should react to or that directly touches what they track (their named topics, markets, products, competitors).\\n- 40-69 worth knowing: relevant background, a real development in an adjacent area, something to skim.\\n- 0-39 can wait: evergreen filler, listicles, reviews, vendor press releases, coincidental keyword matches, anything that gives no reason to act.\\n\\nJudge what the card gives the operator to DO or LEARN, not how loud the headline is. Return STRICT JSON: {\\\"score\\\": <0-100>, \\\"reason\\\": \\\"<one short sentence naming why it matters or why it does not>\\\"}\",\n  \"urgency_thresholds\": {\n    \"high\": 70,\n    \"mid\": 40\n  },\n  \"score_kinds\": [\"news\"],\n  \"batch_limit\": 10,\n  \"taste_rules\": [],\n  \"max_taste_rules\": 20,\n  \"feedback_prompt\": \"You maintain a short list of durable TASTE rules describing how an operator wants their digest cards prioritized. Given a card, the scorer''s verdict, and the operator''s comment on that verdict, extract at most 2 NEW durable rules (what they value, what bores them, how to weigh kinds of news), merge with the existing rules, drop duplicates and one-off gripes, keep under {max} rules, each short and imperative. Return STRICT JSON: {\\\"rules\\\":[\\\"...\\\"]}\",\n  \"snooze_days\": 7\n}\n```\n"},{"slug":"plugin-digest-search-topics","title":"Digest search topics","body":"# Digest search topics\n\nOne topic per line. The digest''s search source looks each of these up every\nrun and files fresh headlines into the brief. Lines starting with # are\nignored. Keep it to a handful: the brief should stay a brief.\n\nAI agents\n"},{"slug":"plugin-digest-onboarding-persona","title":"Digest onboarding (system prompt)","body":"# Digest onboarding (system prompt)\n\nYou are Nyo, setting up someone''s Digest: a short daily brief built from news search on a handful of watched topics. Your job in this conversation: get a source ready and figure out the topics yourself. Keep every message under 50 words. No lists of questions. No em dashes.\n\nStep 1, before your first message: call digest_sources.\n- If no search provider is installed: say \"No source yet. In the panel beside this chat, click add next to News Search (free, no key).\" Mention Brave Search only as the one that needs a key. Wait until digest_sources shows a provider.\n- If a provider is installed but not connected (Brave without a key): say \"Brave needs a key. Create a free one at https://api-dashboard.search.brave.com/app/keys and paste it here.\" When they paste it, call that provider''s connect tool (connect_brave_search) with the key; on success say it is connected, on failure quote the error and ask again. Never store or repeat the key in your own words.\n\nStep 2, one question only: \"What is your website?\" (If they have none, ask for the company or their role in one line instead.)\n\nStep 3: call read_website on the answer. From the site, work out on your own: what they do, what they sell, who they serve, named competitors or partners, the industry, the places they operate. Do not ask them to explain the business; you have the site. Ask at most one follow-up, and only if the site is thin or ambiguous.\n\nStep 4: derive at most 5 watched topics, each a search query a news engine understands: the company name, the product category, a named competitor, the core technology, a regulation or market they depend on. Specific beats general. Show the five in one short message and ask for a yes or an edit.\n\nStep 5, on yes: call save_digest_topics with the final list, then call digest_sources again. If a provider is ready, say the brief fills on the next Generate and that the list lives in the Knowledge doc \"Digest search topics\". If none is ready, say exactly which add button to click, by name.\n\nNever invent facts about the person or the company; everything you say about them comes from the site or from them.\n"},{"slug":"plugin-digest-build-a-source","title":"Build a new Digest source (prompt for an LLM)","body":"# Build a new Digest source (prompt for an LLM)\n\nCopy everything below the line into Claude Code, Expand build, or any capable assistant.\n\n---\n\nYou are helping someone who is not a programmer add a new SOURCE to their nyyon Digest. The Digest is a daily brief; a source is a small plugin that can search or fetch a service and hand back items. You will first find out what they want, then build it, then tell them how to install it. Talk in plain words. One question at a time. Never ask them to read code.\n\n## Part 1: find out what to build (ask, do not assume)\n\nAsk these, in order, one per message, and stop early when you have enough:\n\n1. \"What do you want the digest to watch?\" Get a plain description: a news site, a blog, a forum, a product''s changelog, a government or regulator page, a job board, a search engine, a podcast feed, a specific company''s press page, a competitor''s site. Ask for the exact web address if there is one.\n2. \"Is it public, or do you need to log in or hold a key to see it?\" If a key or account is needed, ask where the key comes from (the address of the page where they get it) and whether it is free. If it needs a login with a password and has no API, say honestly that it cannot be a source yet and stop.\n3. \"When you imagine one item from this source landing in your brief, what does it look like?\" Get the shape: a headline with a link, a post with a date, a listing with a price, a page section that changed. Ask what makes an item worth including and what should be ignored.\n4. \"How fresh does it need to be, and in what language or country?\" Daily is the default. Note language and country if they matter for the service.\n5. Repeat back in three sentences what you will build: the service, how you will read it (feed, page, or API with a key), and what one item will contain. Get a yes before writing anything.\n\nDecide the pattern from the answers:\n- RSS or Atom feed exists: read the feed. Keyless. Best case.\n- Public JSON API without a key: call it. Keyless.\n- Public page, no feed, no API: fetch the page and extract items from its HTML. Keyless but fragile; say so.\n- API that needs a key: call it with the key stored in the plugin''s own table. The person pastes the key to Nyo; your connect tool stores it after one real test request.\n- Needs a browser login and has no API: not possible as a source. Say so and stop.\n\n## Part 2: what you build, and the rules that keep the install safe\n\nA nyyon plugin is a folder. Its gateway advertises the capability `search`; the Digest discovers it by that capability, never by name, and calls it with each watched topic (or, for a fixed source, ignores the topic and returns what is new).\n\nFiles:\n\n1. `manifest.json`\n   {\n     \"nyyon_plugin\": 2, \"name\": \"<kebab-case>\", \"title\": \"<Name>\", \"version\": \"1.0.0\",\n     \"description\": \"<one sentence>\", \"icon\": \"MagnifyingGlass\", \"origin\": { \"system\": \"user\" },\n     \"requires\": {\n       \"gateways\": [{ \"slug\": \"<slug>\", \"modes\": [\"search\", \"status\"], \"purpose\": \"<service>\" }],\n       \"tables\": []   // only if a key is needed: [{ \"name\": \"plugin_<name>_config\", \"ddl\": \"CREATE TABLE IF NOT EXISTS plugin_<name>_config (id INTEGER PRIMARY KEY, api_key TEXT NOT NULL, updated_at INTEGER NOT NULL)\" }]\n     },\n     \"provides\": {\n       \"gateways\": [{ \"slug\": \"<slug>\", \"modes\": [\"search\", \"status\"], \"capability\": \"search\", \"code_file\": \"gateway-<slug>.mjs\" }],\n       \"tools\": [ ...one entry per tool file: { \"name\", \"code_file\": \"tools/<name>.mjs\", \"def\": <the tool''s def> } ],\n       \"workflows\": [], \"knowledge\": [{ \"slug\": \"plugin-<name>-usage\", \"title\": \"<when to use it>\", \"body_file\": \"knowledge/plugin-<name>-usage.md\" }], \"surfaces\": []\n     }\n   }\n2. `gateway-<slug>.mjs`\n   export const gateway = {\n     slug: ''<slug>'', service: ''<what it talks to>'', description: ''<one line>'', capability: ''search'',\n     modes: {\n       status: async (api) => ({ connected: true, label: ''<Name>'' }),   // with a key: connected = a key row exists\n       search: async (api, input) => { /* fetch, then return */ return { ok: true, query: input.query, results: [{ title, url, source, published_at, summary }] }; },\n     },\n   };\n   Rules: the gateway only fetches and translates. It never decides what is important, never reads knowledge, never writes anything. Use `fetch` with `AbortSignal.timeout(20000)`. On any failure return `{ ok: false, error: ''<the provider''s real message>'' }`, never throw. Each result needs `title` and `url`; the other fields may be null. Cap results at `input.limit` (default 5, max 20). Read a key only with `api.DB.prepare(\"SELECT api_key FROM plugin_<name>_config WHERE id = 1\").first()`.\n3. `tools/*.mjs`, each: `export const def = { name, description, input_schema }` and `export async function run(api, input)`. Ship at least one search tool for Nyo (for example `search_<name>(query, limit?)`) that calls `api.gateway(''<slug>'', ''search'', input)`. If a key is needed also ship `connect_<name>(api_key)` that verifies with one real request, then `INSERT ... ON CONFLICT(id) DO UPDATE` into the plugin''s own table, and `disconnect_<name>()`. Tools reach the outside world only through the gateway.\n4. `knowledge/plugin-<name>-usage.md`: two short paragraphs, when Nyo should use the tool and how the key is connected (paste it to Nyo).\n\nHard limits (breaking any of these makes the install refuse the plugin):\n- Only touch tables named `plugin_<name>_*`. No other table, no DDL beyond the manifest.\n- No imports from outside the plugin folder. No environment variables. No secrets in code.\n- The plugin name is kebab-case, 2 to 40 characters, and every gateway or tool name is unique.\n- No em dashes in any text. Plain sentences.\n- Never fake data. If the service answers nothing, return an empty results list with ok true.\n\n## Part 3: hand it over\n\nZip the folder (manifest.json at the top level of the folder). Tell them: open the Plugins page, upload the zip, wait about a minute, then open the Digest. If a key is needed, tell them Nyo will ask for it in the digest setup. Their watched topics live in the Knowledge doc \"Digest search topics\".\n"}],"surfaces":[{"slug":"digest","title":"Digest","icon":"Activity","files":[{"path":"DigestItemDrawer.tsx","code":"// Right-side drawer that opens when a digest item is clicked. Surfaces:\n//   - the item''s title / summary / suggested action / link\n//   - for calendar cards, the underlying event (when, where, link)\n//   - a draft note that auto-saves on the card\n//   - snooze, star, and mark read\n// Closing without acting leaves the item in the brief.\n\nimport { useEffect, useState } from ''react'';\nimport {\n  api,\n  parseMeta,\n  type DigestItem,\n  type DigestAction,\n  type DigestContext,\n} from ''./digest-data'';\nimport { X, Star, Trash } from ''../../components/Icons'';\n\ntype Props = {\n  item: DigestItem;\n  onClose: () => void;\n  onChange: () => void;\n};\n\nfunction fmtWhen(ms: number): string {\n  return new Date(ms).toLocaleString(undefined, { weekday: ''short'', month: ''short'', day: ''numeric'', hour: ''numeric'', minute: ''2-digit'' });\n}\n\nexport function DigestItemDrawer({ item, onClose, onChange }: Props) {\n  const [context, setContext] = useState<DigestContext | null>(null);\n  const [actions, setActions] = useState<DigestAction[] | null>(null);\n  const [busy, setBusy]       = useState<string | null>(null);\n  const [error, setError]     = useState<string | null>(null);\n  const [doneMsg, setDoneMsg] = useState<string | null>(null);\n  const [starred, setStarred] = useState(item.starred === 1);\n  const [isRead, setIsRead]   = useState(item.read_at !== null);\n  const [snoozed, setSnoozed] = useState(false);\n\n  // Draft note: persists server-side (meta_json.draft), auto-saves 800ms\n  // after the operator stops typing.\n  const [draft, setDraft] = useState<string | null>(null);\n  const savedDraft = parseMeta(item).draft ?? '''';\n  const draftText = draft ?? savedDraft;\n  const [draftNote, setDraftNote] = useState<string | null>(null);\n  useEffect(() => {\n    if (draft === null) return;\n    const t = window.setTimeout(() => {\n      api.patchDigestItem(item.id, { draft })\n        .then(() => setDraftNote(''saved''))\n        .catch((e) => setDraftNote(e instanceof Error ? e.message : String(e)));\n    }, 800);\n    return () => window.clearTimeout(t);\n  }, [draft, item.id]);\n\n  useEffect(() => {\n    let alive = true;\n    setContext(null); setActions(null);\n    setError(null); setDoneMsg(null); setSnoozed(false);\n    setDraft(null); setDraftNote(null);\n    setStarred(item.starred === 1); setIsRead(item.read_at !== null);\n    api.digestActions(item.id)\n      .then((r) => {\n        if (!alive) return;\n        setActions(r.actions);\n        if (r.context) setContext(r.context);\n      })\n      .catch((e) => { if (alive) setError(String(e?.message || e)); });\n    return () => { alive = false; };\n  }, [item.id, item.starred, item.read_at]);\n\n  // ESC closes\n  useEffect(() => {\n    const h = (e: KeyboardEvent) => { if (e.key === ''Escape'') onClose(); };\n    window.addEventListener(''keydown'', h);\n    return () => window.removeEventListener(''keydown'', h);\n  }, [onClose]);\n\n  async function toggleStar() {\n    setBusy(''star''); setError(null);\n    try {\n      const r = await api.executeDigestAction(item.id, { type: ''star'', starred: !starred });\n      if (r.error) throw new Error(r.error);\n      setStarred(!starred);\n      onChange();\n    } catch (e) { setError(e instanceof Error ? e.message : String(e)); }\n    finally { setBusy(null); }\n  }\n\n  async function markRead(read: boolean) {\n    setBusy(''mark_read''); setError(null);\n    try {\n      const r = await api.executeDigestAction(item.id, { type: ''mark_read'', read });\n      if (r.error) throw new Error(r.error);\n      setIsRead(read);\n      onChange();\n      if (read) onClose();\n    } catch (e) { setError(e instanceof Error ? e.message : String(e)); }\n    finally { setBusy(null); }\n  }\n\n  async function snooze() {\n    setBusy(''snooze''); setError(null);\n    try {\n      const r = await api.digestSnooze(item.id);\n      if (r.error) throw new Error(r.error);\n      setSnoozed(true);\n      setDoneMsg(`Snoozed${r.until ? ` until ${fmtWhen(r.until)}` : ''''}${r.archived && r.archived > 1 ? `, ${r.archived} cards archived` : ''''}.`);\n      onChange();\n    } catch (e) { setError(e instanceof Error ? e.message : String(e)); }\n    finally { setBusy(null); }\n  }\n\n  const openLink  = actions?.find((a) => a.type === ''open_link'') || null;\n  const snoozeAct = actions?.find((a) => a.type === ''snooze'') || null;\n  const event     = context?.event || null;\n  const isCal     = item.ref_kind === ''calendar_events'';\n\n  return (\n    <>\n      {/* backdrop */}\n      <div\n        onClick={onClose}\n        className=\"fixed inset-0 bg-black/25 backdrop-blur-[1px] z-40\"\n      />\n      <aside\n        className=\"fixed top-0 right-0 h-full w-full sm:w-[520px] bg-paper border-l border-line z-50 shadow-[-16px_0_40px_-20px_rgba(10,10,10,0.18)] flex flex-col\"\n        role=\"dialog\"\n        aria-label=\"Digest item\"\n      >\n        {/* Header */}\n        <header className=\"px-5 h-12 border-b border-line flex items-center justify-between shrink-0\">\n          <div className=\"flex items-center gap-2 min-w-0\">\n            <span className={\n              ''h-1.5 w-1.5 rounded-full shrink-0 '' +\n              (item.urgency === 1 ? ''bg-rose-500'' : item.urgency === 2 ? ''bg-amber-500'' : ''bg-stone-400'')\n            } />\n            <span className=\"mono text-[10px] uppercase tracking-[0.18em] text-mute truncate\">{item.source_label || ''digest item''}</span>\n          </div>\n          <div className=\"flex items-center gap-1\">\n            <button\n              onClick={toggleStar}\n              disabled={busy === ''star''}\n              aria-label={starred ? ''Unstar'' : ''Star''}\n              title={starred ? ''Unstar'' : ''Star: pinned cards stay visible across day rolls''}\n              className={\n                ''h-8 w-8 grid place-items-center rounded-sm transition '' +\n                (starred ? ''text-amber-500'' : ''text-mute hover:text-amber-500 hover:bg-card/70'')\n              }\n            >\n              <Star size={16} className={starred ? ''fill-current'' : ''''} />\n            </button>\n            <button\n              onClick={onClose}\n              title=\"Close\"\n              className=\"h-8 w-8 grid place-items-center text-mute hover:text-ink rounded-sm hover:bg-card/70 transition\"\n            >\n              <X size={16} />\n            </button>\n          </div>\n        </header>\n\n        <div className=\"flex-1 overflow-y-auto px-5 py-5 space-y-5\">\n          {/* Item summary */}\n          <section>\n            <h2 dir=\"auto\" className=\"text-[15px] font-semibold leading-snug text-ink\">{item.title}</h2>\n            {item.summary && (\n              <p dir=\"auto\" className=\"text-[13px] text-mute mt-2 leading-relaxed whitespace-pre-wrap\">{item.summary}</p>\n            )}\n            {item.suggested_action && (\n              <div dir=\"auto\" className=\"mt-3 inline-flex items-center mono text-[10px] uppercase tracking-[0.18em] text-ink bg-paper hairline rounded-sm px-2 py-1\">\n                {item.suggested_action}\n              </div>\n            )}\n            {(openLink?.url || item.source_url) && (\n              <div className=\"mt-3\">\n                <a\n                  href={openLink?.url || item.source_url || ''#''}\n                  target=\"_blank\"\n                  rel=\"noreferrer\"\n                  onClick={() => { api.executeDigestAction(item.id, { type: ''open_link'' }).catch(() => {}); }}\n                  className=\"inline-flex items-center gap-1.5 mono text-[10px] uppercase tracking-[0.18em] bg-ink text-paper rounded-sm px-2.5 py-1 hover:opacity-90 transition\"\n                  title=\"Open the link\"\n                >\n                  {isCal ? ''Open invite ↗'' : ''Open link ↗''}\n                </a>\n              </div>\n            )}\n          </section>\n\n          {/* Calendar event context */}\n          {event && (\n            <section className=\"hairline rounded-sm bg-card/60 p-4 space-y-1.5\">\n              <div className=\"mono text-[10px] uppercase tracking-[0.2em] text-mute mb-1\">Event</div>\n              <div className=\"text-[13px] text-ink font-medium\" dir=\"auto\">{event.title}</div>\n              <div className=\"text-[12px] text-mute\">\n                {event.all_day ? ''All day · '' : ''''}{fmtWhen(event.starts_at)}{event.ends_at ? ` to ${new Date(event.ends_at).toLocaleTimeString(undefined, { hour: ''numeric'', minute: ''2-digit'' })}` : ''''}\n              </div>\n              {event.location && <div className=\"text-[12px] text-mute\" dir=\"auto\">Where: {event.location}</div>}\n              {event.platform && <div className=\"text-[12px] text-mute\">Via: {event.platform}</div>}\n              {event.status && <div className=\"mono text-[10px] uppercase tracking-[0.16em] text-mute\">{event.status}</div>}\n              {event.description && (\n                <p dir=\"auto\" className=\"text-[12px] text-mute leading-relaxed whitespace-pre-wrap pt-1\">{event.description}</p>\n              )}\n            </section>\n          )}\n\n          {/* Draft note */}\n          <section className=\"hairline rounded-sm bg-card/60 p-4 space-y-2\">\n            <div className=\"flex items-center justify-between\">\n              <div className=\"text-[13px] font-medium text-ink\">Draft note</div>\n              <span className=\"mono text-[9px] uppercase tracking-[0.16em] text-mute\">{draftNote || ''auto-saves''}</span>\n            </div>\n            <textarea\n              dir=\"auto\"\n              value={draftText}\n              onChange={(e) => { setDraft(e.target.value); setDraftNote(null); }}\n              rows={5}\n              placeholder=\"Jot what you want to do with this...\"\n              className=\"w-full resize-y rounded-sm hairline bg-paper px-3 py-2 text-[13px] leading-relaxed focus:border-ink focus:outline-none transition\"\n            />\n          </section>\n\n          {/* Snooze */}\n          <section className=\"hairline rounded-sm bg-card/60 p-4 space-y-2\">\n            <div className=\"text-[13px] font-medium text-ink\">Snooze</div>\n            <p className=\"text-[11px] text-mute\">\n              {snoozeAct?.description || ''Keep this out of the brief for a while.''}\n            </p>\n            <button\n              onClick={snooze}\n              disabled={busy === ''snooze'' || snoozed}\n              className=\"mono inline-flex items-center gap-1.5 h-8 px-3 rounded-sm hairline text-ink hover:bg-card transition text-[10px] uppercase tracking-[0.18em] disabled:opacity-40\"\n            >\n              {snoozed ? ''snoozed'' : busy === ''snooze'' ? ''snoozing...'' : ''snooze''}\n            </button>\n          </section>\n\n          {/* Mark read / unread */}\n          <section className=\"flex items-center justify-end gap-2 pt-1\">\n            {isRead ? (\n              <button\n                onClick={() => markRead(false)}\n                disabled={busy === ''mark_read''}\n                className=\"mono inline-flex items-center gap-1.5 h-8 px-3 rounded-sm text-mute hover:text-ink hover:bg-card transition text-[10px] uppercase tracking-[0.18em] disabled:opacity-40\"\n              >\n                {busy === ''mark_read'' ? ''working...'' : ''mark unread''}\n              </button>\n            ) : (\n              <button\n                onClick={() => markRead(true)}\n                disabled={busy === ''mark_read''}\n                className=\"mono inline-flex items-center gap-1.5 h-8 px-3 rounded-sm text-mute hover:text-rose-700 hover:bg-rose-50 transition text-[10px] uppercase tracking-[0.18em] disabled:opacity-40\"\n              >\n                <Trash size={12} />\n                {busy === ''mark_read'' ? ''dismissing...'' : ''mark read''}\n              </button>\n            )}\n          </section>\n\n          {error && (\n            <div className=\"hairline rounded-sm bg-rose-50 text-rose-800 text-[12px] px-3 py-2\">{error}</div>\n          )}\n          {doneMsg && (\n            <div className=\"hairline rounded-sm bg-emerald-50 text-emerald-800 text-[12px] px-3 py-2\">{doneMsg}</div>\n          )}\n        </div>\n      </aside>\n    </>\n  );\n}\n"},{"path":"digest-data.ts","code":"// Digest plugin: the Digest surface''s data layer.\n//\n// A plugin surface drives its OWN plugin''s tools through the scoped invoke\n// route, so the page, the cron and Nyo all go through the exact same verbs\n// and can never diverge. The types travel with the module.\n\nexport type DigestKind = ''news'' | ''opportunity'' | ''note'';\n\nexport type DigestItem = {\n  id: string;\n  kind: DigestKind;\n  meta_json?: string | null;\n  ref_kind: string | null;\n  ref_id: string | null;\n  title: string;\n  summary: string | null;\n  source_label: string | null;\n  source_url: string | null;\n  urgency: 1 | 2 | 3;           // 1 = high, 3 = low\n  actionable: number;           // 0 | 1\n  suggested_action: string | null;\n  starred: number;              // 0 | 1\n  read_at: number | null;\n  created_at: number;\n  meta: unknown;\n};\n\n// What a card carries in meta_json (parsed defensively on the client).\nexport type DigestMeta = {\n  draft?: string | null;\n  draft_edited_at?: number;\n  priority?: number;\n  priority_reason?: string;\n  priority_at?: number;\n};\n\nexport type DigestStats = {\n  total: number;\n  unread: number;\n  high: number;\n  action_count: number;\n  starred: number;\n  last_generated_at: number | null;\n};\n\nexport type CalendarEventRow = {\n  id: string;\n  kind: string | null;\n  title: string;\n  description: string | null;\n  starts_at: number;\n  ends_at: number | null;\n  all_day: number | null;\n  status: string | null;\n  location: string | null;\n  link_url: string | null;\n  platform: string | null;\n};\n\nexport type DigestContext = {\n  item: DigestItem;\n  event: CalendarEventRow | null;\n};\n\nexport type DigestActionType = ''open_link'' | ''mark_read'' | ''star'' | ''save_draft'' | ''snooze'';\nexport type DigestAction = {\n  type: DigestActionType;\n  label: string;\n  description: string;\n  url?: string;\n};\nexport type DigestActionsResponse = {\n  item: DigestItem | null;\n  context?: DigestContext;\n  actions: DigestAction[];\n};\n\nexport type GenerateResult = {\n  generated: number;\n  onboarding_needed?: boolean;\n  note?: string;\n  pruned?: number;\n  since_ms?: number;\n  per_source?: Record<string, { count: number; error: string | null; skipped?: string }>;\n};\n\nexport function parseMeta(item: Pick<DigestItem, ''meta_json''>): DigestMeta {\n  try { return (JSON.parse(item.meta_json || ''{}'') || {}) as DigestMeta; } catch { return {}; }\n}\n\n// The invoke pipe.\nasync function invoke<T>(tool: string, input: unknown): Promise<T> {\n  const r = await fetch(`/api/plugins/digest/invoke/${tool}`, {\n    method: ''POST'',\n    headers: { ''content-type'': ''application/json'' },\n    body: JSON.stringify(input ?? {}),\n  });\n  const d = await r.json();\n  if (!d.ok) throw new Error(d.error || `HTTP ${r.status}`);\n  return d.result as T;\n}\n\n// Tool results that carry a soft {error} pass through for the UI to render\n// inline.\nexport const api = {\n  listDigest: (opts: { unread?: boolean; starred?: boolean; limit?: number } = {}) =>\n    invoke<{ items: DigestItem[] }>(''list_digest'', {\n      unread_only: !!opts.unread, starred_only: !!opts.starred, limit: opts.limit ?? 200,\n    }).then((r) => r.items),\n  digestStats: () => invoke<DigestStats>(''digest_stats'', {}),\n  generateDigest: (since_ms?: number) =>\n    invoke<GenerateResult>(''generate_digest'', since_ms ? { since_ms } : {}),\n  patchDigestItem: (id: string, patch: { read?: boolean; starred?: boolean; draft?: string }) => {\n    if (typeof patch.draft === ''string'') return invoke<{ item: DigestItem }>(''save_digest_draft'', { id, draft: patch.draft }).then((r) => r.item);\n    if (patch.read !== undefined) return invoke<{ item: DigestItem }>(''mark_digest_read'', { id, read: patch.read }).then((r) => r.item);\n    return invoke<{ item: DigestItem }>(''star_digest_item'', { id, starred: !!patch.starred }).then((r) => r.item);\n  },\n  digestContext: (id: string) => invoke<DigestContext>(''digest_context'', { id }),\n  digestActions: (id: string) => invoke<DigestActionsResponse>(''digest_actions'', { id }),\n  executeDigestAction: (id: string, action: { type: DigestActionType; read?: boolean; starred?: boolean; draft?: string }) =>\n    invoke<{ ok?: boolean; error?: string; url?: string; item?: DigestItem; until?: number; days?: number; archived?: number }>(\n      ''execute_digest_action'', { id, ...action }),\n  digestSnooze: (id: string) =>\n    invoke<{ ok?: boolean; error?: string; until?: number; days?: number; archived?: number }>(''signal_snooze'', { digest_id: id }),\n  digestPriorityFeedback: (id: string, comment: string) =>\n    invoke<{ ok?: boolean; error?: string; rules?: number; rescored?: { ok?: boolean; score?: number; reason?: string } }>(\n      ''signal_feedback'', { digest_id: id, comment }),\n};\n\n// ── sources + onboarding ─────────────────────────────────────\n// Every data fetch must answer JSON. An HTML answer (the SPA fallback, a\n// login page) is reported as what it is instead of a parse error.\nasync function jsonOrThrow(r: Response, what: string) {\n  const text = await r.text();\n  try { return JSON.parse(text); }\n  catch { throw new Error(`${what}: server answered ${r.status} with ${text.trim().startsWith(''<'') ? ''HTML, not JSON (are you signed in? is the route deployed?)'' : ''something that is not JSON''}`); }\n}\nexport type DigestSources = {\n  providers: { slug: string; label: string; connected: boolean; note: string | null }[];\n  calendar: boolean; topics: string[]; configured: boolean; ready: boolean;\n};\nexport type CatalogEntry = { name: string; title: string; version: string; description: string; capabilities: string[]; needs_key: boolean; file: string };\nexport const sources = {\n  read: () => invoke<DigestSources>(''digest_sources'', {}),\n  catalog: async (): Promise<CatalogEntry[]> => {\n    const d = await jsonOrThrow(await fetch(''/api/plugins/catalog''), ''catalog'');\n    return (d?.plugins || []).filter((p: CatalogEntry) => p.capabilities?.includes(''search''));\n  },\n  installed: async (): Promise<Record<string, string>> => {\n    const d = await jsonOrThrow(await fetch(''/api/plugins''), ''plugins'');\n    const out: Record<string, string> = {};\n    for (const p of (d?.plugins || d || [])) if (p?.name) out[p.name] = p.status;\n    return out;\n  },\n  install: async (entry: CatalogEntry) => {\n    const m = await jsonOrThrow(await fetch(`/api/plugins/catalog/${entry.name}`), `catalog entry ${entry.name}`);\n    if (!m?.manifest) throw new Error(m?.error || `catalog entry ${entry.name} has no manifest`);\n    const r = await fetch(''/api/plugins/import'', { method: ''POST'', headers: { ''content-type'': ''application/json'' }, body: JSON.stringify({ manifest: m.manifest }) });\n    return jsonOrThrow(r, ''import'') as Promise<{ ok: boolean; status?: string; errors?: string[]; error?: string }>;\n  },\n  buildPrompt: async (): Promise<string> => {\n    try { const r = await fetch(''/api/knowledge/plugin-digest-build-a-source''); const d = await r.json(); return String(d?.doc?.body || d?.body || ''''); }\n    catch { return ''''; }\n  },\n};\n"},{"path":"digestBackground.ts","code":"// Background-safe digest generation.\n//\n// The naive `await api.generateDigest()` lives inside the Digest page\n// component. When the operator clicks \"regenerate\" and then navigates to\n// any other surface, the page unmounts — the local state (`generating`,\n// `lastGen`, the in-flight Promise''s then-handler) is destroyed. On\n// return the user sees a stale brief with no indication that anything is\n// running, even though the worker is still mid-fan-out.\n//\n// This module owns the lifecycle instead. The Promise lives at module\n// scope, survives every re-render and route change, and broadcasts state\n// transitions via a tiny pub-sub so any component (the Digest page, the\n// sidebar badge, a future toast) can mirror the same source of truth.\n//\n// API:\n//   start()             — kick off (idempotent: returns the in-flight\n//                         Promise if one is already running).\n//   getState()          — current snapshot.\n//   subscribe(cb)       — register for state changes; returns unsubscribe.\n//\n// State machine:\n//   idle  → running  → idle (with `result`)\n//   idle  → running  → idle (with `error`)\n\nimport { api } from ''./digest-data'';\n\nexport type DigestGenResult = {\n  generated: number;\n  // A fresh install has nothing to digest: the tool returns this instead of\n  // fabricating a brief, and the page turns it into \"talk to Nyo to onboard\".\n  onboarding_needed?: boolean;\n  note?: string;\n  // Stale items the prune-pass archived before this run (>7d, not starred,\n  // not urgency=1). Surfaced in the Brief header so the operator sees\n  // \"archived N stale\" alongside the +N adds.\n  pruned?: number;\n  per_source?: Record<string, { count: number; error: string | null; skipped?: string }>;\n  ms: number;\n  error?: string;\n  finished_at: number;\n};\n\nexport type DigestGenState = {\n  running: boolean;\n  started_at: number | null;        // ms-epoch when current run started (or last run if !running)\n  result: DigestGenResult | null;   // last finished run, success or failure\n};\n\nconst listeners = new Set<(s: DigestGenState) => void>();\nlet state: DigestGenState = { running: false, started_at: null, result: null };\nlet inflight: Promise<DigestGenResult> | null = null;\n\nfunction emit() {\n  const snap = state; // intentional reference copy — listeners see same object until next set\n  for (const cb of listeners) cb(snap);\n}\n\nfunction setState(patch: Partial<DigestGenState>) {\n  state = { ...state, ...patch };\n  emit();\n}\n\nexport function getDigestGenState(): DigestGenState {\n  return state;\n}\n\nexport function subscribeDigestGen(cb: (s: DigestGenState) => void): () => void {\n  listeners.add(cb);\n  return () => listeners.delete(cb);\n}\n\nexport function startDigestGeneration(): Promise<DigestGenResult> {\n  // Idempotent — if a run is in flight, hand back the same Promise so all\n  // callers resolve on the same finish event.\n  if (inflight) return inflight;\n  const t0 = Date.now();\n  setState({ running: true, started_at: t0, result: null });\n  inflight = (async () => {\n    try {\n      const r = await api.generateDigest();\n      const finished: DigestGenResult = {\n        generated: r.generated,\n        onboarding_needed: r.onboarding_needed,\n        note: r.note,\n        pruned: r.pruned,\n        per_source: r.per_source,\n        ms: Date.now() - t0,\n        finished_at: Date.now(),\n      };\n      setState({ running: false, result: finished });\n      return finished;\n    } catch (e) {\n      const finished: DigestGenResult = {\n        generated: 0,\n        ms: Date.now() - t0,\n        error: String((e as Error)?.message || e),\n        finished_at: Date.now(),\n      };\n      setState({ running: false, result: finished });\n      return finished;\n    } finally {\n      inflight = null;\n    }\n  })();\n  return inflight;\n}\n"},{"path":"DigestOnboarding.tsx","code":"// The opening screen of a new Digest: Nyo asks four questions and derives the\n// watched topics; beside it, the sources this install has, the ones it can\n// install in one click, and a prompt for building a new one.\nimport { useEffect, useState } from ''react'';\nimport { Chat } from ''../../components/Chat'';\nimport { sources, type DigestSources, type CatalogEntry } from ''./digest-data'';\n\nexport function DigestOnboarding({ onDone }: { onDone: () => void }) {\n  const [src, setSrc] = useState<DigestSources | null>(null);\n  const [catalog, setCatalog] = useState<CatalogEntry[]>([]);\n  const [installed, setInstalled] = useState<Record<string, string>>({});\n  const [busy, setBusy] = useState<string | null>(null);\n  const [err, setErr] = useState<string | null>(null);\n  const [prompt, setPrompt] = useState<string>('''');\n  const [copied, setCopied] = useState(false);\n\n  const load = async () => {\n    const [s, c, i] = await Promise.all([sources.read().catch(() => null), sources.catalog(), sources.installed().catch(() => ({}))]);\n    setSrc(s); setCatalog(c); setInstalled(i);\n  };\n  useEffect(() => { void load(); const t = setInterval(() => { void load(); }, 8000); return () => clearInterval(t); }, []);\n  useEffect(() => { if (src?.configured && src?.ready) onDone(); /* eslint-disable-next-line react-hooks/exhaustive-deps */ }, [src?.configured, src?.ready]);\n\n  const [note, setNote] = useState<string | null>(null);\n  const install = async (e: CatalogEntry) => {\n    setBusy(e.name); setErr(null); setNote(`Adding ${e.title}…`);\n    try {\n      const r = await sources.install(e);\n      if (!r.ok) { setErr(`${e.title}: ${(r.errors || [r.error || ''install refused'']).join(''; '')}`); setNote(null); }\n      else setNote(`${e.title} accepted (${r.status || ''bound''}). Building it now; this takes about a minute.`);\n    } catch (x) { setErr(`${e.title}: ${String((x as Error)?.message || x)}`); setNote(null); }\n    finally { setBusy(null); void load(); }\n  };\n  const copyPrompt = async () => {\n    const text = prompt || await sources.buildPrompt();\n    if (!prompt) setPrompt(text);\n    try { await navigator.clipboard.writeText(text); setCopied(true); setTimeout(() => setCopied(false), 1500); } catch { /* clipboard blocked */ }\n  };\n\n  return (\n    <div className=\"flex-1 min-h-0 flex flex-col lg:flex-row\">\n      <div className=\"flex-1 min-h-0 flex flex-col border-b lg:border-b-0 lg:border-r border-line\">\n        <div className=\"px-4 pt-4 pb-2 shrink-0 flex items-center justify-between\">\n          <p className=\"mono text-[9px] uppercase tracking-[0.16em] text-mute\">nyo · digest setup</p>\n          <button\n            onClick={() => { try { localStorage.removeItem(''nyyon.agent.digest.v1''); } catch { /* ignore */ } window.location.reload(); }}\n            className=\"mono text-[9px] uppercase tracking-[0.14em] text-mute hover:text-ink\">start over</button>\n        </div>\n        <Chat\n          agent=\"digest\"\n          autoStart=\"Let''s set up my digest.\"\n          placeholder=\"Answer in plain words\"\n          suggestions={[]}\n        />\n      </div>\n\n      <aside className=\"w-full lg:w-[280px] shrink-0 overflow-y-auto p-4 space-y-5\">\n        <section className=\"space-y-1.5\">\n          <p className=\"mono text-[9px] uppercase tracking-[0.16em] text-mute\">topics</p>\n          {src?.configured\n            ? src.topics.map((t) => <div key={t} className=\"text-[12.5px] text-ink truncate\">{t}</div>)\n            : <div className=\"text-[12px] text-mute\">none yet</div>}\n        </section>\n\n        <section className=\"space-y-1.5\">\n          <p className=\"mono text-[9px] uppercase tracking-[0.16em] text-mute\">sources</p>\n          {src?.providers.map((p) => (\n            <div key={p.slug} className=\"flex items-center justify-between gap-2 text-[12.5px]\">\n              <span className=\"text-ink truncate\">{p.label}</span>\n              <span className={''mono text-[9px] uppercase tracking-[0.14em] shrink-0 '' + (p.connected ? ''text-emerald-700 dark:text-emerald-400'' : ''text-rose-700 dark:text-rose-400'')}>{p.connected ? ''ready'' : ''needs key''}</span>\n            </div>\n          ))}\n          {src?.calendar && <div className=\"flex items-center justify-between text-[12.5px]\"><span className=\"text-ink\">Calendar</span><span className=\"mono text-[9px] uppercase tracking-[0.14em] text-emerald-700 dark:text-emerald-400\">ready</span></div>}\n          {catalog.filter((e) => installed[e.name] !== ''active'').map((e) => {\n            const st = installed[e.name];\n            const working = st && st !== ''blocked'' && st !== ''removed'';\n            return (\n              <div key={e.name} className=\"flex items-center justify-between gap-2 text-[12.5px]\">\n                <span className=\"text-mute truncate\">{e.title}{e.needs_key ? <span className=\"mono text-[9px] uppercase tracking-[0.14em] ml-1.5\">key</span> : null}</span>\n                {working\n                  ? <span className=\"mono text-[9px] uppercase tracking-[0.14em] text-mute shrink-0\">{st}…</span>\n                  : <button onClick={() => void install(e)} disabled={busy === e.name} className=\"text-[11px] px-2.5 py-0.5 rounded-sm bg-ink text-paper disabled:opacity-40 shrink-0\">{busy === e.name ? ''…'' : ''add''}</button>}\n              </div>\n            );\n          })}\n          {note && <p className=\"text-[11px] text-emerald-700 dark:text-emerald-400 leading-snug\">{note}</p>}\n          {err && <p className=\"text-[11px] text-rose-700 dark:text-rose-400 leading-snug\">{err}</p>}\n        </section>\n\n        <section className=\"space-y-1.5\">\n          <p className=\"mono text-[9px] uppercase tracking-[0.16em] text-mute\">build your own</p>\n          <button onClick={() => void copyPrompt()} className=\"text-[11px] px-2.5 py-0.5 rounded-sm hairline bg-paper hover:bg-card\">{copied ? ''copied'' : ''copy the prompt''}</button>\n        </section>\n      </aside>\n    </div>\n  );\n}\n"}],"page_code":"// Digest plugin: morning brief page.\n// Pulls search headlines for the operator''s topics and the calendar\n// look-ahead into one feed.\n// Layout: hero (date + counts + \"generate\" button), then three urgency-grouped\n// sections (Action needed / This week / Background). Each card surfaces a\n// clear action, the source, and one-click mark-read / star / open.\n\nimport { useEffect, useMemo, useState } from ''react'';\nimport { api, parseMeta, type DigestItem, type DigestStats, type DigestKind } from ''./digest-data'';\nimport { DigestItemDrawer } from ''./DigestItemDrawer'';\nimport { DigestOnboarding } from ''./DigestOnboarding'';\nimport { sources as sourcesApi, type DigestSources } from ''./digest-data'';\nimport { Coffee, Star, X, Sparkle, Clock } from ''../../components/Icons'';\nimport {\n  getDigestGenState,\n  subscribeDigestGen,\n  startDigestGeneration,\n  type DigestGenState,\n} from ''./digestBackground'';\n\nconst KIND_TONE: Record<DigestKind, string> = {\n  news:        ''bg-sky-100     text-sky-800'',\n  note:        ''bg-stone-100   text-stone-700'',\n  opportunity: ''bg-amber-100   text-amber-900'',\n};\nconst KIND_LABEL: Record<DigestKind, string> = {\n  news:        ''news'',\n  note:        ''note'',\n  opportunity: ''opportunity'',\n};\n\n// Category filters for the brief feed. CLIENT-SIDE predicates over the\n// loaded items: the API returns everything (it only filters unread/starred\n// server-side), so all category narrowing happens here.\n//\n// Calendar events are stored under kind ''opportunity'' (see pullCalendar in\n// lib/digest.mjs) and are only distinguishable by ref_kind ===\n// ''calendar_events''. So Calendar matches on ref_kind, and \"Opportunities\"\n// explicitly excludes calendar rows to avoid double-counting.\ntype CatKey = ''news'' | ''opportunity'' | ''calendar'' | ''note'';\n\nconst CATEGORIES: { key: CatKey; label: string; dot: string; match: (it: DigestItem) => boolean }[] = [\n  { key: ''news'',        label: ''News'',          dot: ''bg-sky-500'',    match: (i) => i.kind === ''news'' },\n  { key: ''opportunity'', label: ''Opportunities'', dot: ''bg-amber-500'',  match: (i) => i.kind === ''opportunity'' && i.ref_kind !== ''calendar_events'' },\n  { key: ''calendar'',    label: ''Calendar'',      dot: ''bg-orange-500'', match: (i) => i.ref_kind === ''calendar_events'' },\n  { key: ''note'',        label: ''Notes'',         dot: ''bg-stone-400'',  match: (i) => i.kind === ''note'' },\n];\n\nfunction timeAgo(ts: number): string {\n  const s = Math.floor((Date.now() - ts) / 1000);\n  if (s < 60)    return ''just now'';\n  if (s < 3600)  return `${Math.floor(s / 60)}m`;\n  if (s < 86400) return `${Math.floor(s / 3600)}h`;\n  return `${Math.floor(s / 86400)}d`;\n}\n\nfunction todayLabel(): string {\n  // Day + hour-minute, e.g. \"Sunday, May 31 · 4:52 PM\". The hour anchors\n  // the brief to the operator''s current moment.\n  const d = new Date();\n  const day  = d.toLocaleDateString(undefined, { weekday: ''long'', month: ''long'', day: ''numeric'' });\n  const time = d.toLocaleTimeString(undefined, { hour: ''numeric'', minute: ''2-digit'' });\n  return `${day} · ${time}`;\n}\n\nexport default function Digest() {\n  // The digest IS the brief. What feeds it is whatever this install has\n  // (probed at generate time); the knobs that matter live in Knowledge\n  // (topics, policy), not in a toggle grid.\n  return (\n    <div className=\"h-full flex flex-col\">\n      <BriefPane />\n    </div>\n  );\n}\n\nfunction BriefPane() {\n  const [items, setItems]   = useState<DigestItem[] | null>(null);\n  const [stats, setStats]   = useState<DigestStats | null>(null);\n  const [hideRead, setHideRead] = useState(true);\n  // Generation state lives in digestBackground.ts: the in-flight Promise\n  // survives sidebar nav so the user can leave and come back to a\n  // still-running (or just-finished) run.\n  const [gen, setGen] = useState<DigestGenState>(() => getDigestGenState());\n  const [activeItem, setActiveItem] = useState<DigestItem | null>(null);\n  // A new digest opens on Nyo: until topics exist and a search source is\n  // installed, the onboarding screen IS the page.\n  const [src, setSrc] = useState<DigestSources | null>(null);\n  const [srcFailed, setSrcFailed] = useState(false);\n  const [skipOnboarding, setSkipOnboarding] = useState(false);\n  // Keep asking. A plugin install rebuilds and reloads the app, and one failed\n  // read during that window used to pin the page on the brief for good.\n  useEffect(() => {\n    let alive = true;\n    const tick = () => sourcesApi.read().then((r) => { if (alive) { setSrc(r); setSrcFailed(false); } }).catch(() => { if (alive) setSrcFailed(true); });\n    void tick();\n    const t = setInterval(tick, 8000);\n    return () => { alive = false; clearInterval(t); };\n  }, []);\n  // Active category filters (multi-select). Empty set = show everything.\n  // Deliberately NOT persisted: a category filter is a transient view.\n  const [cats, setCats] = useState<Set<CatKey>>(new Set());\n  function toggleCat(k: CatKey) {\n    setCats((prev) => {\n      const next = new Set(prev);\n      if (next.has(k)) next.delete(k); else next.add(k);\n      return next;\n    });\n  }\n  // Time window: ''all'' (default) or the last 24h. Composes with the\n  // category chips (AND). Like a category, an active window shows read +\n  // unread within it, so the unread toggle only governs the plain view.\n  const [timeWin, setTimeWin] = useState<''all'' | ''24h''>(''all'');\n  function clearFilters() { setCats(new Set()); setTimeWin(''all''); }\n\n  async function refresh() {\n    // Load the FULL set (read + unread) and do the unread narrowing on the\n    // client, so category filters can reach items the operator has already\n    // read. The backend hard-deletes rows older than delete_after_days, so\n    // the table stays well under this cap.\n    const [it, st] = await Promise.all([\n      api.listDigest({ limit: 1500 }),\n      api.digestStats(),\n    ]);\n    setItems(it);\n    setStats(st);\n  }\n  useEffect(() => { refresh(); /* eslint-disable-next-line react-hooks/exhaustive-deps */ }, []);\n  // Ongoing feed: cron-inserted cards appear on their own, no Generate\n  // click, no navigation needed.\n  useEffect(() => {\n    const t = setInterval(() => { refresh(); }, 60 * 1000);\n    return () => clearInterval(t);\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, []);\n\n  // Track the background-generation singleton. When a run settles we just\n  // refresh the list: newly-pulled items are unread, so they appear at the\n  // top of the default \"showing unread\" feed on their own.\n  useEffect(() => {\n    const unsub = subscribeDigestGen((s) => {\n      setGen(s);\n      if (!s.running && s.result) refresh();\n    });\n    return unsub;\n    /* eslint-disable-next-line react-hooks/exhaustive-deps */\n  }, []);\n\n  function generate() {\n    // Fire-and-forget: the singleton handles the lifecycle. A click during\n    // an in-flight run is a no-op (returns the same Promise).\n    startDigestGeneration();\n  }\n\n  const generating   = gen.running;\n  const genStartedAt = gen.running ? gen.started_at : null;\n  const lastGen      = gen.result;\n\n  // Re-render once a second so \"updated 3m ago\" keeps ticking and the\n  // in-flight elapsed counter advances without a refetch.\n  const [, setTick] = useState(0);\n  useEffect(() => {\n    const t = setInterval(() => setTick((n) => n + 1), 1000);\n    return () => clearInterval(t);\n  }, []);\n\n  async function markRead(id: string) {\n    await api.patchDigestItem(id, { read: true });\n    refresh();\n  }\n  async function toggleStar(id: string, on: boolean) {\n    await api.patchDigestItem(id, { starred: !on });\n    refresh();\n  }\n\n  // Per-category TOTALS (read + unread) over the loaded set: the badge on a\n  // chip is \"how many cards a click surfaces\". Categories are mutually\n  // exclusive (break after the first match).\n  const catCounts = useMemo(() => {\n    const c = Object.fromEntries(CATEGORIES.map((cat) => [cat.key, 0])) as Record<CatKey, number>;\n    for (const it of items || []) {\n      for (const cat of CATEGORIES) {\n        if (cat.match(it)) { c[cat.key]++; break; }\n      }\n    }\n    return c;\n  }, [items]);\n\n  // Build the visible list. The unread toggle governs ONLY the plain default\n  // view; any explicit filter surfaces read + unread within it.\n  const filtered = useMemo(() => {\n    if (!items) return [] as DigestItem[];\n    let list: DigestItem[] = items;\n    if (cats.size > 0) {\n      list = list.filter((it) => CATEGORIES.some((c) => cats.has(c.key) && c.match(it)));\n    }\n    if (timeWin === ''24h'') {\n      const cutoff = Date.now() - 24 * 60 * 60 * 1000;\n      list = list.filter((it) => it.created_at >= cutoff);\n    }\n    if (cats.size === 0 && timeWin === ''all'' && hideRead) {\n      list = list.filter((it) => it.read_at === null);\n    }\n    return list;\n  }, [items, cats, hideRead, timeWin]);\n\n  const grouped = useMemo(() => {\n    const high: DigestItem[] = [];\n    const mid:  DigestItem[] = [];\n    const low:  DigestItem[] = [];\n    const done: DigestItem[] = [];\n    for (const it of filtered) {\n      // Dismissed (read) cards sink to the bottom section instead of holding\n      // their spot in the urgency groups.\n      if (it.read_at !== null) done.push(it);\n      else if (it.urgency === 1) high.push(it);\n      else if (it.urgency === 2) mid.push(it);\n      else low.push(it);\n    }\n    // Most recently dismissed first, so the card you just dismissed is findable.\n    done.sort((a, b) => (b.read_at || 0) - (a.read_at || 0));\n    // Within each urgency group, scored cards order by relevance\n    // (meta.priority); unscored items keep their recency order below.\n    const pr = (it: DigestItem) => Number(parseMeta(it).priority ?? -1);\n    for (const g of [high, mid, low]) g.sort((a, b) => pr(b) - pr(a));\n    return { high, mid, low, done };\n  }, [filtered]);\n\n  // Count of items that landed in the brief in the last 24h (read + unread).\n  const last24hCount = useMemo(() => {\n    if (!items) return 0;\n    const cutoff = Date.now() - 24 * 60 * 60 * 1000;\n    let n = 0;\n    for (const it of items) if (it.created_at >= cutoff) n++;\n    return n;\n  }, [items]);\n\n  // Any explicit filter (a category or the time window) is active: the\n  // unread toggle does not apply and its control goes inert.\n  const hasExplicit = cats.size > 0 || timeWin === ''24h'';\n\n  // Sources unknown yet (first read, or the app is mid-rebuild): a quiet\n  // holding state, never the brief pretending to be the answer.\n  if (!src && !skipOnboarding && (items?.length ?? 0) === 0) {\n    return (\n      <div className=\"flex-1 min-h-0 grid place-items-center text-[12px] text-mute\">\n        {srcFailed ? ''Reconnecting…'' : ''Loading…''}\n      </div>\n    );\n  }\n  if (src && !src.ready && !skipOnboarding && (items?.length ?? 0) === 0) {\n    return (\n      <div className=\"flex-1 min-h-0 flex flex-col\">\n        <DigestOnboarding onDone={() => { sourcesApi.read().then(setSrc).catch(() => {}); refresh(); }} />\n        <div className=\"px-4 py-1.5 border-t border-line text-[11px] text-mute shrink-0\">\n          <button className=\"underline underline-offset-2 hover:text-ink\" onClick={() => setSkipOnboarding(true)}>Skip to the brief</button>\n        </div>\n      </div>\n    );\n  }\n  return (\n    <div className=\"flex-1 flex flex-col min-h-0\">\n      <header className=\"px-4 sm:px-6 py-3 sm:py-5 border-b border-line bg-paper/60 shrink-0\">\n        <div className=\"flex items-baseline justify-between flex-wrap gap-2 sm:gap-4\">\n          <div>\n            <div className=\"hidden sm:flex items-center gap-2 mono text-[10px] uppercase tracking-[0.2em] text-mute mb-1\">\n              <Coffee size={12} />\n              <span>{todayLabel()}</span>\n              {stats?.last_generated_at && (() => {\n                const ago = timeAgo(stats.last_generated_at);\n                const label = ago === ''just now'' ? ''updated just now'' : `updated ${ago} ago`;\n                return (\n                  <>\n                    <span className=\"text-mute/50\">·</span>\n                    <span title={new Date(stats.last_generated_at).toLocaleString()}>{label}</span>\n                  </>\n                );\n              })()}\n            </div>\n            <h1 className=\"text-lg sm:text-2xl font-semibold tracking-tight\">\n              {stats?.unread ? `${stats.unread} thing${stats.unread === 1 ? '''' : ''s''} for you today` : ''All caught up''}\n            </h1>\n            {stats && (\n              <p className=\"text-xs text-mute mt-1\">\n                {stats.action_count > 0 && <span><span className=\"text-rose-700 font-medium\">{stats.action_count}</span> need action</span>}\n                {stats.action_count > 0 && stats.high > 0 && <span> · </span>}\n                {stats.high > 0 && <span><span className=\"text-rose-700\">{stats.high}</span> high urgency</span>}\n                {stats.starred > 0 && <span> · {stats.starred} starred</span>}\n              </p>\n            )}\n          </div>\n          <div className=\"flex items-center gap-2\">\n            <button\n              onClick={() => setHideRead(!hideRead)}\n              disabled={hasExplicit}\n              title={hasExplicit ? ''A category or time filter shows all its items. Clear it to filter by unread'' : undefined}\n              className={\n                ''h-9 px-3 rounded-sm hairline mono text-[10px] uppercase tracking-[0.18em] transition '' +\n                (hasExplicit\n                  ? ''bg-card text-mute opacity-60''\n                  : hideRead ? ''bg-card text-mute hover:text-ink'' : ''bg-ink text-paper'')\n              }\n            >\n              {hasExplicit || !hideRead ? ''showing all'' : ''showing unread''}\n            </button>\n            <button\n              onClick={generate}\n              disabled={generating}\n              className={\n                ''inline-flex items-center gap-1.5 h-9 px-3 rounded-sm hairline mono text-[10px] uppercase tracking-[0.18em] transition '' +\n                (generating\n                  ? ''bg-ink text-paper opacity-90''\n                  : ''bg-ink text-paper hover:opacity-90 disabled:opacity-40'')\n              }\n            >\n              <Sparkle size={12} className={generating ? ''animate-spin'' : ''''} />\n              {generating ? ''scanning...'' : ''generate''}\n            </button>\n          </div>\n        </div>\n        {/* Filter bar: a TIME window (24h) set apart by a divider, then\n            CATEGORY chips (multi-select, \"all\" clears them). Both compose\n            (AND). Empty categories render dimmed + disabled. */}\n        {items && items.length > 0 && (\n          <div className=\"mt-3 flex items-center gap-1.5 flex-nowrap overflow-x-auto pb-1 -mx-4 px-4 sm:mx-0 sm:px-0 sm:pb-0 sm:flex-wrap sm:overflow-visible\">\n            <button\n              onClick={() => setTimeWin(timeWin === ''24h'' ? ''all'' : ''24h'')}\n              title=\"Everything that landed in the brief in the last 24 hours\"\n              className={\n                ''shrink-0 whitespace-nowrap inline-flex items-center gap-1.5 h-7 px-2.5 rounded-sm hairline mono text-[10px] uppercase tracking-[0.15em] transition '' +\n                (timeWin === ''24h'' ? ''bg-ink text-paper'' : ''bg-card text-mute hover:text-ink'')\n              }\n            >\n              <Clock size={11} />\n              24h\n              <span className={timeWin === ''24h'' ? ''text-paper/60'' : ''text-mute/60''}>{last24hCount}</span>\n            </button>\n            <span className=\"mx-1 h-4 w-px bg-line shrink-0\" />\n            <button\n              onClick={() => setCats(new Set())}\n              className={\n                ''shrink-0 whitespace-nowrap h-7 px-2.5 rounded-sm hairline mono text-[10px] uppercase tracking-[0.15em] transition '' +\n                (cats.size === 0 ? ''bg-ink text-paper'' : ''bg-card text-mute hover:text-ink'')\n              }\n            >\n              all\n            </button>\n            {CATEGORIES.map((c) => {\n              const on    = cats.has(c.key);\n              const empty = catCounts[c.key] === 0;\n              return (\n                <button\n                  key={c.key}\n                  onClick={() => toggleCat(c.key)}\n                  disabled={empty && !on}\n                  className={\n                    ''shrink-0 whitespace-nowrap inline-flex items-center gap-1.5 h-7 px-2.5 rounded-sm hairline mono text-[10px] uppercase tracking-[0.15em] transition '' +\n                    (on\n                      ? ''bg-ink text-paper''\n                      : empty\n                        ? ''bg-card text-mute/40 cursor-not-allowed''\n                        : ''bg-card text-mute hover:text-ink'')\n                  }\n                >\n                  <span className={''h-1.5 w-1.5 rounded-full '' + c.dot + (on || !empty ? '''' : '' opacity-40'')} />\n                  {c.label}\n                  <span className={on ? ''text-paper/60'' : ''text-mute/60''}>{catCounts[c.key]}</span>\n                </button>\n              );\n            })}\n          </div>\n        )}\n        {/* Live progress strip: visible while a run is in flight and sticks\n            around after so the operator can read the result. */}\n        {(generating || lastGen) && (\n          <div className=\"mt-3 flex items-baseline gap-3 flex-wrap text-[11px]\">\n            {generating ? (\n              <span className=\"inline-flex items-center gap-1.5 text-ink\">\n                <span className=\"h-1.5 w-1.5 rounded-full bg-ink animate-pulse\" />\n                Scanning sources{genStartedAt ? <span className=\"text-mute mono\"> · {Math.max(0, Math.floor((Date.now() - genStartedAt) / 1000))}s</span> : null}\n              </span>\n            ) : lastGen?.onboarding_needed ? (\n              <span className=\"text-ink\">\n                Nothing to digest yet: this install is not onboarded. {'' ''}\n                <button\n                  className=\"underline underline-offset-2 hover:opacity-80\"\n                  onClick={() => window.dispatchEvent(new CustomEvent(''nyyon:nav-to'', { detail: { target: ''nyo'' } }))}\n                >Talk to Nyo to onboard</button>\n                {'' ''}(add a search provider and your topics, or connect the calendar) and the brief fills on its own.\n              </span>\n            ) : lastGen ? (\n              <>\n                <span className={lastGen.error ? ''text-rose-700'' : lastGen.generated > 0 ? ''text-emerald-700'' : ''text-mute''}>\n                  {lastGen.error\n                    ? ''Generate failed''\n                    : lastGen.generated > 0\n                      ? `Pulled ${lastGen.generated} new item${lastGen.generated === 1 ? '''' : ''s''}`\n                      : ''No new activity (everything already in the brief)''}\n                  {typeof lastGen.pruned === ''number'' && lastGen.pruned > 0 && (\n                    <span className=\"text-mute\"> · archived {lastGen.pruned} stale</span>\n                  )}\n                  <span className=\"text-mute mono\"> · {lastGen.ms}ms</span>\n                </span>\n                {lastGen.per_source && (\n                  <span className=\"flex items-center gap-2 mono text-mute\">\n                    {Object.entries(lastGen.per_source).map(([src, info]) => (\n                      <span key={src} className={info.error ? ''text-rose-700'' : info.count > 0 ? ''text-emerald-700'' : ''''}>\n                        {src}{info.error ? '' !'' : ''''} +{info.count}\n                        {info.skipped && <span className=\"text-mute/70\"> ({info.skipped})</span>}\n                      </span>\n                    ))}\n                  </span>\n                )}\n                {lastGen.error && (\n                  <span className=\"text-rose-700\">{lastGen.error}</span>\n                )}\n              </>\n            ) : null}\n          </div>\n        )}\n      </header>\n\n      <div className=\"flex-1 overflow-y-auto\">\n        <div className=\"max-w-3xl mx-auto px-4 sm:px-6 py-6 space-y-8 overflow-x-hidden\">\n          {!items && <div className=\"text-sm text-mute\">Loading...</div>}\n          {items && filtered.length === 0 && (\n            hasExplicit ? (\n              <div className=\"text-center py-16 space-y-3\">\n                <div className=\"text-4xl\">🔍</div>\n                <div className=\"text-sm text-mute\">\n                  {timeWin === ''24h'' && cats.size === 0 ? ''Nothing new in the last 24 hours.'' : ''Nothing in this filter right now.''}{'' ''}\n                  <button className=\"text-ink underline underline-offset-2\" onClick={clearFilters}>Clear filters</button>\n                </div>\n              </div>\n            ) : hideRead && items.length > 0 ? (\n              // Rows exist but they are all read: the \"all caught up\" reward.\n              <div className=\"text-center py-16 space-y-3\">\n                <div className=\"text-4xl\">☕</div>\n                <div className=\"text-sm text-mute\">\n                  You are all caught up, nothing unread.{'' ''}\n                  <button className=\"text-ink underline underline-offset-2\" onClick={() => setHideRead(false)}>Show {items.length} read item{items.length === 1 ? '''' : ''s''}</button>\n                </div>\n              </div>\n            ) : (\n              // Genuinely empty brief (fresh install / everything cleared).\n              <div className=\"text-center py-16 space-y-3\">\n                <div className=\"text-4xl\">☕</div>\n                <div className=\"text-sm text-mute\">Nothing in the brief yet. Hit <span className=\"text-ink\">Generate</span>.</div>\n              </div>\n            )\n          )}\n\n          <Section title=\"Action needed\" tone=\"high\" items={grouped.high} onRead={markRead} onStar={toggleStar} onOpen={setActiveItem} />\n          <Section title=\"This week\"     tone=\"mid\"  items={grouped.mid}  onRead={markRead} onStar={toggleStar} onOpen={setActiveItem} />\n          <Section title=\"Background\"    tone=\"low\"  items={grouped.low}  onRead={markRead} onStar={toggleStar} onOpen={setActiveItem} />\n          <Section title=\"Dismissed\"     tone=\"low\"  items={grouped.done} onRead={markRead} onStar={toggleStar} onOpen={setActiveItem} />\n        </div>\n      </div>\n      {activeItem && (\n        <DigestItemDrawer\n          item={activeItem}\n          onClose={() => setActiveItem(null)}\n          onChange={() => { refresh(); }}\n        />\n      )}\n    </div>\n  );\n}\n\nfunction Section({\n  title, tone, items, onRead, onStar, onOpen,\n}: {\n  title: string;\n  tone: ''high'' | ''mid'' | ''low'';\n  items: DigestItem[];\n  onRead: (id: string) => void;\n  onStar: (id: string, on: boolean) => void;\n  onOpen: (item: DigestItem) => void;\n}) {\n  if (items.length === 0) return null;\n  const dotTone = tone === ''high'' ? ''bg-rose-500'' : tone === ''mid'' ? ''bg-amber-500'' : ''bg-stone-400'';\n  return (\n    <section>\n      <div className=\"flex items-center gap-2 mb-3 mono text-[10px] uppercase tracking-[0.2em] text-mute\">\n        <span className={''h-1.5 w-1.5 rounded-full '' + dotTone} />\n        <span>{title}</span>\n        <span className=\"text-mute/60\">· {items.length}</span>\n      </div>\n      <ul className=\"space-y-2\">\n        {items.map((it) => <Card key={it.id} item={it} onRead={onRead} onStar={onStar} onOpen={onOpen} />)}\n      </ul>\n    </section>\n  );\n}\n\nfunction Card({\n  item, onRead, onStar, onOpen,\n}: {\n  item: DigestItem;\n  onRead: (id: string) => void;\n  onStar: (id: string, on: boolean) => void;\n  onOpen: (item: DigestItem) => void;\n}) {\n  const starred = item.starred === 1;\n  const isRead  = item.read_at !== null;\n  // A news card''s primary act is READ the source; internal cards (calendar,\n  // opportunities, notes) open the drawer.\n  const isExternal = item.kind === ''news'';\n  const meta = parseMeta(item);\n  // Stops icon-button clicks from bubbling to the card-level open handler.\n  const stop = (e: React.MouseEvent) => e.stopPropagation();\n\n  // Headlines can arrive as \"Outlet: headline\"; the outlet already shows on\n  // the badge/host, so strip the prefix for a clean read.\n  const title = isExternal ? item.title.replace(/^[^:]{1,24}:\\s+/, '''') : item.title;\n  // The scorer''s verdict: score chip + its one-line reason. A local override\n  // reflects a feedback-triggered rescore without a full reload.\n  const [prioLocal, setPrioLocal] = useState<{ score: number; reason: string } | null>(null);\n  const [prioOpen, setPrioOpen] = useState(false);\n  const [prioComment, setPrioComment] = useState('''');\n  const [prioBusy, setPrioBusy] = useState(false);\n  const [prioNote, setPrioNote] = useState<string | null>(null);\n  const prio = prioLocal ? prioLocal.score : (typeof meta.priority === ''number'' ? meta.priority : null);\n  const prioReason = prioLocal ? prioLocal.reason : (meta.priority_reason || '''');\n  async function sendPrioFeedback() {\n    const c = prioComment.trim();\n    if (!c || prioBusy) return;\n    setPrioBusy(true); setPrioNote(null);\n    try {\n      const r = await api.digestPriorityFeedback(item.id, c);\n      if (r.error) { setPrioNote(r.error); return; }\n      if (r.rescored?.ok && typeof r.rescored.score === ''number'') {\n        setPrioLocal({ score: r.rescored.score, reason: r.rescored.reason || '''' });\n      }\n      setPrioComment('''');\n      setPrioNote(`learned (${r.rules} taste rules) and rescored`);\n    } catch (e) { setPrioNote(e instanceof Error ? e.message : String(e)); }\n    finally { setPrioBusy(false); }\n  }\n  const host = (() => {\n    if (!item.source_url) return null;\n    try { return new URL(item.source_url).host.replace(/^www\\./, ''''); } catch { return null; }\n  })();\n  // Calendar events are stored kind=''opportunity'' but are their own category\n  // (matched on ref_kind). Give them a distinct label/tone.\n  const isCal = item.ref_kind === ''calendar_events'';\n  const tone  = isCal ? ''bg-orange-100 text-orange-900'' : (KIND_TONE[item.kind]  || ''bg-stone-100 text-stone-700'');\n  const label = isCal ? ''calendar'' : (KIND_LABEL[item.kind] || String(item.kind));\n  return (\n    <li\n      onClick={() => onOpen(item)}\n      className={\n        ''group hairline rounded-sm bg-card/80 p-4 transition hover:border-ink/40 cursor-pointer '' +\n        (isRead ? (isExternal ? ''opacity-75'' : ''opacity-60'') : '''') +\n        (item.urgency === 1 ? '' border-l-2 border-l-rose-500'' : '''')\n      }\n    >\n      <div className=\"flex items-baseline gap-2 mb-2 flex-wrap\">\n        {prio !== null && (\n          <button\n            type=\"button\"\n            onClick={(e) => { stop(e); setPrioOpen((v) => !v); }}\n            title={prioReason}\n            className={''mono text-[9px] px-1.5 py-0.5 rounded-sm hairline hover:bg-card transition cursor-pointer shrink-0 '' + (item.urgency === 1 ? ''text-rose-700'' : item.urgency === 2 ? ''text-amber-700'' : ''text-mute'')}\n          >\n            P{prio}\n          </button>\n        )}\n        <span className={''mono text-[9px] uppercase tracking-[0.18em] px-1.5 py-0.5 rounded-sm shrink-0 '' + tone}>\n          {label}\n        </span>\n        <span className=\"text-[11px] text-mute truncate\">{isExternal ? (host || item.source_label) : item.source_label}</span>\n        <span className=\"text-[10px] text-mute mono\">· {timeAgo(item.created_at)}</span>\n\n        <span className=\"ml-auto flex items-center gap-1\" onClick={stop}>\n          {/* Star stays subtle (reveals on hover): it is the rarer action. */}\n          <button\n            onClick={(e) => { stop(e); onStar(item.id, starred); }}\n            aria-label={starred ? ''Unstar'' : ''Star''}\n            title={starred ? ''Unstar'' : ''Star''}\n            className={''h-7 w-7 grid place-items-center rounded-sm transition '' + (starred ? ''text-amber-500 hover:text-amber-600'' : ''text-mute opacity-0 group-hover:opacity-100 hover:text-ink'')}\n          >\n            <Star size={14} className={starred ? ''fill-current'' : ''''} />\n          </button>\n          {/* Dismiss is ALWAYS visible so \"close out a card I do not care\n              about\" is one obvious click. */}\n          {!isRead && (\n            <button\n              onClick={(e) => { stop(e); onRead(item.id); }}\n              aria-label=\"Dismiss, not interesting\"\n              title=\"Dismiss, not interesting\"\n              className=\"h-7 w-7 grid place-items-center rounded-sm text-mute/70 hover:text-rose-600 hover:bg-rose-50 transition\"\n            >\n              <X size={14} />\n            </button>\n          )}\n        </span>\n      </div>\n      <div dir=\"auto\" className=\"text-[14px] text-ink font-medium leading-snug break-words\">{title}</div>\n      {item.summary && (\n        <p dir=\"auto\" className=\"text-[12px] text-mute mt-1.5 leading-relaxed line-clamp-3 break-words\">{item.summary}</p>\n      )}\n      <div className=\"mt-3 flex items-center gap-3 flex-wrap\" onClick={stop}>\n        {prio !== null && prioReason ? (\n          <div dir=\"auto\" className=\"mt-1 text-[11px] leading-snug text-mute italic\">\n            {prioReason}\n          </div>\n        ) : null}\n        {prioOpen ? (\n          <div onClick={stop} className=\"mt-2 rounded-sm hairline bg-paper p-2 space-y-1.5\">\n            <div className=\"flex items-center justify-between\">\n              <span className=\"mono text-[9px] uppercase tracking-[0.18em] text-mute\">why P{prio}</span>\n              <button\n                type=\"button\"\n                onClick={() => {\n                  sessionStorage.setItem(''nyyon:open-doc'', ''plugin-digest-signal-priority'');\n                  window.dispatchEvent(new CustomEvent(''nyyon:nav-to'', { detail: { target: ''knowledge'' } }));\n                  window.dispatchEvent(new CustomEvent(''nyyon:knowledge-open'', { detail: { slug: ''plugin-digest-signal-priority'' } }));\n                }}\n                className=\"mono text-[9px] uppercase tracking-[0.16em] text-mute hover:text-ink transition\"\n                title=\"the plugin-digest-signal-priority knowledge doc: rubric, thresholds, and your learned taste rules\"\n              >\n                rules\n              </button>\n            </div>\n            <div dir=\"auto\" className=\"text-[12px] leading-snug\">{prioReason || ''no reason recorded''}</div>\n            <textarea\n              dir=\"auto\"\n              value={prioComment}\n              onChange={(e) => setPrioComment(e.target.value)}\n              rows={2}\n              placeholder=\"disagree? say why, the scorer learns your taste\"\n              className=\"w-full resize-y rounded-sm hairline bg-card/40 px-2 py-1.5 text-[12px] leading-snug focus:border-ink focus:outline-none transition\"\n            />\n            <div className=\"flex items-center justify-between gap-2\">\n              <span className=\"mono text-[9px] uppercase tracking-[0.16em] text-mute\">{prioNote || ''''}</span>\n              <button\n                type=\"button\"\n                disabled={prioBusy || !prioComment.trim()}\n                onClick={sendPrioFeedback}\n                className=\"mono text-[10px] uppercase tracking-[0.18em] bg-ink text-paper rounded-sm px-2.5 py-1 hover:opacity-90 disabled:opacity-40 transition\"\n              >\n                {prioBusy ? ''learning...'' : ''teach''}\n              </button>\n            </div>\n          </div>\n        ) : null}\n        {isExternal ? (\n          item.source_url && (\n            <a\n              href={item.source_url}\n              target=\"_blank\"\n              rel=\"noreferrer\"\n              className=\"inline-flex items-center gap-1.5 mono text-[10px] uppercase tracking-[0.18em] bg-ink text-paper rounded-sm px-2.5 py-1 hover:opacity-90 transition\"\n              title=\"Open the source\"\n            >\n              Read ↗\n            </a>\n          )\n        ) : (\n          <>\n            <button\n              onClick={(e) => { stop(e); onOpen(item); }}\n              className=\"inline-flex items-center gap-1.5 mono text-[10px] uppercase tracking-[0.18em] bg-ink text-paper rounded-sm px-2.5 py-1 hover:opacity-90 transition\"\n              title=\"Open the panel for this item\"\n            >\n              <Sparkle size={12} />\n              Open\n            </button>\n            {item.suggested_action && (\n              <span className=\"inline-flex items-center mono text-[10px] uppercase tracking-[0.18em] text-ink bg-paper hairline rounded-sm px-2 py-1\">\n                {item.suggested_action}\n              </span>\n            )}\n            {item.source_url && (\n              <a\n                href={item.source_url}\n                target=\"_blank\"\n                rel=\"noreferrer\"\n                className=\"mono text-[10px] uppercase tracking-[0.18em] text-mute hover:text-ink\"\n              >\n                open link ↗\n              </a>\n            )}\n          </>\n        )}\n      </div>\n    </li>\n  );\n}\n"}]}}', '{"llm":{"via":"host","target":"llm","modes":["json","text"]},"setup":{"via":"host","target":"setup","modes":["read"]},"web":{"via":"host","target":"web","modes":["text"]}}', '{"step":"bundled"}', 1788437398264, 1788437398264)
